\hypertarget{proof:full_info}{} 
\Proof{prop:full_info}{
 First, I derive the optimal rule using each of the three approaches or show how to obtain it; then, I establish the equivalence of each method to the KKT characterization derived in the first step. 
 \begin{enumerate}

	\item Karush-Kuhn-Tucker Conditions. The Lagrangian is given by:
	\begin{align*}
		\mathcal{L} (\boldsymbol{\tau}, \lambda, \mu_1, ..., \mu_n)  = \sum_{i=1}^{n}   \Big( z-y_{i}-\tau_{i} \Big)^{2}+ \lambda \Big( \sum_{i=1}^{n} \tau_{i} - B  \Big) - \sum_{i=1}^{n} \xi_{i} \tau_i  \text{. }
	\end{align*}
	 Since the problem is strictly convex and has affine constraints, the KKT conditions are both necessary and sufficient for optimality. I check the KKT conditions below:
	 \begin{itemize}

		\item \underline{Stacionarity Conditions} For each $i$,
		\begin{align}
			\frac{\partial \mathcal{L}}{\partial \tau_i} & = - 2(z-y_i - \tau_i) + \lambda - \xi_i = 0 \tag{SC}
		\end{align}

		\item \underline{Primal feasibility}
		\begin{align}
			\sum_{i=1}^{n} \tau_i \leq B \text{,  } \tau_{i} \geq 0, \forall i \tag{PF}
		\end{align}

		\item \underline{Dual feasibility}
		\begin{align}
			\lambda \geq 0 \text{,  } \xi_{i} \geq 0, \forall i \tag{DF}
		\end{align}

		\item \underline{Complementary slackness}
		\begin{align}
			\lambda \Big( \sum_{i=1}^{n} \tau_i - B \Big) =0 \text{,  } \xi_i \tau_i = 0, \forall i \tag{CS}
		\end{align}

	 \end{itemize}
	From (SC)-(CS), for each $i$, if $\tau_i > 0$, then $\xi_{i} = 0$ and $\lambda = 2(z-y_i-\tau_i)$. Instead, if $\tau_i = 0$, then $\xi_i \geq 0$ and $\lambda \geq 2(z-y_i)$. Hence, for all $i$, $\tau_{i}^{\star} = \max\{0, z-y_i -\lambda/2\}$. Again, since  the objective is strictly convex in $\boldsymbol{\tau}$ and the constraints are linear, the optimum is unique.


	\item Projection Onto Simplex. By \citeA{boyd2004convex}, since the feasible set is closed and convex, then the unique minimizer is precisely the orthogonal projection of the vector $\boldsymbol{1}z - \boldsymbol{y}$ onto that set. Furthermore, the authors show that the orthogonality (normal-cone) condition satisfied by the projection is equivalent to the KKT stationarity and complementary slackness constraints derived above. Therefore, the solution given by the KKT system must be the same as the orthogonal projection. 

	\item Progressive “Leveling Up” Algorithm. \citeA{gangopadhyay1992optimal}  shows, using a proof by contradiction based on permissible transfers, that the algorithm leads to the optimal transfer schedule. I verify below that the algorithm is exactly the solution given by the KKT/projection approach. I want to show that the result of the algorithm, $\tau_{i}^{A}$, is equivalent to the solution found by KKT,  $\tau_{i}^{\star}$.
	\begin{itemize}

		\item[\underline{Step 1}:] Clearly, $\tau_{i}^{A} \geq 0$ by construction (the poorest get ``leveled up'' to at least their current income) and the total sum of $\tau_{i}^{A}$ equals $B$, so it is a feasible point.

		\item[\underline{Step 2}:] In terms of stationarity, for $i \leq p$, $\tau_{i}^{A} = \underline{y} - y_i$, so $\tau_{i}^{A} >0 $ (assuming strict inequality $\underline{y} > y_i$). By KKT complementary slackness, $\mu_i=0$ for all $i \leq p$. Then stationarity requires:
		\begin{align*}
			-2\Big(z-y_i-\tau_{i}^{A}\Big) + \lambda = 0 \Rightarrow \lambda = 2\Big(z-y_i-\tau_{i}^{A}\Big) = 2 \Big( z - y_i - \underline{y} + y_i\Big) = 2(z- \underline{y}).
		\end{align*}

		For $i > p$, $\tau_{i}^{A}=0$. By stationarity and dual feasibility, it must be that
		\begin{align*}
			\mu_i = \lambda - 2(z-y_i) \geq 0 \Rightarrow \lambda \geq 2(z-y_i). 
		\end{align*}
		Since for the $i \leq p$, $\lambda = 2(z- \underline{y})$, 
		\begin{align*}
			2(z- \underline{y}) \geq 2(z-y_i) \iff y_i \geq \underline{y}. 
		\end{align*}
		Thus, all households not receiving a transfer are those that began with higher income than $\underline{y}$. 
	\end{itemize}
	Hence, I have constructed a single $\lambda = 2(z- \underline{y})$ and $\mu_i \geq 0$ that satisfy the KKT conditions with $\sum_{i=1}^{n} \tau_{i}^{A} = B$. By uniqueness of the KKT solution, it must coincide with the global optimum.
\end{enumerate}
}
\hyperlink{prop:full_info}{QED}.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\hypertarget{proof:equivalence}{} 
\Proof{prop:equivalence}{
Throughout we impose $\mu_i \geq 0$. Consider the two statistical decision problems: 
\begin{enumerate}
	\item Problem P1 (Transfer Allocation):
\begin{itemize}
    \item Sample space: $\mathcal{X}_1 = \mathbb{R}^n$ (income observations $\boldsymbol{\hat{Y}}$)
    \item Parameter space: $\Theta_1 = \mathbb{R}_+^n$ (cond. mean incomes $\boldsymbol{\mu}$)
    \item Action space: $\mathcal{A}_1 = \{\boldsymbol{\tau} \in \mathbb{R}_+^n \mid \boldsymbol{1}^\top \boldsymbol{\tau} \leq B\}$ (transfers)
    \item Probability distributions: For each $\boldsymbol{\mu} \in \Theta_1$, $P_{1,\boldsymbol{\mu}}$ is the distribution of $\boldsymbol{\hat{Y}}$ where $\hat{Y}_i \mid y_i, \sigma_i \stackrel{\text{ind}}{\sim} \mathcal{N}(\mu_i, \sigma_i^2)$
    \item Loss function: $L_1(\boldsymbol{\tau}, \boldsymbol{\mu}) = \sum_{i=1}^n (z-\mu_i-\tau_i)^2$
\end{itemize}

	\item Problem P2 (Poverty Gap Estimation):
\begin{itemize}
    \item Sample space: $\mathcal{X}_2 = \mathbb{R}^n$ (poverty gap observations $\boldsymbol{X}$)
    \item Parameter space: $\Theta_2 = \{\boldsymbol{\theta} \in \mathbb{R}^n \mid \boldsymbol{\theta} \leq \boldsymbol{1}z\}$ (true poverty gaps)
    \item Action space: $\mathcal{A}_2 = \{\boldsymbol{\tau} \in \mathbb{R}_+^n \mid \boldsymbol{1}^\top \boldsymbol{\tau} \leq B\}$ (estimators)
    \item Probability distributions: For each $\boldsymbol{\theta} \in \Theta_2$, $P_{2,\boldsymbol{\theta}}$ is the distribution of $\boldsymbol{X}$ where $X_i \mid \theta_i, \sigma_i \stackrel{\text{ind}}{\sim} \mathcal{N}(\theta_i, \sigma_i^2)$
    \item Loss function: $L_2(\boldsymbol{\tau}, \boldsymbol{\theta}) = \|\boldsymbol{\theta} - \boldsymbol{\tau}\|^2 = \sum_{i=1}^n (\theta_i - \tau_i)^2$
\end{itemize}
\end{enumerate}
To establish the equivalence, I construct bijective mappings between the components of the two problems and show that these mappings preserve the decision-theoretic structure. Consider the following bijections:
\begin{itemize}
    \item[(a)] Parameter spaces: $f: \Theta_1 \rightarrow \Theta_2$ defined by $f(\boldsymbol{\mu}) = \boldsymbol{1}z - \boldsymbol{\mu}$, with inverse $f^{-1}(\boldsymbol{\theta}) = \boldsymbol{1}z - \boldsymbol{\theta}$. For any $\theta \leq z$, we have $\mu = z-\theta \geq 0$, hence any $\theta \in \Theta_2$ has a unique pre-image, so $f$ is bijective.

    \item[(b)] Sample spaces: $g: \mathcal{X}_1 \rightarrow \mathcal{X}_2$ defined by $g(\boldsymbol{\hat{y}}) = \boldsymbol{1}z - \boldsymbol{\hat{y}}$, with inverse $g^{-1}(\boldsymbol{x}) = \boldsymbol{1}z - \boldsymbol{x}$.

    \item[(c)] Action spaces: $h: \mathcal{A}_1 \rightarrow \mathcal{A}_2$ defined as the identity mapping $h(\boldsymbol{\tau}) = \boldsymbol{\tau}$, as the action spaces are identical.
\end{itemize}
%\textbf{Step 2: Probability Measure Preservation.}
{\bf Probability Measure Preservation}. For any $\boldsymbol{\mu} \in \Theta_1$ and any measurable set $A \subset \mathcal{X}_2$:
\begin{align*}
    P_{2,f(\boldsymbol{\mu})}(A) &= P(\boldsymbol{X} \in A \mid \boldsymbol{\theta} = f(\boldsymbol{\mu})) = P(\boldsymbol{1}z - \boldsymbol{\hat{Y}} \in A \mid \boldsymbol{1}z - \boldsymbol{\mu} = f(\boldsymbol{\mu})) \\
    &= P(\boldsymbol{\hat{Y}} \in \boldsymbol{1}z - A \mid \boldsymbol{\mu}) = P(\boldsymbol{\hat{Y}} \in g^{-1}(A) \mid \boldsymbol{\mu}) \\
    &= P_{1,\boldsymbol{\mu}}(g^{-1}(A))
\end{align*}
{\bf  Loss Function Equivalence}. For any $\boldsymbol{\tau} \in \mathcal{A}_1$ and $\boldsymbol{\mu} \in \Theta_1$:
\begin{align*}
    L_1(\boldsymbol{\tau}, \boldsymbol{\mu}) &= \sum_{i=1}^n (z-\mu_i-\tau_i)^2 = \sum_{i=1}^n ((z-\mu_i)-\tau_i)^2 \\
    &= \sum_{i=1}^n (\theta_i-\tau_i)^2 \quad \text{where } \theta_i = z-\mu_i \\
    &= \|\boldsymbol{\theta} - \boldsymbol{\tau}\|^2 = L_2(h(\boldsymbol{\tau}), f(\boldsymbol{\mu}))
\end{align*}
{\bf Risk Function Equivalence}. For any decision rule $\delta_1: \mathcal{X}_1 \rightarrow \mathcal{A}_1$ in P1, define the corresponding decision rule $\delta_2: \mathcal{X}_2 \rightarrow \mathcal{A}_2$ in P2 as $\delta_2 = h \circ \delta_1 \circ g^{-1} = \delta_1 \circ g^{-1}$ (since $h$ is the identity). The risk function for $\delta_1$ at $\boldsymbol{\mu} \in \Theta_1$ is:
\begin{align*}
    \mathcal{R}_1(\delta_1, \boldsymbol{\mu}) &= \mathbb{E}_{\boldsymbol{\hat{Y}} \sim P_{1,\boldsymbol{\mu}}}[L_1(\delta_1(\boldsymbol{\hat{Y}}), \boldsymbol{\mu})]
\end{align*}
Using the change of variables $\boldsymbol{X} = g(\boldsymbol{\hat{Y}})$, we have $\boldsymbol{\hat{Y}} = g^{-1}(\boldsymbol{X})$. Since $g$ is a bijection, the Jacobian determinant of this transformation is non-zero and constant (in fact, equal to $(-1)^n$). Therefore:
\begin{align*}
    \mathcal{R}_1(\delta_1, \boldsymbol{\mu}) &= \mathbb{E}_{\boldsymbol{\hat{Y}} \sim P_{1,\boldsymbol{\mu}}}[L_1(\delta_1(\boldsymbol{\hat{Y}}), \boldsymbol{\mu})] = \mathbb{E}_{\boldsymbol{X} \sim P_{2,f(\boldsymbol{\mu})}}[L_1(\delta_1(g^{-1}(\boldsymbol{X})), \boldsymbol{\mu})] \\
    &= \mathbb{E}_{\boldsymbol{X} \sim P_{2,f(\boldsymbol{\mu})}}[L_2(h(\delta_1(g^{-1}(\boldsymbol{X}))), f(\boldsymbol{\mu}))] \quad \text{(by loss equivalence)} \\
    &= \mathbb{E}_{\boldsymbol{X} \sim P_{2,f(\boldsymbol{\mu})}}[L_2(\delta_2(\boldsymbol{X}), f(\boldsymbol{\mu}))] =  \mathcal{R}_2(\delta_2, f(\boldsymbol{\mu}))
\end{align*}
{\bf Optimality Preservation}. A decision rule $\delta_1^*$ is optimal in P1 if and only if for all $\boldsymbol{\mu} \in \Theta_1$ and all decision rules $\delta_1$:
\begin{align*}
    \mathcal{R}_1(\delta_1^*, \boldsymbol{\mu}) \leq \mathcal{R}_1(\delta_1, \boldsymbol{\mu})
\end{align*}
By the risk equivalence established in the previous step, this holds if and only if for all $\boldsymbol{\theta} = f(\boldsymbol{\mu}) \in \Theta_2$ and all decision rules $\delta_2 = \delta_1 \circ g^{-1}$:
\begin{align*}
    \mathcal{R}_2(\delta_2^*, \boldsymbol{\theta}) \leq \mathcal{R}_2(\delta_2, \boldsymbol{\theta})
\end{align*}
where $\delta_2^* = \delta_1^* \circ g^{-1}$. Conversely, given any decision rule $\delta_2$ in P2, I can define a corresponding rule $\delta_1 = \delta_2 \circ g$ in P1, and the same equivalence of optimality holds. Therefore, the two statistical decision problems (P1) and (P2) are equivalent in the sense that risk is preserved componentwise (for every parameter value), with a one-to-one correspondence between their optimal decision rules.
}
\hyperlink{prop:equivalence}{QED}.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\hypertarget{proof:JamesStein}{} 
\Proof{prop:JamesStein}{
Let the event
\[
\mathcal{E} := \left\{ X : s(X) >3,  \sigma^2 [s(X) -3] <  ||\tau^{\text{plug}}(X)||^2 \right\},
\]
which is the region where the shrinkage factor lies strictly inside $(0, 1)$ and $\tau^{\text{JS}}(X) \neq \tau^{\text{plug}}(X)$. On this event, I may write
\[
\tau^{\text{JS}}(X) = \tau^{\text{plug}}(X) - \sigma^2 (s - 3) g(X),
\]
and define the loss difference:
\[
\Delta(X) := \|\tau^{\text{JS}}(X) - \theta\|^2 - \|\tau^{\text{plug}}(X) - \theta\|^2.
\]
Then the risk difference is given by:
\[
R(\tau^{\text{JS}}, \theta) - R(\tau^{\text{plug}}, \theta) = \mathbb{E}_\theta\left[\mathbbm{1}_{\mathcal{E}} \cdot \Delta(X)\right].
\]

On $\mathcal{E}$, I expand:
\begin{align*}
\Delta(X)
&= \|\tau^{\text{plug}}(X) - \theta - \sigma^2 (s - 3) g(X)\|^2 - \|\tau^{\text{plug}}(X) - \theta\|^2 \\
&= \sigma^4 (s - 3)^2 \|g(X)\|^2 - 2\sigma^2 (s - 3) (\tau^{\text{plug}}(X) - \theta)^\top g(X).
\end{align*}

To simplify the inner product, note:
\[
(\tau^{\text{plug}}(X) - \theta)^\top g(X)
= (X - \theta)^\top g(X) - (X - \tau^{\text{plug}}(X))^\top g(X),
\]
and the second term vanishes since $\tau^{\text{plug}}(X)$ is the projection of $X$ onto the convex cone, so the residual is orthogonal to $g(X)$. Therefore,
\begin{align*}
	\Delta (X) = \sigma^4 (s - 3)^2 \|g(X)\|^2 - 2\sigma^2 (s - 3) (X - \theta)^\top g(X).
\end{align*}
Since $s$ its piece-wise constant with a gradient that its zero almost everywhere, by Stein’s lemma:
\[
\mathbb{E}_\theta[(s - 3)(X - \theta)^\top g(X)] = \sigma^2 \mathbb{E}_\theta[(s - 3) \operatorname{div} g(X)].
\]
From Lemma~\ref{lemma:divg},
\[
\operatorname{div} g(X) = \frac{s - 3}{\|\tau^{\text{plug}}(X)\|^2} + \frac{2B^2}{s \cdot \|\tau^{\text{plug}}(X)\|^4}.
\]
Substituting gives:
\begin{align*}
R(\tau^{\text{JS}}, \theta) - R(\tau^{\text{plug}}, \theta)
&= -\sigma^4 \mathbb{E}_\theta\left[ \mathbbm{1}_{\mathcal{E}}\left(
    \frac{(s - 3)^2}{\|\tau^{\text{plug}}(X)\|^2}
    + \frac{4B^2(s - 3)}{s \cdot \|\tau^{\text{plug}}(X)\|^4}
  \right) \right].
\end{align*}
Each term inside the expectation is strictly positive on $\mathcal{E}$, so the risk difference is strictly negative whenever $\Pr(\mathcal{E}) > 0$.
}
\hyperlink{prop:JamesStein}{QED}.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\hypertarget{proof:oracle_bayes_rule}{} 
\Proof{prop:oracle_bayes_rule}{
By \citeA{berger2013statistical}, a statistical decision rule is Bayes if and only if it minimizes the posterior risk for every data realization (Result 1, Chapter 4, p. 159). To solve for the optimal action, replace each $y_i$ in the KKT proof of Proposition~\ref{prop:full_info}
by the posterior mean
$m_i=\mathbb{E}_{G\mid\hat{\boldsymbol y},\boldsymbol\sigma}
     [\mu_i\mid\hat y_i,\sigma_i]$. Under Assumption 1, the posterior mean is finite and measurable, so the replacement is valid.
The objective remains a strictly convex quadratic and the feasible set
is unchanged, so the same KKT system yields
\[
  t_i^{*}(\hat y_i,\sigma_i,\lambda)
  =\max\bigl\{0,\,z-m_i-\lambda/2\bigr\},
\]
with $\lambda^{*}$ chosen so that
$\sum_{i=1}^{n} t_i^{*}(\hat y_i,\sigma_i,\lambda^{*})=B$
whenever the budget binds.
Strict convexity again guarantees uniqueness. Since each map $\hat{y}_i \mapsto m_i (\hat{y}_i)$ is measurable and $\boldsymbol{\hat{y}} \mapsto \lambda^{*}(\boldsymbol{\hat{y}})$ is obtained from a continuous, monotone equation, the resulting rule $\boldsymbol{\tau^{*}}$ is measurable.  By construction, $\boldsymbol{\tau^{*}}$ minimizes the posterior risk for every $\boldsymbol{\hat{y}}$; therefore, by \citeA{berger2013statistical}, it minimizes the Bayes risk $r(G, \boldsymbol{\tau} \mid \boldsymbol{\sigma}^2)$ over all $\boldsymbol{\tau} \in \mathcal{D}$. 
}
\hyperlink{prop:oracle_bayes_rule}{QED}.
