\hypertarget{proof:regret}{} 
\Proof{prop:regret}{
Since the orthogonal projection onto a closed, convex set is 1-Lipschitz in the Euclidean norm and it is translation‑invariant,
\begin{align*}
	|| \boldsymbol{\hat{\tau}} -   \boldsymbol{\tau^{*}} || = || P_{\mathcal{A}} ( \boldsymbol{1}z - \boldsymbol{\hat{m}}) - P_{\mathcal{A}} ( \boldsymbol{1}z - \boldsymbol{m^{*}}) || & \leq || \boldsymbol{\hat{m}} - \boldsymbol{m^{*}} ||.
\end{align*}
Since both sides of the inequality are non-negative random variables, taking expectations gives
\begin{align}
\label{eq:intermediate_result}
	\frac{1}{n} \mathbb{E} || \boldsymbol{\hat{\tau}} - \boldsymbol{\tau^{*}} ||^2 \leq \frac{1}{n} \mathbb{E} || \boldsymbol{\hat{m}} - \boldsymbol{m^{*}} ||^2.
\end{align}
Further note that, because the square-root is monotone on $[0, \infty)$, the inequality is preserves if applied to each expectation in \eqref{eq:intermediate_result}:
\begin{align*}
	\sqrt{\frac{1}{n} \mathbb{E} || \boldsymbol{\hat{\tau}} - \boldsymbol{\tau^{*}} ||^2} \leq \sqrt{\frac{1}{n} \mathbb{E} || \boldsymbol{\hat{m}} - \boldsymbol{m^{*}} ||^2}.
\end{align*}

Let  $\boldsymbol{\Delta} = \boldsymbol{\hat{\tau}} - \boldsymbol{\tau^{*}}$ and  $\boldsymbol{\theta} = \boldsymbol{1}z - \boldsymbol{\mu}$, which means that $L(\boldsymbol{\tau}, \boldsymbol{\mu}) = \frac{1}{n} || \boldsymbol{\theta}-  \boldsymbol{\tau}||^{2}$. Observe that:
\begin{align*}
	L(\boldsymbol{\hat{\tau}}, \boldsymbol{\theta}) - L(\boldsymbol{\tau^{*}}, \boldsymbol{\theta}) & = \frac{1}{n} \Big( || \boldsymbol{\theta}-  \boldsymbol{\hat{\tau}}||^{2} - || \boldsymbol{\theta}-  \boldsymbol{\tau^{*}} ||^{2} \Big) \\
	& = \frac{1}{n} \Big[ (\boldsymbol{\hat{\tau}}- \boldsymbol{\theta})'(\boldsymbol{\hat{\tau}}- \boldsymbol{\theta}) - (\boldsymbol{\tau^{*}}- \boldsymbol{\theta})' (\boldsymbol{\tau^{*}}- \boldsymbol{\theta}) \Big] \\
	& = \frac{1}{n} \boldsymbol{\Delta}' (\boldsymbol{\hat{\tau}}+\boldsymbol{\tau^{*}}-2\boldsymbol{\theta})
\end{align*}
The inner product using Cauchy-Schwarz inequality:
\begin{align*}
	\frac{1}{n} \boldsymbol{\Delta}' (\boldsymbol{\hat{\tau}}+\boldsymbol{\tau^{*}}-2\boldsymbol{\theta}) \leq \frac{1}{n} || \boldsymbol{\Delta}|| ||\boldsymbol{\hat{\tau}}+\boldsymbol{\tau^{*}}-2\boldsymbol{\theta}||.
\end{align*}
Taking expectations and applying Hölder's inequality,
\begin{align*}
	\mathbb{E} \Bigg[  || \boldsymbol{\Delta}|| ||\boldsymbol{\hat{\tau}}+\boldsymbol{\tau^{*}}-2\boldsymbol{\theta}|| \Bigg] \leq \Big( \mathbb{E} [  || \boldsymbol{\Delta}||^2] \Big)^{1/2} \Big( \mathbb{E} [ ||\boldsymbol{\hat{\tau}}+\boldsymbol{\tau^{*}}-2\boldsymbol{\theta}||^2] \Big)^{1/2}.
\end{align*}
Using the triangle inequality for norms and expanding:
\begin{align*}
	 ||\boldsymbol{\hat{\tau}}+\boldsymbol{\tau^{*}}-2\boldsymbol{\theta}||^2 &=  ||(\boldsymbol{\hat{\tau}}-\boldsymbol{\theta})+(\boldsymbol{\tau^{*}}-\boldsymbol{\theta})||^2 \\
	 & \leq 2||\boldsymbol{\hat{\tau}}-\boldsymbol{\theta}||^{2} + 2 ||\boldsymbol{\tau^{*}}-\boldsymbol{\theta}||^2.
\end{align*}
For any $ x \in \mathcal{A}$, $||x|| \leq B$, so by the triangle inequality $||x-\boldsymbol{\theta}||^2 \leq B^2 + ||\boldsymbol{\theta}||^2 +2B||\boldsymbol{\theta}||$. Using the algebraic inequality $2ab \leq a^2 + b^2$ gives
\begin{align*}
	||\boldsymbol{\hat{\tau}}-\boldsymbol{\theta}||^{2} \leq 2B^2 + 2 ||\boldsymbol{\theta}||^2, \quad ||\boldsymbol{\tau^{*}}-\boldsymbol{\theta}||^2 \leq 2B^2 + 2 ||\boldsymbol{\theta}||^2.
\end{align*}
Thus,
\begin{align*}
	||\boldsymbol{\hat{\tau}}+\boldsymbol{\tau^{*}}-2\boldsymbol{\theta}||^2 \leq 8B^2 + 8 ||\boldsymbol{\theta} ||^2.
\end{align*}
Since by Assumption 4, the prior has bounded (finite) first and second moment so $1/n \mathbb{E} || \boldsymbol{\theta} ||^2 = \sigma_{\theta}^2$ and $\mathbb{E} || \boldsymbol{\theta} ||^2 = n \sigma_{\theta}^2$, where $\sigma_{\theta}^2 = (z- \mathbb{E}[\mu_i])^2 + \text{Var}(\mu_i) < \infty$. 

Putting everything together and taking expectations gives
\begin{align*}
	\mathbb{E} \Big[ L(\boldsymbol{\hat{\tau}}, \boldsymbol{\theta}) - L(\boldsymbol{\tau^{*}}, \boldsymbol{\theta}) \Big] & \leq \frac{1}{n} \Big( \mathbb{E} || \boldsymbol{\hat{m}} - \boldsymbol{m^{*}} ||^2 \Big)^{1/2} \Big(  8B^2 + 8 n \sigma_{\theta}^{2}  \Big)^{1/2} \\
	& = \Big( \frac{1}{n} \mathbb{E} || \boldsymbol{\hat{m}} - \boldsymbol{m^{*}} ||^2 \Big)^{1/2} \Big(  8B^2/n + 8 \sigma_{\theta}^{2}  \Big)^{1/2}. 
\end{align*}
Let $C_n = \sqrt{8B^2/n + 8 \sigma_{\theta}^{2} } = \sqrt{8} \sigma_{\theta} (1+\frac{B^2}{n \sigma_{\theta}^2})^{1/2}$. 

Consider $\hat{m}_i - \mu_i = (\hat{m}_i -m_{i}^{*}) + (m_{i}^{*}-\mu_i)$ for $i=1,..,n$. Squaring and taking expectations gives
\begin{align*}
	\mathbb{E}[(\hat{m}_i - \mu_i)^2] = \mathbb{E}[(\hat{m}_i - m_i^{*})^2] + \mathbb{E}[(m_i^{*} - \mu_i)^2] +2\mathbb{E}[(\hat{m}_i - m_i^{*})(m_i^{*} - \mu_i)].
\end{align*}
Since $m_{i}^{*} = \mathbb{E}[ \mu_i \mid \hat{y}_i, \sigma_i]$,  $ \mathbb{E}[ (m_{i}^{*} - \mu_i) \mid \hat{y}_i, \sigma_i] = 0$. Since $\hat{m}_i - m_{i}^{*}$ is measurable with respect to the data, the law of iterated expectations gives the orthogonality $\mathbb{E}[(\hat{m}_i - m_i^{*})(m_i^{*} - \mu_i)] =0$. Therefore, summing over $i$ and diving by $n$,
\begin{align*}
	\frac{1}{n}  \mathbb{E}|| \boldsymbol{\hat{m}} -\boldsymbol{\mu}||^{2}  = \frac{1}{n} \mathbb{E}|| \boldsymbol{\hat{m}} -\boldsymbol{m^{*}}||^{2} + \frac{1}{n} \mathbb{E}|| \boldsymbol{m^{*}} -\boldsymbol{\mu} ||^{2}.
\end{align*}
Since  the second term on the right-hand side is non-negative, 
\begin{align*}
	 \frac{1}{n} \mathbb{E}|| \boldsymbol{\hat{m}} -\boldsymbol{m^{*}}||^{2} \leq \frac{1}{n}  \mathbb{E}|| \boldsymbol{\hat{m}} -\boldsymbol{\mu}||^{2}. 
\end{align*}


Since \citeA{jiang2020general}, Theorem 1 (eq. 2.4), states that for a universal constant $M_0$ and all $\log n>1/p$,
\begin{align*}
	\sqrt{\frac{1}{n} \mathbb{E} || \boldsymbol{\hat{m}} - \boldsymbol{\mu} ||^{2}} - \sqrt{\frac{1}{n} \mathbb{E} || \boldsymbol{m^{*}} - \boldsymbol{\mu} ||^{2}} \leq M_0 n^{-p/(2+2p)} (\log n)^{(7p+8)/(4+4p)}.
\end{align*}
Since the posterior mean minimizes conditional MSE, $\mathbb{E} [(m_i^{*} - \mu_i)^2] \leq \sigma_{i}^2$, then, by Assumption 1, 
\begin{align*}
	\frac{1}{n} \mathbb{E} || \boldsymbol{m^{*}} - \boldsymbol{\mu} ||^{2} \leq  \sigma_{\max}^2.
\end{align*}
So, $ \sqrt{\frac{1}{n} \mathbb{E} || \boldsymbol{m^{*}} - \boldsymbol{\mu} ||^{2}} \leq  \sigma_{\max} = \mathcal{O}(1)$ as $n \to \infty$. Consequently,
\begin{align*}
	\sqrt{\frac{1}{n} \mathbb{E} || \boldsymbol{\hat{m}} - \boldsymbol{\mu} ||^{2}} \leq \sigma_{\max} + M_0 n^{-p/(2+2p)} (\log n)^{(7p+8)/(4+4p)}.
\end{align*}
Thus,
\begin{align*}
	\mathbb{E} \Big[ L(\boldsymbol{\hat{\tau}}, \boldsymbol{\theta}) - L(\boldsymbol{\tau^{*}}, \boldsymbol{\theta}) \Big] & \leq \Big[ \sigma_{\max} + M_0 n^{-p/(2+2p)} (\log n)^{(7p+8)/(4+4p)} \Big] C_n.
\end{align*}
}
\hyperlink{prop:regret}{QED}.







