\appendix
\section{Eliashberg theory based on Hubbard model}
\label{app:Eliashberg_Hubbard}
For the analyses of the two-sublattice tetragonal model in the main text, we assume the $d_{xy}$-wave superconducting order belonging to the $B_2$ irrep [Eq.~\eqref{eq:order_parameter_dxy}] within the MF approximation.
Here, we demonstrate that this $d_{xy}$-wave superconducting state is indeed the leading instability and the FFLO state can be stabilized on the basis of the Hubbard interaction and Eliashberg theory.

\subsection{Formalism}
In the following, we discuss the Hubbard Hamiltonian $H = H_0 + H_{\text{int}}^{\text{(Hub)}}$, where the interaction term is given by
\begin{equation}
 H_{\text{int}}^{\text{(Hub)}} = U \sum_{\bm{R}} \sum_{l} n_{\bm{R}, l\uparrow} n_{\bm{R}, l\downarrow},
 \label{eq:interaction_Hubbard}
\end{equation}
with $U > 0$ being the onsite Coulomb repulsion.
$n_{\bm{R}, l s} = c_{\bm{R}, l s}^\dagger c_{\bm{R}, l s}$ is the electron-number operator.

To consider fluctuations of electric and magnetic multipoles, let us formulate the generalized susceptibility within the random-phase approximation.
This is calculated as
\begin{equation}
 \hat{\chi}(\bm{q}; \Omega_m) = \left[ \hat{\bm{1}} - \hat{\chi}_0(\bm{q}; \Omega_m) \hat{U}^{\text{(Hub)}} \right]^{-1} \hat{\chi}_0(\bm{q}; \Omega_m),
 \label{eq:generalized_susceptibility}
\end{equation}
where $\Omega_m = 2m\pi T$ is the bosonic Matsubara frequency.
The bare susceptibility $\chi_0$ is defined by
\begin{equation}
 \chi_0(q)_{\zeta_1 \zeta_2, \zeta_3 \zeta_4} = - \frac{T}{N} \sum_{k} G_0(k+q)_{\zeta_1, \zeta_3} G_0(k)_{\zeta_4, \zeta_2},
\end{equation}
where we use the abbreviations $k = (\bm{k}; \omega_n)$ and $q = (\bm{q}; \Omega_m)$.
The matrix elements of the Hubbard interaction $\hat{U}^{\text{(Hub)}}$ are defined by
\begin{gather}
 U^{\text{(Hub)}}_{\zeta_1 \zeta_2, \zeta_3 \zeta_4} = \delta_{l_1, l_2} \delta_{l_2, l_3} \delta_{l_3, l_4} U_{s_1 s_2, s_3 s_4}, \\
 U_{s_1 s_2, s_3 s_4} =
 \begin{cases}
  U & (s_1 s_2, s_3 s_4) = (\uparrow \downarrow, \uparrow \downarrow) \ \text{or} \  (\downarrow \uparrow, \downarrow \uparrow), \\
  -U & (s_1 s_2, s_3 s_4) = (\uparrow \uparrow, \downarrow \downarrow) \ \text{or} \  (\downarrow \downarrow, \uparrow \uparrow), \\
  0 & \text{otherwise}.
 \end{cases}
\end{gather}

Next, we construct the linearized Eliashberg equation with finite COM momentum~\cite{Yoshida2021, Sumita2023}:
\begin{equation}
 \lambda_{\bm{Q}} \Delta_{\bm{Q}}(k)_{\zeta, \zeta'} = \frac{T}{N} \sum_{q} \sum_{\zeta_1, \zeta_2} V^{\text{(a)}}(q)_{\zeta \zeta_1, \zeta_2 \zeta'} F_{\bm{Q}}(k-q)_{\zeta_1, \zeta_2},
 \label{eq:linearized_Eliashberg}
\end{equation}
where $\hat{\Delta}_{\bm{Q}}(k)$ is the order parameter matrix, and the anomalous Green's function is given by
\begin{equation}
 \hat{F}_{\bm{Q}}(k) = - \hat{G}_0(k) \hat{\Delta}_{\bm{Q}}(k) \hat{G}_0(-k+Q)^{\mathrm{T}}, 
 \label{eq:Green_func_anomalous}
\end{equation}
with $Q = (\bm{Q}; 0)$.
Since we consider the multipole fluctuations as a glue of pairing, the interaction vertex are represented by using the generalized susceptibility \eqref{eq:generalized_susceptibility}:
\begin{align}
 \hat{V}^{\text{(a)}}(q) &= - \frac{1}{2} \hat{U}^{\text{(Hub)}} - \hat{U}^{\text{(Hub)}} \hat{\chi}(q) \hat{U}^{\text{(Hub)}}.
\end{align}
In this finite-momentum Eliashberg theory, we can discuss the instability of the FF state with the COM momentum $\bm{Q}$ for a given momentum $\bm{Q}$.
The phase transition into the FF state takes place when the eigenvalue $\lambda_{\bm{Q}}$ in Eq.~\eqref{eq:linearized_Eliashberg} reaches unity.

\subsection{Numerical results}

\begin{figure}
 \includegraphics[width=\linewidth, pagebox=artbox]{B2_lam_h001_a_0.000.pdf}
 \caption{The COM momentum dependence of the eigenvalue $\lambda_{\bm{Q}}$ of the Eliashberg equation~\eqref{eq:linearized_Eliashberg} for (a) $h = 0$ and (b) $h = 0.4$. The eigenvalue has peaks at finite momenta in (b).}
 \label{fig:B2_lam_h001_a_0.000}
\end{figure}

Using the above formalism, let us investigate the possible superconducting order in an altermagnetic state.
By using the power method, we solve the linearized Eliashberg equation~\eqref{eq:linearized_Eliashberg}.
For a practical reason, we fix the temperature and seek the optimal combination of the COM momentum $\bm{Q}$ and order parameter $\hat{\Delta}_{\bm{Q}}(k)$ that provides the largest eigenvalue $\lambda_{\bm{Q}}$.
In the numerical study, we take $128 \times 128$ $\bm{k}$-point meshes and about 90 Matsubara frequencies generated by \texttt{SparseIR.jl} package~\cite{Wallerberger2023, Wang2020} based on the intermediate representation~\cite{Shinaoka2017} and the sparse sampling~\cite{Li2020}.
The temperature $T$ and the energy cutoff $\omega_{\text{max}}$ are set to $0.01t_1$ and $32t_1$, respectively.
We consider the SC order parameter belonging to the four irreps of $4mm$: $A_1$, $A_2$, $B_1$, and $B_2$.
Using $\tilde{\bm{k}} := \bm{k} - \bm{Q}/2$, the initial functional form is chosen as
\begin{equation}
 \hat{\Delta}_{\bm{Q}}^{\text{(init)}}(k) \sim
 \begin{cases}
  \hat{\tau}_0 \otimes \ii\hat{\sigma}_y & \text{for $A_1$}, \\
  (\cos\tilde{k}_x - \cos\tilde{k}_y) (\hat{\tau}_z \otimes \ii\hat{\sigma}_y) & \text{for $A_2$}, \\
  (\cos\tilde{k}_x - \cos\tilde{k}_y) (\hat{\tau}_0 \otimes \ii\hat{\sigma}_y) & \text{for $B_1$}, \\
  \sin\frac{\tilde{k}_x}{2} \sin\frac{\tilde{k}_y}{2} (\hat{\tau}_x \otimes \ii\hat{\sigma}_y) & \text{for $B_2$}.
 \end{cases}
\end{equation}
We confirmed that the $B_2$ representation ($d_{xy}$-wave superconductivity) is the leading instability for superconductivity in our model for $0 \leq h \leq 0.4$.

Figures~\ref{fig:B2_lam_h001_a_0.000} shows the $\bm{Q}$ dependence of the Eliashberg eigenvalue.
In the paramagnetic state ($h = 0$), the eigenvalue has a single peak at zero momentum [Fig.~\ref{fig:B2_lam_h001_a_0.000}(a)].
On the other hand, the maximum is located at finite $\bm{Q}$ in the altermagnetic state with $h = 0.4$ [Fig.~\ref{fig:B2_lam_h001_a_0.000}(b)].
This results indicate that the FFLO superconductivity is stabilized under the altermagnetic order.


\section{Microscopic derivation of GL equation}
\label{app:GL_microscopic_derivation}
We show the detailed derivation of the GL equation~\eqref{eq:GL} from the Gor'kov equations~\eqref{eq:Gorkov}.
Here, we assume that the vector potential is absent, neglecting the orbital pair breaking effect due to an external magnetic field~%
\footnote{When the vector potential $\bm{A}(\bm{R})$ is taken into account, one should replace the spatial derivative $\nabla_{\bm{R}}$ with the covariant derivative $\bm{D}_{\bm{R}} := \nabla_{\bm{R}} - \ii \frac{2e}{\hbar c} \bm{A}(\bm{R})$ in the final expression.}.
Therefore, the normal Green's function of free electrons is given by
\begin{align}
 \hat{G}_0(\bm{x}, \bm{x}'; \omega_n)
 &= \hat{G}_0(\bm{r}; \omega_n) \notag \\
 &= \frac{1}{N} \sum_{\bm{k}} \ee^{\ii \bm{k} \cdot \bm{r}} \left[(\ii\omega_n + \mu) \hat{\bm{1}} - \hat{H}_0(\bm{k})\right]^{-1},
 \label{eq:G0_r}
\end{align}
which is a function of the relative coordinate $\bm{r} := \bm{x} - \bm{x}'$ because of the translation symmetry.
Using the Wigner representation of the order parameter [Eq.~\eqref{eq:order_parameter_Wigner}], the Gor'kov equations~\eqref{eq:Gorkov} are rewritten as
\begin{widetext}
\begin{subequations}
 \label{eq:Gorkov_2}
 \begin{align}
  \hat{G}\left(\bm{x}, \bm{x}'; \omega_n\right)
  &= \hat{G}_0\left(\bm{r}; \omega_n\right)
  - \frac{1}{N} \sum_{\bm{r}_{12}, \bm{R}_{12}} \sum_{\bm{k}'} \eta(\bm{R}_{12}) \ee^{\ii \bm{k}' \cdot \bm{r}_{12}} \hat{G}_0\left(\bm{R} + \frac{\bm{r}}{2} - \bm{R}_{12} - \frac{\bm{r}_{12}}{2}; \omega_n\right) \hat{\phi}(\bm{k}') \hat{F}\left(\bm{R}_{12} - \frac{\bm{r}_{12}}{2}, \bm{R} - \frac{\bm{r}}{2}; \omega_n\right)^*, \\
  \hat{F}\left(\bm{x}, \bm{x}'; \omega_n\right)
  &= - \frac{1}{N} \sum_{\bm{r}_{12}, \bm{R}_{12}} \sum_{\bm{k}'} \eta(\bm{R}_{12}) \ee^{\ii \bm{k}' \cdot \bm{r}_{12}} \hat{G}_0\left(\bm{R} + \frac{\bm{r}}{2} - \bm{R}_{12} - \frac{\bm{r}_{12}}{2}; \omega_n\right) \hat{\phi}(\bm{k}') \hat{G}\left(\bm{R}_{12} - \frac{\bm{r}_{12}}{2}, \bm{R} - \frac{\bm{r}}{2}; \omega_n\right)^*,
 \end{align}
\end{subequations}
where we define $\bm{R} := (\bm{x} + \bm{x}') / 2$, $\bm{r}_{12} := \bm{x}_1 - \bm{x}_2$, and $\bm{R}_{12} := (\bm{x}_1 + \bm{x}_2) / 2$.
Using the above equations, we expand the right-hand side (RHS) of the MF equation~\eqref{eq:mean-field} up to the third order of $\eta$:
\begin{align}
 \text{[RHS of Eq.~\eqref{eq:mean-field}]}
 &= - \frac{TV}{N} \sum_{\omega_n} \sum_{\bm{r}} \sum_{\bm{k}} \ee^{-\ii \bm{k} \cdot \bm{r}} \tr\left[
  \hat{\phi}(\bm{k})^\dagger \hat{F}\left(\bm{R} + \frac{\bm{r}}{2}, \bm{R} - \frac{\bm{r}}{2}; \omega_n\right) 
 \right] \notag \displaybreak[2] \\
 &= \frac{TV}{N^2} \sum_{\omega_n} \sum_{\bm{r}} \sum_{\bm{r}_{12}, \bm{R}_{12}} \sum_{\bm{k}, \bm{k}'} \eta(\bm{R}_{12}) \ee^{-\ii \bm{k} \cdot \bm{r} + \ii \bm{k}' \cdot \bm{r}_{12}} \notag \\
 &\qquad \times \tr\left[
  \hat{\phi}(\bm{k})^\dagger \hat{G}_0\left(\bm{R} + \frac{\bm{r}}{2} - \bm{R}_{12} - \frac{\bm{r}_{12}}{2}; \omega_n\right)
  \hat{\phi}(\bm{k}') \hat{G}\left(\bm{R}_{12} - \frac{\bm{r}_{12}}{2}, \bm{R} - \frac{\bm{r}}{2}; \omega_n\right)^*
 \right] \notag \displaybreak[2] \\
 &= \frac{TV}{N^2} \sum_{\omega_n} \sum_{\bm{r}} \sum_{\bm{r}_{12}, \bm{R}_{12}} \sum_{\bm{k}, \bm{k}'} \eta(\bm{R}_{12}) \ee^{-\ii \bm{k} \cdot \bm{r} + \ii \bm{k}' \cdot \bm{r}_{12}} \notag \\
 &\qquad \times \tr\left[
  \hat{\phi}(\bm{k})^\dagger \hat{G}_0\left(\bm{R} + \frac{\bm{r}}{2} - \bm{R}_{12} - \frac{\bm{r}_{12}}{2}; \omega_n\right)
  \hat{\phi}(\bm{k}') \hat{G}_0\left(\bm{R}_{12} - \frac{\bm{r}_{12}}{2} - \bm{R} + \frac{\bm{r}}{2}; \omega_n\right)^*
 \right] \notag \\
 &\quad - \frac{TV}{N^3} \sum_{\omega_n} \sum_{\bm{r}} \sum_{\bm{r}_{12}, \bm{R}_{12}} \sum_{\bm{r}_{34}, \bm{R}_{34}} \sum_{\bm{k}, \bm{k}', \bm{k}''} \eta(\bm{R}_{12}) \eta(\bm{R}_{34})^* \ee^{-\ii \bm{k} \cdot \bm{r} + \ii \bm{k}' \cdot \bm{r}_{12} - \ii \bm{k}'' \cdot \bm{r}_{34}} \notag \\
 &\qquad \times \tr\left[
  \hat{\phi}(\bm{k})^\dagger \hat{G}_0\left(\bm{R} + \frac{\bm{r}}{2} - \bm{R}_{12} - \frac{\bm{r}_{12}}{2}; \omega_n\right)
  \hat{\phi}(\bm{k}') \hat{G}_0\left(\bm{R}_{12} - \frac{\bm{r}_{12}}{2} - \bm{R}_{34} - \frac{\bm{r}_{34}}{2}; \omega_n\right)^*
 \right. \notag \\
 &\qquad\qquad \times
 \left.
  \hat{\phi}(\bm{k}'')^* \hat{F}\left(\bm{R}_{34} - \frac{\bm{r}_{34}}{2}, \bm{R} - \frac{\bm{r}}{2}; \omega_n\right)
 \right] \notag \displaybreak[2] \\
 &\simeq \frac{TV}{N^2} \sum_{\omega_n} \sum_{\bm{r}} \sum_{\bm{r}_{12}, \bm{R}_{12}} \sum_{\bm{k}, \bm{k}'} \eta(\bm{R}_{12}) \ee^{-\ii \bm{k} \cdot \bm{r} + \ii \bm{k}' \cdot \bm{r}_{12}} \notag \\
 &\qquad \times \tr\left[
  \hat{\phi}(\bm{k})^\dagger \hat{G}_0\left(\bm{R} + \frac{\bm{r}}{2} - \bm{R}_{12} - \frac{\bm{r}_{12}}{2}; \omega_n\right)
  \hat{\phi}(\bm{k}') \hat{G}_0\left(\bm{R}_{12} - \frac{\bm{r}_{12}}{2} - \bm{R} + \frac{\bm{r}}{2}; \omega_n\right)^*
 \right] \notag \\
 &\quad - \frac{TV}{N^4} \sum_{\omega_n} \sum_{\bm{r}} \sum_{\bm{r}_{12}, \bm{R}_{12}} \sum_{\bm{r}_{34}, \bm{R}_{34}} \sum_{\bm{r}_{56}, \bm{R}_{56}} \sum_{\bm{k}, \bm{k}', \bm{k}'', \bm{k}'''} \eta(\bm{R}_{12}) \eta(\bm{R}_{34})^* \eta(\bm{R}_{56}) \ee^{-\ii \bm{k} \cdot \bm{r} + \ii \bm{k}' \cdot \bm{r}_{12} + \ii \bm{k}'' \cdot \bm{r}_{34} + \ii \bm{k}''' \cdot \bm{r}_{56}} \notag \\
 &\qquad \times \tr\left[
  \hat{\phi}(\bm{k})^\dagger \hat{G}_0\left(\bm{R} + \frac{\bm{r}}{2} - \bm{R}_{12} - \frac{\bm{r}_{12}}{2}; \omega_n\right)
  \hat{\phi}(\bm{k}') \hat{G}_0\left(\bm{R}_{12} - \frac{\bm{r}_{12}}{2} - \bm{R}_{34} - \frac{\bm{r}_{34}}{2}; \omega_n\right)^*
 \right. \notag \\
 &\qquad\qquad \times
 \left.
  \hat{\phi}(\bm{k}'')^\dagger \hat{G}_0\left(\bm{R}_{34} - \frac{\bm{r}_{34}}{2} - \bm{R}_{56} - \frac{\bm{r}_{56}}{2}; \omega_n\right)
  \hat{\phi}(\bm{k}''') \hat{G}_0\left(\bm{R}_{56} - \frac{\bm{r}_{56}}{2} - \bm{R} + \frac{\bm{r}}{2}; \omega_n\right)^*
 \right].
 \label{eq:MF_RHS}
\end{align}
In the second term of the final expression, we use the transformation $\bm{k}'' \to -\bm{k}''$ and replace $\hat{G}$ with $\hat{G}_0$ as an approximation.
Using Eq.~\eqref{eq:G0_r}, the first term in Eq.~\eqref{eq:MF_RHS} is further calculated as
\begin{align}
 \text{[The first term in Eq.~\eqref{eq:MF_RHS}]}
 &= \frac{TV}{N^2} \sum_{\omega_n} \sum_{\bm{r}} \sum_{\bm{r}_{12}, \bm{R}_{12}} \sum_{\bm{k}, \bm{k}'} \eta(\bm{R}_{12}) \ee^{-\ii \bm{k} \cdot \bm{r} + \ii \bm{k}' \cdot \bm{r}_{12}} \notag \\
 &\qquad \times \frac{1}{N^2} \sum_{\bm{k}_1, \bm{k}_2} \ee^{\ii \bm{k}_1 \cdot (\bm{R} + \frac{\bm{r}}{2} - \bm{R}_{12} - \frac{\bm{r}_{12}}{2})} \ee^{-\ii \bm{k}_2 \cdot (\bm{R}_{12} - \frac{\bm{r}_{12}}{2} - \bm{R} + \frac{\bm{r}}{2})}
 \tr\left[
  \hat{\phi}(\bm{k})^\dagger \hat{G}_0\left(\bm{k}_1; \omega_n\right)
  \hat{\phi}(\bm{k}') \hat{G}_0\left(\bm{k}_2; \omega_n\right)^*
 \right] \notag \\
 &= \frac{TV}{N^2} \sum_{\omega_n} \sum_{\bm{k}, \bm{Q}} \sum_{\bm{R}_{12}}
 \underline{\ee^{-2\ii \bm{Q} \cdot (\bm{R}_{12} - \bm{R})} \eta(\bm{R}_{12})}
 \tr\left[ \hat{X}(\bm{k}, \bm{Q}; \omega_n) \right].
\end{align}
Defining $\bar{\bm{R}} := \bm{R}_{12} - \bm{R}$, we expand $\eta(\bm{R}_{12}) = \eta(\bm{R} + \bar{\bm{R}})$ around $\bm{R}$.
Then the underlined part is given by
\begin{align}
 \ee^{-2\ii \bm{Q} \cdot \bar{\bm{R}}} \eta(\bm{R} + \bar{\bm{R}})
 &= \ee^{-2\ii \bm{Q} \cdot \bar{\bm{R}}}
 \sum_{n=0}^{\infty} \frac{1}{n!} (\bar{\bm{R}} \cdot \nabla_{\bm{R}'})^n \eta(\bm{R}')\bigg|_{\bm{R}' = \bm{R}} \notag \\
 &= \ee^{-2\ii \bm{Q} \cdot \bar{\bm{R}}} \eta(\bm{R})
 + \sum_{n=1}^{\infty} \frac{1}{n!} \left(\frac{-1}{2\ii}\right)^n \sum_{\mu_1, \dots, \mu_n} \frac{\partial^n \ee^{-2\ii \bm{Q} \cdot \bar{\bm{R}}}}{\partial Q_{\mu_1} \dotsb \partial Q_{\mu_n}}
 \cdot \frac{\partial^n \eta(\bm{R})}{\partial R_{\mu_1} \dotsb \partial R_{\mu_n}}.
\end{align}
Assuming the slowly varying of the order parameter in the real space, we take the expansion up to the fourth order with respect to the derivative $\nabla_{\bm{R}}$.
Then we obtain
\begin{align}
 \text{[The first term in Eq.~\eqref{eq:MF_RHS}]}
 &\simeq \frac{TV}{N^2} \eta(\bm{R}) \sum_{\omega_n} \sum_{\bm{k}, \bm{Q}}
 \sum_{\bar{\bm{R}}} \ee^{-2\ii \bm{Q} \cdot \bar{\bm{R}}}
 \tr\left[ \hat{X}(\bm{k}, \bm{Q}; \omega_n) \right] \notag \\
 &\quad + \frac{TV}{N^2} \sum_{n=1}^{4} \frac{1}{n!} \left(\frac{-1}{2\ii}\right)^n \sum_{\mu_1, \dots, \mu_n}
 \frac{\partial^n \eta(\bm{R})}{\partial R_{\mu_1} \dotsb \partial R_{\mu_n}}
 \sum_{\omega_n} \sum_{\bm{k}, \bm{Q}} \sum_{\bar{\bm{R}}}
 \frac{\partial^n \ee^{-2\ii \bm{Q} \cdot \bar{\bm{R}}}}{\partial Q_{\mu_1} \dotsb \partial Q_{\mu_n}}
 \cdot \tr\left[ \hat{X}(\bm{k}, \bm{Q}; \omega_n) \right] \notag \displaybreak[2] \\
 &= \frac{TV}{N} \eta(\bm{R}) \sum_{\omega_n} \sum_{\bm{k}}
 \tr\left[ \hat{X}(\bm{k}, \bm{0}; \omega_n) \right] \notag \\
 &\quad + \frac{TV}{N} \sum_{n=1}^{4} \frac{1}{n! (2\ii)^n} \sum_{\mu_1, \dots, \mu_n}
 \frac{\partial^n \eta(\bm{R})}{\partial R_{\mu_1} \dotsb \partial R_{\mu_n}}
 \sum_{\omega_n} \sum_{\bm{k}} \frac{\partial^n}{\partial Q_{\mu_1} \dotsb \partial Q_{\mu_n}}
 \tr\left[ \hat{X}(\bm{k}, \bm{Q}; \omega_n) \right] \bigg|_{\bm{Q} = \bm{0}} \notag \\
 &= (1 - V \alpha) \eta(\bm{R})
 - V \sum_{n=1}^{4} \sum_{\mu_1, \dots, \mu_n} c^{(2)}_{\mu_1 \dots \mu_n}
 \frac{\partial^n \eta(\bm{R})}{\partial R_{\mu_1} \dotsb \partial R_{\mu_n}},
 \label{eq:Gorkov_RHS_1st}
\end{align}
where we use Eqs.~\eqref{eq:GL_coefficient_alpha} and \eqref{eq:c2_diff}.
On the other hand, the third-order term in $\eta$ is given by
\begin{equation}
 \text{[The second term in Eq.~\eqref{eq:MF_RHS}]}
 \simeq - \frac{TV}{N} |\eta(\bm{R})|^2 \eta(\bm{R}) \sum_{\omega_n} \sum_{\bm{k}}
 \tr\left[ \hat{X}(\bm{k}, \bm{0}; \omega_n)^2 \right]
 = - 2V \beta |\eta(\bm{R})|^2 \eta(\bm{R}),
 \label{eq:Gorkov_RHS_2nd}
\end{equation}
where we neglect the spatial derivative and use Eq.~\eqref{eq:GL_coefficient_beta}.
Substituting Eqs.~\eqref{eq:Gorkov_RHS_1st} and \eqref{eq:Gorkov_RHS_2nd} into the MF equation~\eqref{eq:mean-field}, we finally get the GL equation:
\begin{gather}
 \eta(\bm{R}) = (1 - V \alpha) \eta(\bm{R}) - 2V \beta |\eta(\bm{R})|^2 \eta(\bm{R})
 - V \sum_{n=1}^{4} \sum_{\mu_1, \dots, \mu_n} c^{(2)}_{\mu_1 \dots \mu_n}
 \frac{\partial^n \eta(\bm{R})}{\partial R_{\mu_1} \dotsb \partial R_{\mu_n}}, \notag \\
 \therefore \alpha \eta(\bm{R}) + 2\beta |\eta(\bm{R})|^2 \eta(\bm{R})
 + \sum_{n=1}^{4} \sum_{\mu_1, \dots, \mu_n} c^{(2)}_{\mu_1 \dots \mu_n}
 \frac{\partial^n \eta(\bm{R})}{\partial R_{\mu_1} \dotsb \partial R_{\mu_n}} = 0.
\end{gather}
Imposing the symmetry of tetragonal systems on this equation, we can reproduce Eq.~\eqref{eq:GL} in the main text.
\end{widetext}

\section{GL coefficients in a continuum model}
\label{app:GL_coefficients_continuum}
Following Refs.~\cite{Bauer_book, Wakatsuki2017, Wakatsuki2018}, we derive the GL coefficients of a continuum model in a Zeeman field [Eqs.~\eqref{eq:GL_continuum_sZ_dS} and \eqref{eq:GL_continuum_dZ_dS}].
For the Hamiltonian in Eqs.~\eqref{eq:Hamiltonian_continuum_kin} and \eqref{eq:Hamiltonian_continuum_mag}, the Green's function of free electrons is given by
\begin{equation}
 G_0(\bm{k}; \omega_n)_{s, s'} = \frac{\delta_{s, s'}}{\ii\omega_n - \xi(\bm{k}) + (-1)^s h(\bm{k})},
\end{equation}
where $\xi(\bm{k}) = \frac{\bm{k}^2}{2m} - \mu$.
Using this Green's function, we calculate the coefficients $\alpha$, $\beta$, and $\kappa$ [Eqs.~\eqref{eq:GL_coefficient_alpha}--\eqref{eq:GL_coefficient_beta} and \eqref{eq:GL_coefficient_kappa}] by replacing the summation $\frac{1}{N} \sum_{\bm{k}}$ with an integral $\frac{1}{(2\pi)^2} \int \mathrm{d}\bm{k}$.
For the analytical calculations in the following, we will refer to some useful formulas, which are summarized at the end of this Appendix (Sec.~\ref{app:GL_coefficients_continuum_formulas}).

First, to discuss $\alpha$ and $\kappa$, let us consider the following integral,
\begin{equation}
 I(\bm{Q}) := T \sum_{\omega_n} \int \frac{\mathrm{d}\bm{k}}{(2\pi)^2} \tr\left[\hat{X}(\bm{k}, \bm{Q}; \omega_n)\right],
\end{equation}
whose expansion with respect to $\bm{Q}$ includes the two coefficients:
\begin{equation}
 I(\bm{Q}) = \left(\frac{1}{V} - \alpha\right) Q^0 - 4 \kappa Q^2 + \mathcal{O}(Q^4).
 \label{eq:I_Q_expansion}
\end{equation}
Noting that $\xi(\bm{k})$ and $h(\bm{k})$ are even in $\bm{k}$, and using the $d_{x^2-y^2}$-wave order parameter $\hat{\phi}(\bm{k}_n) = \sqrt{2} (k_{nx}^2 - k_{ny}^2) \ii\hat{\sigma}_y$, we calculate $I(\bm{Q})$ as
\begin{widetext}
\begin{align}
 I(\bm{Q})
 &= T \sum_{s} \sum_{\omega_n} \int \frac{\mathrm{d}\bm{k}}{(2\pi)^2}
 \frac{2(k_{nx}^2 - k_{ny}^2)^2}{\left[\ii\omega_n - \xi(\bm{k} + \bm{Q}) + (-1)^s h(\bm{k} + \bm{Q})\right] \left[- \ii\omega_n - \xi(\bm{k} - \bm{Q}) - (-1)^s h(\bm{k} - \bm{Q})\right]} \notag \displaybreak[2] \\
 &\simeq T \sum_{s} \sum_{\omega_n} \int \frac{\mathrm{d}\bm{k}}{(2\pi)^2}
 \frac{2(k_{nx}^2 - k_{ny}^2)^2}{\left[\ii\omega_n - \xi(\bm{k}) - \bm{v}(\bm{k}) \cdot \bm{Q} + (-1)^s h(\bm{k} + \bm{Q})\right] \left[- \ii\omega_n - \xi(\bm{k}) + \bm{v}(\bm{k}) \cdot \bm{Q} - (-1)^s h(\bm{k} - \bm{Q})\right]} \notag \displaybreak[2] \\
 &\simeq \rho_{\mathrm{F}} T \sum_{s} \sum_{\omega_n} \int_{-\infty}^{\infty} \mathrm{d}\xi \Braket{
 \frac{\cos^2(2\theta_{\bm{k}})}{\left[\xi - \ii\omega_n + \bm{v}(\bm{k}) \cdot \bm{Q} - (-1)^s h(\bm{k} + \bm{Q})\right] \left[\xi + \ii\omega_n - \bm{v}(\bm{k}) \cdot \bm{Q} + (-1)^s h(\bm{k} - \bm{Q})\right]}}_{\mathrm{FS}},
 \label{eq:int_trX_tmp}
\end{align}
\end{widetext}
where $\bm{v}(\bm{k}) := \nabla_{\bm{k}} \xi(\bm{k}) = \bm{k} / m$ is the velocity.
In the last line, we used the approximation
\begin{gather}
 2 \int \frac{\mathrm{d}\bm{k}}{(2\pi)^2} (\cdot) \simeq \rho_{\mathrm{F}} \int_{-\infty}^{\infty} \mathrm{d}\xi \braket{\cdot}_{\mathrm{FS}}, \displaybreak[2] \\
 \braket{f(\bm{k})}_{\mathrm{FS}} := \int_{0}^{2\pi} \frac{\mathrm{d}\theta_{\bm{k}}}{2\pi} f(k_{\mathrm{F}} \cos\theta_{\bm{k}}, k_{\mathrm{F}} \sin\theta_{\bm{k}}),
\end{gather}
where the angular average is taken over the undistorted Fermi surface with the Fermi momentum $k_{\mathrm{F}}$.
Using the formula~\eqref{eq:formula_int_xi_1}, Equation~\eqref{eq:int_trX_tmp} is reduced to
\begin{align}
 I(\bm{Q})
 &= \rho_{\mathrm{F}} \pi T \sum_{s} \sum_{\omega_n} \left\langle \frac{\cos^2(2\theta_{\bm{k}})}{|\omega_n| + \ii \Omega_s(\bm{k}, \bm{Q}) \sgn(\omega_n)} \right\rangle_{\mathrm{FS}} \notag \\
 &= \rho_{\mathrm{F}} \pi T \sum_{s} \sum_{\omega_n} \sum_{l=0}^{\infty} (-1)^l \left\langle \cos^2(2\theta_{\bm{k}}) \frac{\Omega_s(\bm{k}, \bm{Q})^{2l}}{|\omega_n|^{2l+1}} \right\rangle_{\mathrm{FS}} \notag \\
 &= \rho_{\mathrm{F}} \sum_{s} \sum_{l=0}^{\infty} (-1)^l S_{2l+1}(T) \left\langle \cos^2(2\theta_{\bm{k}}) \Omega_s(\bm{k}, \bm{Q})^{2l} \right\rangle_{\mathrm{FS}},
 \label{eq:int_trX}
\end{align}
where we define
\begin{align}
 & \Omega_s(\bm{k}, \bm{Q})
 := \bm{v}(\bm{k}) \cdot \bm{Q} - \frac{(-1)^s}{2} [h(\bm{k} + \bm{Q}) + h(\bm{k} - \bm{Q})] \notag \\
 &= (-1)^{s-1} h(\bm{k}) + \bm{v}(\bm{k}) \cdot \bm{Q} + \frac{(-1)^{s-1}}{2} (\bm{Q} \cdot \nabla_{\bm{k}})^2 h(\bm{k}) + \dotsb.
\end{align}
Then we expand $\sum_{s} \Omega_s(\bm{k}, \bm{Q})^{2l}$ ($l \geq 1$) with respect to $\bm{Q}$:
\begin{align}
 \sum_{s} \Omega_s(\bm{k}, \bm{Q})^{2l}
 &= 2h(\bm{k})^{2l} + 2 \cdot \binom{2l}{1} \, h(\bm{k})^{2l-1} (\bm{Q} \cdot \nabla_{\bm{k}})^2 h(\bm{k}) \notag \\
 &\quad + 2 \cdot \binom{2l}{2} \, h(\bm{k})^{2l-2} [\bm{v}(\bm{k}) \cdot \bm{Q}]^2 + \dotsb.
 \label{eq:Omega_2l}
\end{align}
From Eqs.~\eqref{eq:I_Q_expansion}, \eqref{eq:int_trX}, and \eqref{eq:Omega_2l}, therefore, the GL coefficients $\alpha$ and $\kappa$ are given by
\begin{align}
 \alpha &= \frac{1}{V} - 2\rho_{\mathrm{F}} \sum_{l=0}^{\infty} (-1)^l S_{2l+1}(T) \left\langle \cos^2(2\theta_{\bm{k}}) h(\bm{k})^{2l} \right\rangle_{\mathrm{FS}}, \\
 \kappa &= \frac{\rho_{\mathrm{F}} k_{\mathrm{F}}^2}{2m^2}
 \sum_{l=1}^{\infty} (-1)^{l-1} \binom{2l}{2} \, S_{2l+1}(T) \Biggl\langle \cos^2(2\theta_{\bm{k}}) \notag \\
 &\quad \times \Biggl[ \frac{2m^2 h(\bm{k})^{2l-1}}{(2l-1) k_{\mathrm{F}}^2} (\hat{\bm{Q}} \cdot \nabla_{\bm{k}})^2 h(\bm{k})
 + h(\bm{k})^{2l-2} (\bm{k}_n \cdot \hat{\bm{Q}})^2 \Biggr] \Biggr\rangle_{\mathrm{FS}}.
 \label{eq:GL_continuum_dS_kappa}
\end{align}
Using the formulas~\eqref{eq:formula_int_theta_1}--\eqref{eq:formula_int_theta_3}, one can reproduce Eqs.~\eqref{eq:GL_continuum_sZ_dS_alpha} and \eqref{eq:GL_continuum_sZ_dS_beta_kappa} for a uniform Zeeman field [$h(\bm{k}) = h$], and Eqs.~\eqref{eq:GL_continuum_dZ_dS_alpha} and \eqref{eq:GL_continuum_dZ_dS_kappa} for a momentum-dependent Zeeman field [$h(\bm{k}) = \sqrt{2} h (k_{nx}^2 - k_{ny}^2) = \sqrt{2} h \cos(2\theta_{\bm{k}})$].

Next, the coefficient $\beta$ is calculated in a similar way to $I(\bm{Q})$:
\begin{widetext}
\begin{align}
 \beta
 &= \frac{T}{2} \sum_{\omega_n} \int \frac{\mathrm{d}\bm{k}}{(2\pi)^2}
 \tr\left[\hat{X}(\bm{k}, \bm{0}; \omega_n)^2\right] \notag \\
 &= T \sum_{s} \sum_{\omega_n} \int \frac{\mathrm{d}\bm{k}}{(2\pi)^2}
 \frac{2(k_{nx}^2 - k_{ny}^2)^4}{\left[\ii\omega_n - \xi(\bm{k}) + (-1)^s h(\bm{k})\right]^2 \left[- \ii\omega_n - \xi(\bm{k}) - (-1)^s h(\bm{k})\right]^2} \notag \\
 &\simeq \rho_{\mathrm{F}} T \sum_{s} \sum_{\omega_n} \int_{-\infty}^{\infty} \mathrm{d}\xi
 \Braket{\frac{\cos^4(2\theta_{\bm{k}})}{\left[\xi - \ii\omega_n - (-1)^s h(\bm{k})\right]^2 \left[\xi + \ii\omega_n + (-1)^s h(\bm{k})\right]^2}}_{\mathrm{FS}} \notag \\
 &= \frac{\rho_{\mathrm{F}}}{2} \pi T \sum_{s} \sum_{\omega_n} \left\langle \frac{\cos^4(2\theta_{\bm{k}})}{\left[|\omega_n| - \ii (-1)^s h(\bm{k}) \sgn(\omega_n)\right]^3} \right\rangle_{\mathrm{FS}} \notag \\
 &= \frac{\rho_{\mathrm{F}}}{2} \pi T \sum_{s} \sum_{\omega_n} \sum_{l=1}^{\infty} (-1)^{l-1} \binom{2l}{2} \left\langle \cos^4(2\theta_{\bm{k}}) \frac{h(\bm{k})^{2l-2}}{|\omega_n|^{2l+1}} \right\rangle_{\mathrm{FS}} \notag \\
 &= \rho_{\mathrm{F}} \sum_{l=1}^{\infty} (-1)^{l-1} \binom{2l}{2} \, S_{2l+1}(T) \left\langle \cos^4(2\theta_{\bm{k}}) h(\bm{k})^{2l-2} \right\rangle_{\mathrm{FS}},
\end{align}
\end{widetext}
where we used the formula~\eqref{eq:formula_int_xi_2}.
With the help of the formula~\eqref{eq:formula_int_theta_1}, this equation results in Eq.~\eqref{eq:GL_continuum_sZ_dS_beta_kappa} for a uniform Zeeman field, and Eq.~\eqref{eq:GL_continuum_dZ_dS_beta} for a $d_{x^2-y^2}$-wave Zeeman field.

\subsection{The case of strongly coupled superconductivity}
\label{app:GL_coefficients_continuum_strong}
We make a short notice on the GL coefficient $\kappa$ in a $d$-wave Zeeman field.
Equation~\eqref{eq:GL_continuum_dZ_dS_kappa} explicitly contains the Fermi energy $E_{\mathrm{F}}$, which arises from the derivative of the momentum-dependent field [the first term in Eq.~\eqref{eq:GL_continuum_dS_kappa}].
In the main text, we neglected this term since weakly coupled superconductors satisfy $T_{\mathrm{c}0} \ll E_{\mathrm{F}}$.

Here, we consider strongly coupled superconductors where the transition temperature $T_{\mathrm{c}0}$ is comparable to the Fermi energy $T_{\mathrm{c}0}$.
Figure~\ref{fig:phase_GL_continuum_dZ_dS_strong} show a phase diagram for $E_{\mathrm{F}} / T_{\mathrm{c}0} = 1$.
In this case, the zeros of $\kappa$ (green dash-dotted line) become a convex curve upward, while those are a straight line in the weak-coupling limit [Fig.~\ref{fig:phase_GL_continuum_dS}(b)].
Therefore, the FF state would be stabilized in the intermediate field regime between the blue and green lines.
In a higher Zeeman field, however, the coefficient $\beta$ also flips to negative; then the amplitude-modulated superconductivity becomes more stable.
Although this behavior does not describe our results in Fig.~\ref{fig:phase_GL_square2}, this may correspond to a previous theoretical analysis reporting the transition from the FF state to the PDW state by changing the chemical potential~\cite{Sim2024_arXiv}.

\begin{figure}
 \includegraphics[width=.7\linewidth, pagebox=artbox]{phase_GL_continuum_dZ_dS_strong.pdf}
 \caption{$T$--$h$ phase diagram in the continuum model with a $d$-wave Zeeman field, for strongly coupled superconductivity. As in Fig.~\ref{fig:phase_GL_continuum_dS}, the $\alpha = 0$ lines are unreliable when $h / T$ is large (dark shaded areas) since we truncate the infinite series after 100 terms.}
 \label{fig:phase_GL_continuum_dZ_dS_strong}
\end{figure}

\subsection{Integral formulas}
\label{app:GL_coefficients_continuum_formulas}
We here introduce some integral formulas that are used in the analytical calculations above.
First, we show integrals with respect to the energy $\xi$.
Let $a$ and $b$ be arbitrary real numbers.
Then the following equations are satisfied:
\begin{align}
 &\int_{-\infty}^{\infty} \mathrm{d}\xi \frac{1}{[\xi - (\ii\omega_n + a)] [\xi - (-\ii\omega_n + b)]} \notag \\
 =& \frac{\pi}{|\omega_n| + \ii \frac{b-a}{2} \sgn(\omega_n)},
 \label{eq:formula_int_xi_1} \\
 & \int_{-\infty}^{\infty} \mathrm{d}\xi \frac{1}{[\xi - (\ii\omega_n + a)]^2 [\xi - (-\ii\omega_n + b)]^2} \notag \\
 =& \frac{\pi / 2}{\left[|\omega_n| + \ii \frac{b-a}{2} \sgn(\omega_n)\right]^3},
 \label{eq:formula_int_xi_2}
\end{align}
which are easily proved by using the residue theorem.

Next, we introduce integrals with respect to the angle $\theta_{\bm{k}}$.
Let $l$ be an integer greater than or equal to $1$.
Then
\begin{align}
 & \int_{0}^{2\pi} \frac{\mathrm{d}\theta_{\bm{k}}}{2\pi} \cos^{2l}(2\theta_{\bm{k}})
 = \frac{(2l)!}{2^{2l} (l!)^2},
 \label{eq:formula_int_theta_1} \displaybreak[2] \\
 & \int_{0}^{2\pi} \frac{\mathrm{d}\theta_{\bm{k}}}{2\pi} \cos^{2l}(2\theta_{\bm{k}}) \cos^2\theta_{\bm{k}} \notag \\
 =& \int_{0}^{2\pi} \frac{\mathrm{d}\theta_{\bm{k}}}{2\pi} \cos^{2l}(2\theta_{\bm{k}}) \sin^2\theta_{\bm{k}}
 = \frac{(2l)!}{2^{2l+1} (l!)^2},
 \label{eq:formula_int_theta_2} \displaybreak[2] \\
 & \int_{0}^{2\pi} \frac{\mathrm{d}\theta_{\bm{k}}}{2\pi} \cos^{2l-1}(2\theta_{\bm{k}}) \sin^2\theta_{\bm{k}} (\sin^2\theta_{\bm{k}} - 3\cos^2\theta_{\bm{k}}) \notag \\
 =& \int_{0}^{2\pi} \frac{\mathrm{d}\theta_{\bm{k}}}{2\pi} \cos^{2l-1}(2\theta_{\bm{k}}) \cos^2\theta_{\bm{k}} (3\sin^2\theta_{\bm{k}} - \cos^2\theta_{\bm{k}}) \notag \\
 =& - \frac{(2l)!}{2^{2l+1} (l!)^2},
 \label{eq:formula_int_theta_3}
\end{align}
are satisfied.


