\section{Theory}
% ----------------------------- %
% ----------------------------- %

% ----------------------------- %
\subsection{The convolutive mixture model}
% ----------------------------- %
A multichannel EMG signal can be described as a linear convolution mixture, i.e.,
\begin{equation}
\label{eqn:convBSSspiketrain}
x_i(t) \ = \ \sum_{j=1}^{N} \sum_{l=0}^{L-1}h_{ij}(l) s_j(t-l) \, + \, \varepsilon_{i} (t) \ ,
\end{equation}
where $x_i(t)$ (with $i=1,..., M$ and $t=0,..., T$) denotes the $i$th channel of the EMG signal with $M$ electrodes, and $t$ denotes a discrete time frame with $T+1$ being the total number of samples. 
The impulse response of the $j$th MU, i.e., the motor unit action potential (MUAP), at the $i$th channel is given by $h_{ij}(l)$, where $L$ denotes the number of discrete samples of the impulse responses and $N$ is the number of active MUs in the EMG signal. 
Further, $\varepsilon_{i}$ denotes additive noise.
The spike train for the $j$th MU is defined as
\begin{equation}
\label{eqn:convBSSdirac}
s_j(t)=\sum_{r \in \mathcal{S}_j} \delta (t-t_j^r),
\end{equation}
where $\mathcal{S}_j:=\{t_j^1, ..., t_j^{T_j}\}$ is the set of discharge times of the $j$th MU and $\delta(\cdot)$ is the Dirac delta function. 
Equation~\eqref{eqn:convBSSspiketrain} can be rephrased in matrix form, i.e.,
\begin{equation}
\label{eqn:convBSSmatrix}
\mathbf{x}(t) \ = \ \sum_{l=0}^{L-1} \mathbf{H}(l) \mathbf{s}(t-l) \ + \ \bm{\varepsilon}(t),
\end{equation}
where $\mathbf{x}(t)=[x_1(t),x_2(t),...,x_M(t)]^T$, $\mathbf{s}(t)=[s_1(t),s_2(t),...,s_N(t)]^T$, and $\mathbf{H}(l)$ has size $M \times N$ and contains the $l$th sample of MUAPs for the $N$ MUs and $M$ channels.

A convolutive mixture with finite impulse response filters can be represented as a linear instantaneous mixture in the time domain. 
This is achieved by defining an extended vector of sources and observations, each including the original sources or observations and their delayed versions {\citep{Hyvarinen2001}}. 
%In this context, the extended vector of sources includes the original sources and their $L-1$ delayed versions. 
%The extended vector of observations includes $R$ delayed versions of each observation, where the selection of $R$ is postulated to be large enough to solve the inverse problem through an overcomplete system {\citep{Holobar2007a,Farina2016a}}. 
%In this way, relatively long impulse responses require large extension factors unless the number of recorded channels is high, given the empirical rule $R \geq (N/M)L$ {\citep{Holobar2007a,Farina2016a}}. However, the importance of this empirical rule has become less clear due to the recent ultrasound-based method {\citep{Lubel2024}}, where the length of the mechanical impulse responses may be over 300 ms {\citep{McNulty2000,Raikova2008}}, while the number of pixels ($M$), MUs ($N$), and extension factor is approximately the same as with EMG signals ($R \approx 15)$ {\citep{Negro2016,Lubel2024}}.
%
This yields
\begin{equation}
\label{eqn:convBSSextendedmatrix}
\begin{split}
\mathbf{\tilde{x}}(t) \ &= \ \mathbf{\tilde{H}} \mathbf{\tilde{s}}(t) \, + \, \bm{\tilde{\varepsilon}}(t) \ , \  \text{with} \\[3mm]
\mathbf{\tilde{H}} \ &= \ 
\begin{bmatrix}
\mathbf{\tilde{H}}_{11} & \cdots & \mathbf{\tilde{H}}_{1N} \\
\vdots & \ddots & \vdots \\
\mathbf{\tilde{H}}_{M1} & \cdots & \mathbf{\tilde{H}}_{MN} \\
\end{bmatrix}, \\[2mm]
\mathbf{\tilde{x}}(t) \ &= \ [\mathbf{\tilde{x}}_1(t),\mathbf{\tilde{x}}_2(t),...,\mathbf{\tilde{x}}_M(t)]^T \ ,\\[1mm]
\mathbf{\tilde{s}}(t) \ &= \ [\mathbf{\tilde{s}}_1(t),\mathbf{\tilde{s}}_2(t),...,\mathbf{\tilde{s}}_N(t)]^T \ ,\\[1mm]
\bm{\tilde{\varepsilon}}(t) \ &= \ [\bm{\tilde{\varepsilon}}_1(t),\bm{\tilde{\varepsilon}}_2(t),...,\bm{\tilde{\varepsilon}}_M(t)]^T \ ,\\
\end{split}
\end{equation}
where the block matrices or vectors are given by
\begin{equation}
\label{eqn:convBSSextendedcomps}
\begin{split}
\mathbf{\tilde{H}}_{ij} \ &= \ 
\begin{bmatrix}
h_{ij}(0) & \cdots & h_{ij}(L-1) & 0 & \cdots & 0 \\
0 & \ddots & \ddots & \ddots & \ddots & \vdots \\
\vdots & \ddots & \ddots & \ddots & \ddots & 0 \\
0 & \cdots & 0 & h_{ij}(0) & \cdots & h_{ij}(L-1) \\
\end{bmatrix} \ , \\[2mm]
\mathbf{\tilde{x}}_i(t)&=[x_i(t),x_i(t-1),\ldots,x_i(t-R)] \ ,\\[1mm]
\mathbf{\tilde{s}}_j(t)&=[s_j(t),s_j(t-1),\ldots,s_j(t-L-R+1)] \ ,\\[1mm]
\bm{\tilde{\varepsilon}}_i(t)&=[\varepsilon_i(t),\varepsilon_i(t-1),\ldots,\varepsilon_i(t-R)] \ .\\
\end{split}
\end{equation}

The mixing model in Equation~\eqref{eqn:convBSSextendedcomps} is typically ill-conditioned. Thus, the activity of a full motor neuron pool cannot be reconstructed even when the forward mixing model is known {\citep[e.g.,][]{Klotz2023}}. 
Treating non-detectable sources as part of the additive noise {\citep{Negro2016, Farina2016a}}, we get:
\begin{equation}
\label{eqn:convBSSnondetect}
\begin{split}
\mathbf{\tilde{x}}(t)\ &= \ \mathbf{\tilde{H}}_{:,j
_\mathcal{D}} \, \mathbf{\tilde{s}}_{j_\mathcal{D}}(t) \, + \, \mathbf{\tilde{H}}_{:,j_\mathcal{N}} \mathbf{\tilde{s}}_{j_\mathcal{N}}(t) \, + \,\bm{\tilde{\varepsilon}}(t) \ , \\
&= \ \mathbf{\tilde{H}}_{:,j_\mathcal{D}} \, \mathbf{\tilde{s}}_{j_\mathcal{D}}(t) \, + \,\bm{\tilde{\varepsilon}}'(t) \ .
\end{split}
\end{equation}
Therein, $\mathbf{\tilde{H}}_{:,j}$ is the $j$th column of block matrix $\mathbf{\tilde{H}}$ and $\mathbf{\tilde{s}}_{j}$ is the $j$th row of the block vector $\mathbf{\tilde{s}}$.
Further, $\mathcal{D} := \{j_\mathcal{D}^1, ..., j_\mathcal{D}^{N_\mathcal{D}}\}$ is the set of detectable sources, with column indices $j_\mathcal{D}$, and $\mathcal{N} := \{j_\mathcal{N}^1, ..., j_\mathcal{N}^{N_\mathcal{N}}\}$ is the set of non-detectable sources, with column indices $j_\mathcal{N}$.
The total number of (potentially delayed) sources is $R\cdot N=N_\mathcal{D}+N_\mathcal{N}$, with $N_\mathcal{D}$ or $N_\mathcal{N}$ denoting the number of detectable and non-detectable sources, respectively.

% ----------------------------- %
\subsection{The inverse problem}
% ----------------------------- %
The goal of decomposing EMG signals is to estimate the (detectable) motor neuron spike trains only given the extended observation matrix. 
Most state-of-the-art convolution BSS-based decomposition algorithms can be classified as variants of ICA.
In this section, we revisit the fundamentals of ICA to derive new theoretical insights into the performance of motor neuron identification algorithms.

% ----------------------------- %
\subsubsection{Preconditioning}\label{sec:inverse_preconditioning}
% ----------------------------- %
In the attempt to solve the inverse problem, it is common to conduct a few pre-processing steps.  
This includes, if possible, rejecting parts of the noise, e.g., using bandpass or notch filters. 
Due to the linearity of the mixing model (cf. Equation~\ref{eqn:convBSSextendedmatrix}), only linear pre-processing steps should be conducted {\citep{Hyvarinen2001}}.
Next, the extended observations are centred by subtracting the (sample) mean from the extended observations.   
Then, a whitening transformation is applied 
\begin{equation}
\label{eqn:convBSSwhite}
    \mathbf{\tilde{z}}(t) \ = \ \mathbf{V} \mathbf{\tilde{x}}(t)  \ ,
\end{equation}
where the whitening matrix $\mathbf{V}$ is constructed such that the covariance matrix of extended and whitened observations $\mathbf{\tilde{z}}(t)$ is the identity matrix, i.e., $\mathbf{C}_{\tilde{z}\tilde{z}} = \mathbf{I}$.

Note that the whitening transformation is always possible; however, it is not unique. Popular choices are principal component analysis (PCA) or zero-phase component analysis (ZCA) whitening, where the whitening matrix is constructed from the eigendecomposition of the extended signal's covariance matrix {\citep{Krizhevsky2009}}.
Practically, one needs to empirically estimate the covariance matrix given the extended observations. It turns out useful to decompose the covariance matrix of the extended signal in Equation~\eqref{eqn:convBSSnondetect} into {\citep[e.g.,][]{Hyvarinen2001}}
\begin{equation}\label{eqn:covariance_decomposition}
    \mathbf{C}_{\mathbf{\tilde{x}}\mathbf{\tilde{x}}} \ = \ \mathbb{E}\left[\mathbf{\tilde{x}}(t) \mathbf{\tilde{x}}^T(t)\right] \ = \ \mathbf{\tilde{H}}_{:,j
_\mathcal{D}}  \mathbf{C}_{\mathbf{\tilde{s}}_{j_\mathcal{D}}\mathbf{\tilde{s}}_{j_\mathcal{D}}}\mathbf{\tilde{H}}_{:,j
_\mathcal{D}}^T \, + \, \mathbf{C}_{\mathbf{\tilde{\varepsilon}'}\mathbf{\tilde{\varepsilon}'}} \ .
\end{equation}
Therein, $\mathbf{C}_{\mathbf{\tilde{x}}\mathbf{\tilde{x}}}$ denotes the covariance matrix of the extended observations, $\mathbf{C}_{\mathbf{\tilde{s}}_{j_\mathcal{D}}\mathbf{\tilde{s}}_{j_\mathcal{D}}}$ is the covariance matrix of the extended detectable sources and $\mathbf{C}_{\mathbf{\tilde{\varepsilon}'}\mathbf{\tilde{\varepsilon}'}}$ is the covariance matrix of the extended noise including the non-detectable MUs.
Further, $\mathbb{E}(\cdot)$ denotes the expectation operator.
%
The whitening transformation (attempts to) orthogonalise the mixing matrix and decreases the number of parameters to be estimated approximately by a factor of two {\citep{Hyvarinen2000}}. 
Moreover, as the inverse of an orthogonal matrix is its transpose, one can construct the inverse mixing matrix column-by-column. 
