R_j \ &= \ 1.68 \cdot 10^{-10} \cdot S_{j}^{-2.43},\\
\tau_j \ &= \ 7.9 \cdot 10^{-5} \cdot D_{j} \cdot R_j,\\
t_j^\mathrm{ref} \ &= \  0.2 \cdot 2.7 \cdot 10^{-8} \cdot D_{j}^{-1.51},\\
S_{j}\ &= \ 3.96 \cdot 10^{-4} \cdot I_{j}^{0.396},\\
I_{j}\ &= \ 3.85 \cdot 10^{-9} \cdot 9.1^{(j/N)^{1.1831}},
\end{split}
\end{equation}
where $R_j$, $\tau_j$, $t_j^\mathrm{ref}$, $S_{j}$, and $I_{j}$ denote the membrane resistance (unit: \SI{}{\ohm}), membrane time constant (seconds), refractory time (seconds), neuron surface area (unit. \SI{}{m^2}), and rheobase (ampere) for motor neuron $j$ ($j=1,\ldots,N$), with $N=300$ motor neurons. Moreover, $D_{j}$ denote the soma diameter for motor neuron $j$, which was set in a linear fashion from \SIrange[range-phrase=\,\,to\,\, ,range-units = single]{50}{100}{\micro\meter}. We set the time step to $\Delta t=$ \SI{0.1}{\milli\second}  (i.e., \SI{10}{kHz} sampling rate), the resting potential to $V_\mathrm{r}=$ \SI{-70}{\milli\volt}, the threshold potential to $V_{th}=$ \SI{-50}{\milli\volt}, duration $T=$ \SI{60}{\second}, and finally, the leakage and excitability
parameters $g_{j}^\mathrm{L}=g_{j}^\mathrm{E}$ linearly decreasing from 0.25 to 0.15 (smallest to largest).

