\begin{abstract}
For a smooth $k$-dimensional submanifold $\Sigma$ of a $d$-dimensional compact Riemannian manifold $M$, we extend the $L^p(\Sigma)$ restriction bounds of Burq-Gérard-Tzvetkov \cite{bgt2007}---originally proved for individual Laplace--Beltrami eigenfunctions---to arbitrary systems of $L^2(M)$-orthonormal functions. Our bounds are essentially optimal for every triple $(k,d,p)$ with $p\ge2$, except possibly when
$
d\ge3,\quad k=d-1,\quad 2\le p\le4.
$ This work is inspired by Frank and Sabin \cite{frank2017}, who established analogous $L^p(M)$ bounds for $L^2(M)$-orthonormal systems.
\end{abstract}
\maketitle

\section{Introduction}
	Let $(M,g)$ be a compact boundaryless Riemannian manifold of dimension $d\geq2$, and let $\Delta_g$ be the corresponding Laplace--Beltrami operator on $M$.  Let $e_\lambda$ be an $L^2$-normalized eigenfunction of $\Delta_g$, that is,
 \[-\Delta_g e_\lambda=\lambda^2e_\lambda,\quad \text{and }\int_M |e_\lambda|^2\, dV_g=1.\]

	Studying how such eigenfunctions concentrate on a given manifold is of great interest. One important way is to study the growth of the $L^p$ norms $\|e_\lambda\|_{L^p(M)}$.  It is a classical result of Sogge \cite{sogge1988} that the $L^p$ norms of $e_\lambda$ satisfy
	\begin{equation}\label{Slp}\|e_\lambda\|_{L^p{(M)}}\le C\lambda^{\sigma{(p,d)}}\|e_\lambda\|_{L^2(M)},\end{equation}
	where $2\le p\le\infty$ and $\sigma(p,d)$ is given by
	\begin{eqnarray}\sigma(p,d)=
	\begin{cases}
	\dfrac{d-1}{2}\bigg(\dfrac{1}{2}-\dfrac{1}{p}\bigg), &\text{if }2\le p\le \dfrac{2(d+1)}{d-1},\cr d\bigg(\dfrac{1}{2}-\dfrac{1}{p}\bigg)-\dfrac{1}{2}, &\text{if }\dfrac{2(d+1)}{d-1}\le p\le\infty. \end{cases}
	\end{eqnarray}
	These estimates are the best possible for general Riemannian manifolds since they are achieved on the standard sphere $\mathbb{S}^d$. These bounds of Sogge have been further improved and generalized under various geometric assumptions. We refer the reader to the articles \cite{sogge2002,bgt2004,bgt2005, sogge2017,blair2018,sogge2019,canzani2020,blair2022}  for further discussions. 

In 2017, Frank and Sabin \cite{frank2017} generalized the bounds \eqref{Slp} to systems of orthonormal functions. To describe their results, we define the spectral projection operator
	$$\Pi_{\lambda}:=\mathds{1}(\sqrt{-\Delta_g}\in I_\lambda),\quad \text{where }I_\lambda:=[\lambda,\lambda+1)$$
	and the spectral cluster $$E_{\lambda}:=\Pi_{\lambda}L^2(M).$$   Let  $Q\subset E_{\lambda} $  be a linear subspace of $E_{\lambda}$ and let $\{f_j\}_{j\in J}$ be an orthonormal basis of $Q$.  
  Frank and Sabin \cite{frank2017} proved that 
	\begin{equation}\label{2}
	\Biggl\|\sum_{j\in J}t_j|f_j|^2\Biggr\|_{L^{p/2}(M)}\leq C\lambda^{2\sigma(p,d)}\|\{t_j\}\|_{l^{\alpha(d,p)}},
	\end{equation}
 where

 \begin{eqnarray}\alpha(d,p)=
	\begin{cases}
	\dfrac{2p}{p+2}, &\text{if }2\leq p\le \dfrac{2(d+1)}{d-1},\cr \dfrac{p(d-1)}{2d}, &\text{if }\dfrac{2(d+1)}{d-1}\leq p\leq\infty. \end{cases}
	\end{eqnarray}
In addition, Frank and Sabin showed that this exponent $\alpha(d,p)$ is sharp by constructing explicit examples on the two-sphere. Sogge's bounds \eqref{Slp} corresponds to the case when $\dim Q=1$. Furthermore, since $\alpha(d,p)> 1$ for $p>2$, these bounds improve on those obtained by simply applying triangle inequality (or Minkowski inequality) to \eqref{Slp} in this case. This gain is owing to the orthogonality of $\{f_j\}_{j\in J}$ over $L^2(M)$.

In the work of Burq--G\'erard--Tzvetkov \cite{bgt2007} (see also \cite{hu2009}), $L^p$ estimates similar to \eqref{Slp} have been established for the restriction of eigenfunctions to a submanifold. In what follows, let $\Sigma\subset M$ be a smoothly embedded submanifold of dimension $k$. Let
${\delta(k,d,p)}$ be
\begin{align*}
&\delta(d-1,d,p)=\begin{cases}
\dfrac{d-1}{4}-\dfrac{d-2}{2p},   ~~~~\text{if}~2\leq p<\dfrac{2d}{d-1} ,\\
\dfrac{d-1}{2}-\dfrac{d-1}{p},~~~~\text{if}~\dfrac{2d}{d-1}< p\leq\infty,
\end{cases}\\
&\delta(d-2,d,p)=
\frac{d-1}{2}-\frac{d-2}{p}
,\ \text{if }2\le p\leq\infty,\\
&\delta(k,d,p)=\frac{d-1}{2}-\frac{k}{p}, \text{ if }1\leq k\leq d-3\text{ and }~2\leq p\leq\infty.
\end{align*}
Burq--G\'erard--Tzvetkov proved the following sharp restriction bounds
\begin{equation}\label{lp restriction}\|e_\lambda\|_{L^p(\Sigma)}\le C\lambda^{{\delta(k,d,p)}}\|e_\lambda\|_{L^2(M)},\end{equation}
except a $(\log\lambda)^{\frac{1}{2}}$ loss for $(p,k)=(\frac{2d}{d-1},d-1)$ and $(p,k)=(2,d-2)$.

 A couple of years later, Hu \cite{hu2009} gave another proof of \eqref{lp restriction} and removed the $\log$ loss for the case $(p,k)=(\frac{2d}{d-1},d-1)$. Recently, the second author and Zhang \cite{wang2021} removed the $\log$ loss for totally geodesic submanifolds and curves with non-vanishing curvature in the $(p,k)=(2,d-2)$ case. The bounds \eqref{lp restriction} have been improved and generalized under various geometric assumptions. See, e.g., \cite{chen2014,xi2017,zhang2017,blair2018,xi2019,gao2024refined}. Moreover, certain $L^p(\Sigma)$ restriction bounds have been shown to be connected to the $L^p(M)$ norm of eigenfunctions via Kakeya--Nikodym norms. See, e.g., \cite{bourgain2009,sogge2011,bs2015,bs2015b,miao2016,bs2017}.

In this article, inspired by \eqref{2},  we generalize \eqref{lp restriction} to systems of orthonormal eigenfunctions $\{f_j\}_{j\in J}$.  To be more precise, let $\Lambda = \Lambda(k,d,p)$ denote the square of the current known state-of-the-art bounds for a single eigenfunction, i.e.
$$\Lambda(k,d,p) = \begin{cases}
\lambda^{2{\delta(k,d,p)}},   ~~~~\text{if}~(p,k)\neq(2,d-2) ,\\
\lambda^{2{\delta(k,d,p)}}\log\lambda,~~~~\text{if}~(p,k)=(2,d-2).
\end{cases}$$
We are concerned with estimates of the form
\begin{equation}\label{3}
		\Biggl\|\sum_{j\in J} t_j\,|f_j|^{2}\Biggr\|_{L^{p/2}(\Sigma)}
  \le C\,\Lambda\, 
       \| \{t_j\}\|_{\ell^{\alpha}(J)}.
	\end{equation}

A result like \eqref{3} is natural in view of \eqref{2}. 



 Our first result establishes optimal bounds in the case $\operatorname{codim}\Sigma \ge 2$.

\begin{theorem}\label{codim2}
Suppose that $d\ge3$ and $1\le k\le d-2$. For any $p\in[2,\infty],$ $1\le\alpha\le\frac{p}{2}$, there exists a constant $C>0$ such that
\[
  \Biggl\|\sum_{j\in J} t_j\,|f_j|^{2}\Biggr\|_{L^{p/2}(\Sigma)}
  \le C\,\Lambda \, 
       \| \{t_j\}\|_{\ell^{\alpha}(J)}.
\]
The range of $\alpha$ is sharp.
\end{theorem}

The situation is far more delicate in codimension $1$.  Nonetheless, we are able to prove essentially sharp bounds when $\dim M = 2$. Let
\[
(\alpha(k,d,p), h(k,d,p)):=
\begin{cases}

(\max\{2,\frac{p}{2}\},     \min\{\frac{1}{2},\frac{2}{p}\})                                  & (k,d)=(1,2),\\[4pt]

(\tfrac{2p}{p+2},0)                          & k=d-1,\; 2\le p<\tfrac{2d}{d-1},\\[4pt]
(\tfrac{2p(d-2)}{4d-p-4},\tfrac{2d-p}{p(d-2)})                  & k=d-1,\; \tfrac{2d}{d-1}\le p\le 4,\\[4pt]
(\tfrac{p}{2},\tfrac{2}{p})                            & k=d-1,\; 4\le p\le\infty.
\end{cases}
\]


\begin{theorem}\label{d2}
Sppose that $d=2$ and $k=1.$

\begin{enumerate}[(i)]
\item For any $p\in[2,4)\cup(4,\infty]$ and 
      $\alpha\in[1,\alpha(1,2,p))$ there exists $C_{\alpha} >0$ such that
      \begin{equation}\label{f33}
        \Biggl\|\sum_{j\in J} t_j\,|f_j|^{2}\Biggr\|_{L^{p/2}(\Sigma)}
        \le
        C_{\alpha} \,
        \Lambda \,
        \|\{t_j\}\|_{\ell^{\alpha}(J)}.
      \end{equation}

\item For any $p\in[2,\infty]$ there exists $C>0$ such that
      \begin{equation}\label{f22}
        \Biggl\|\sum_{j\in J} t_j\,|f_j|^{2}\Biggr\|_{L^{p/2}(\Sigma)}
        \le
        C\,
         (\log\lambda)^{h(1,2,p)}\Lambda\,
       \,
        \|\{t_j\}\|_{\ell^{\alpha(1,2,p)}(J)}.
      \end{equation}

\item  When $\Sigma$ is a great circle on the standard two-sphere $M$, the exponent $\alpha(1,2,p)$ are essentially sharp.
\end{enumerate}
\end{theorem}






In higher dimensions, for submanifolds of codimension~$1$ we obtain the following result.
The exponent $\alpha(d-1,d,p)$ is the best possible for $4\le p\le\infty$.
\begin{theorem}\label{codim1}
Suppose that $d\ge3$ and $k=d-1$. 



\begin{enumerate}[(i)]
\item For any $p\in(4,\infty]$ and $\alpha\in[1,\alpha(d-1,d,p))$
      there exists $C_{\alpha}>0$ such that
      \begin{equation}\label{j2}\Biggl\|\sum_{j\in J} t_j\,|f_j|^{2}\Biggr\|_{L^{p/2}(\Sigma)}
        \le
        C_\alpha\,\Lambda
        \bigl\|\{t_j\}\bigr\|_{\ell^{\alpha}(J)}.
      \end{equation}

\item For any $p\in[2,\infty]$ there exists $C>0$ such that
      \begin{equation}\label{j1}\Biggl\|\sum_{j\in J} t_j\,|f_j|^{2}\Biggr\|_{L^{p/2}(\Sigma)}
        \le
        C\,
        (\log\lambda)^{h(d-1,d,p)}\Lambda
        \bigl\|\{t_j\}\bigr\|_{\ell^{\alpha(d-1,d,p)}(J)}.
      \end{equation}




\item When $M$ is the standard $d$-sphere, the exponent $\alpha(d-1,d,p)$ is essentially sharp for $4\le p\le\infty$.
\end{enumerate}
\end{theorem}






