\section{Schatten classes}\label{sec 2}		
In this section, we recall some fundamental properties of Schatten class operators and review a duality principle established by Frank and Sabin.
Let $\mathfrak{H}$ and $\mathfrak{K}$ be complex, separable Hilbert spaces, and denote by $\mathfrak{B}_0(\mathfrak{H, \mathfrak{K}})$  the space of compact linear operators from $\mathfrak{H}$ to $\mathfrak{K}$. For $T\in \mathfrak{B}_0(\mathfrak{H, \mathfrak{K}})$, the operator 
$|T|:=(T^*T)^{1/2}$ is compact and positive. Its eigenvalues, which are non-negative, are called the singular values of $T$, and are arranged in decreasing order as $\sigma_1\geq\sigma_2\geq\cdots\geq0$. For $1\leq p\leq\infty $, the Schatten class $\mathfrak{S}^p(\mathfrak{H},\mathfrak{K})$ consists of all compact operators $T$ whose singular value(counted according to multiplicity) form a sequence in $l^p$. Naturally, the Schatten norm of $T$ is defined by the $l^p$ norm of the singular value sequence, that is,
\[\big\|T\big\|_{\mathfrak{S}^p(\mathfrak{H},\mathfrak{K})}:=\Bigl(\sum_{j\geq0}\sigma^p_j\Bigr)^{1/p},\]
with the standard modification when $p=\infty.$
  When $\mathfrak{H}=\mathfrak{K}$, we write $\mathfrak{S}^p(\mathfrak{H}):=\mathfrak{S}^p(\mathfrak{H},\mathfrak{H})$ and $\mathfrak{B}_0(\mathfrak{H}):=\mathfrak{B}_0(\mathfrak{H},\mathfrak{H})$. For further details, we refer the reader to Simon’s monograph \cite{simon2005}.

 We will require the following lemma from \cite[Theorem 2.7]{simon2005}.
  \begin{lemma}[Theorem 2.7 \cite{simon2005}]\label{z1}
    Let $A$ and $C$ be bounded operators on $\mathfrak{H}.$ Then for all $B\in\mathfrak{B}_0(\mathfrak{H})$ and $1\leq p\leq\infty$, we have
$$\|ABC\|_{\mathfrak{S}^p(\mathfrak{H})}\leq\|A\|\|C\|\|B\|_{\mathfrak{S}^p(\mathfrak{H})}.$$
Here $\|{}\cdot{}\|$ denotes the operator norm on $\mathfrak H.$
  \end{lemma}

We now review a well-known duality principle for Schatten class operators, as presented in \cite[Lemma 3]{sabin2017}.
\begin{lemma}[Duality principle]\label{l1}
	Let $\mathfrak{H}$ be a separable Hilbert space. For $2\leq p\leq \infty$, $\alpha\geq1$, with $1/\alpha+1/\alpha'=1/p+1/p'=1$, suppose that $T$ is a bounded operator from $\mathfrak{H}$ to $L^{p}(\mathbb{R}^d)$. Then the following are equivalent.
	\begin{enumerate}[(1)]
		\item  There exists a constant $C>0$ such that
		\begin{equation}\label{a1}
\Big\|WTT^*\overline{W}\Big\|_{\mathfrak{S}^{\alpha'}(L^2(\mathbb{R}^d))}\leq C\|W\|^2_{L^{2p/(p-2)}(\mathbb{R}^d)},  ~~~\text{for all }W\in L^{2p/(p-2)}(\mathbb{R}^d,\mathbb{C}).
		\end{equation}

		\item  For any orthonormal system $\{f_j\}_{j\in J}$ in
		$\mathfrak{H}$ and any sequence $\{t_j\}_{j\in J}\subset \mathbb{C}$, there is a constant $C'$ such that
		\begin{equation}\label{a2}
		\Biggl\|\sum_{j\in J}t_j|Tf_j|^2\Biggr\|_{L^{p/2}(\mathbb{R}^d)}\leq C'\Biggl(\sum_{j\in J}|t_j|^{\alpha}\Biggr)^{1/\alpha},
		\end{equation}
	 Moreover, the values of the optimal constants $C$ and $C'$ coincide. 
	\end{enumerate} 
\end{lemma}
If one examines the proof of the above lemma in \cite{sabin2017}, one can see that this duality principle is a direct consequence of the duality between Lebesgue $L^p$ spaces.



\section{Approximate projection operators
}\label{sec 3}
In this section, we perform the standard reduction introduced by Sogge \cite{sogge2017} and collect a few key oscillatory‐integral estimates from \cite{bgt2007}.  Sogge’s idea is to consider an operator that reproduces eigenfunctions.  Fix a small constant $\epsilon_0>0$ and let $\lambda\ge1$.  Choose a Schwartz function $\chi$ such that 
\[
\chi(0)=1,\quad \chi(t)>\tfrac12\text{ for }t\in[0,1],
\quad\text{and}\quad
\widehat\chi(t)=0\quad\text{unless }|t|\in[\epsilon_0,2\epsilon_0].
\]
Define
\[
\chi_{\lambda}f
:=\chi\bigl(\sqrt{-\Delta_g}-\lambda\bigr)f
=\frac{1}{2\pi}\int_{\epsilon_0}^{2\epsilon_0}
\bigl(e^{it\sqrt{-\Delta_g}}f\bigr)\,e^{-it\lambda}\,\widehat\chi(t)\,dt.
\]
For $\epsilon_0\ll1$ and $|t|\le2\epsilon_0$, a local‐coordinate parametrix shows that $e^{it\sqrt{-\Delta_g}}$ is a Fourier integral operator.  A stationary‐phase argument then gives the following slight variant of \cite[Lemma 5.1.3]{sogge2017}, as in \cite{bgt2007,sogge2011}.

\begin{lemma}\label{l0}
  Let $\epsilon_0>0$ be smaller than one-tenth of the injectivity radius of $(M,g)$.  
  In local coordinates,
  \[
    \chi_{\lambda}f(x)
    =\lambda^{\frac{d-1}{2}}
     \int_{M}e^{\,i\lambda\psi(x,y)}\,a_{\lambda}(x,y)\,f(y)\,dy
    +R_{\lambda}f(x),
  \]
  where
  \[
    {\rm supp\,} a_{\lambda}
    \subset
    \bigl\{(x,y)\colon\tfrac{\epsilon_0}{2}\le d_g(x,y)\le \epsilon_0\bigr\},
    \qquad
    \psi(x,y)=-d_g(x,y),
  \]
  and $a_{\lambda}\in C^{\infty}_0$ satisfies 
  \[
    |\partial_{x,y}^\alpha a_{\lambda}(x,y)|\le C_\alpha
    \quad\text{for all multi‐indices }\alpha.
  \]
  Moreover, for every $N\in\mathbb Z_+$ and $2\le p\le\infty$ there is $C_{N,p}$ so that
  \[
    \|R_{\lambda}\|_{L^2\to L^p}\le C_{N,p}\,\lambda^{-N}.
  \]
\end{lemma}

\begin{remark}
  By a partition of unity we may also assume $a_\lambda(x,y)$ is supported in small coordinate‐chart neighborhoods of fixed points $x_0,y_0\in M$ with 
  $d_g(x,y)\in[\epsilon_0/2,\epsilon_0]$, both lying inside the geodesic ball $B(x_0,10\epsilon_0)$.  We can always take $\epsilon_0>0$ smaller if needed.
\end{remark}
Define
   \[
    T_{\lambda}f(x)
    =
     \int_{M}e^{\,i\lambda\psi(x,y)}\,a_{\lambda}(x,y)\,f(y)\,dy.
  \]
The approximate projection operator $\chi_\lambda$ is usually called a reproducing operator since it reproduces eigenfunctions by $\chi_\lambda e_\lambda=e_\lambda$.  So it suffices to consider
the operator norm estimates of $T_{\lambda}$ to get the eigenfunction estimates, as $R_{\lambda}$ satisfies much
better bounds than we want to prove.

\section{Proof of Theorem \ref{d2}}\label{sec 4}
We are now ready to prove Theorem \ref{d2}. 
\begin{proof}[Proof of Theorem \ref{d2}]
We begin by establishing the second part of the theorem, namely, the bound stated in inequality \eqref{f22}.
Recall that the operator $\chi_{\lambda}$ is defined by
$$\chi_{\lambda}f:=\chi(\sqrt{-\Delta_g}-\lambda)f=\frac{1}{2\pi}\int^{2\epsilon_0}_{\epsilon_0}(e^{it\sqrt{-\Delta_g}}f)e^{-it\lambda}\hat{\chi}(t)\,dt.$$
Since $\lambda_j\in[\lambda,\lambda+1]$ for $j\in J$, and  $\chi>1/2$ on $[0,1]$,  it follows that 
	$$\sum_{j\in J}t_j| f_j|^2\leq 2\sum_{j\in J}t_j|\chi_{\lambda} f_j|^2.$$
 Therefore, establishing the second part of Theorem \ref{d2} reduces to proving the following estimate involving $\chi_{\lambda} f_j$:
	\begin{equation}\label{g20}
	\Biggl\|\sum_{j\in J}t_j|\chi_{\lambda} f_j|^2\Biggr\|_{L^{p/2}(\Sigma)}\le C\lambda^{2\delta{(p)}}(\log\lambda)^{h(p)}\Big\|\{t_j\}\Big\|_{l^{\alpha(p)}(J)}.
	\end{equation}
	By Lemma \ref{l1}, this inequality is equivalent to the Schatten norm estimate
	\begin{equation}\label{g00}
\Big\|W{\chi}_{\lambda}\chi^{*}_{\lambda}\overline{W}\Big\|_{\mathfrak{S}^{(\alpha(p))'}(L^2(\Sigma))}\le C\lambda^{2\delta(p)}(\log\lambda)^{h(p)}\|W\|^2_{L^{2p/(p-2)}(\Sigma)},~~~{\text{for all}~}W\in L^{2p/(p-2)}(\Sigma),
	\end{equation}
	where $C$ is independent of $W$ and $\lambda$.


	Note that, by Lemma \ref{l0}, $R_{\lambda}$ is
an operator that always contributes a term rapidly decaying in $\lambda$, it suffices to prove the bound
	\begin{equation}\label{g24}
	\Big\|WT_{\lambda}T^{*}_{\lambda}\overline{W}\Big\|_{\mathfrak{S}^{(\alpha(p))'}(L^2(\Sigma))}\le C\lambda^{2\delta(p)-1}(\log\lambda)^{h(p)}\|W\|^2_{L^{2p/(p-2)}(\Sigma)}.
	\end{equation}

	First, consider the case $p=\infty$, which corresponds to $(\alpha(p))'=1$.  Then we have
	\begin{equation}\label{g23}
	\begin{aligned}
\Big\|WT_{\lambda}T^{*}_{\lambda}\overline{W}\Big\|_{\mathfrak{S}^{1}(L^2(\Sigma))}
	&= \|WT_{\lambda} \|^2_{\mathfrak{S}^{2}(L^2(M)\to L^2(\Sigma))}\\
 &=\int_{\Sigma}\int_M|W(x)|^2|T_{\lambda}(x,y)|^2\,dy\,dx\\
 &\leq C\|W\|^2_{L^2(\Sigma)},
	\end{aligned}
	\end{equation}
    where $T_{\lambda}(x,y)=e^{-i\lambda d_g(x,y)}a_{\lambda}(x,y)$ is the kernel function associated with $T_{\lambda}$.
    Here we have used the fact that  if 
  \[
    S : L^2(M)\longrightarrow L^2(\Sigma)
  \]
  is a Hilbert–Schmidt operator with integral kernel $S(x,y)$, then
  \[
    \big\|S\big\|_{\mathfrak S^2(L^2(M)\to L^2(\Sigma))}^2
    =
    \int_{\Sigma}\!\!\int_M \bigl|S(x,y)\bigr|^2\,dy\,dx.
  \]

Next we prove \eqref{g24} for $p=4$.  Once this case is established, the
range $4\le p\le\infty$ follows immediately by interpolation.
Because $\Sigma$ is compact, Hölder’s inequality implies that for every
$2\le p<4$,
\[
  \Biggl\|\sum_{j\in J} t_j\,|\chi_{\lambda}f_j|^{2}\Biggr\|_{L^{p/2}(\Sigma)}
  \;\lesssim\;
  \Biggl\|\sum_{j\in J} t_j\,|\chi_{\lambda}f_j|^{2}\Biggr\|_{L^{2}(\Sigma)}.
\]
Hence \eqref{f22} is a consequence of \eqref{g24} with $p=4$.

Assume that we are in the geodesic normal coordinate system about $x_0\in M$, and $\Sigma:[0,1]\to M$
parameterized by the arc length $s$ and passes through $x_0$. Partition of unity allows us to assume
that $\Sigma$ is contained in the geodesic ball centered at $x_0$ with radius $\epsilon_0/10$, i.e., $|x(s)|\leqslant \epsilon_0/10$ and $x(0) = 0$, which forces $\epsilon_0/3\leq |y| \leq 4\epsilon_0/3$.
We write
\[\mathcal{T}_{\lambda}(f)(s) :={T}_{\lambda}(f)(x(s))=\int e^{i\lambda\psi(x(s),y)}a(x(s), y)f (y)\,dy,\]
and denote by $\mathcal{K}(s, t)$ the kernel of operator $\mathcal{T}_{\lambda}\mathcal{T}_{\lambda}^{*}$. Then we have
$$\mathcal{K}(s, t)=\int e^{i\lambda[\psi(x(s),y)-\psi(x(t),y)]}a(x(s),y)\overline{a(x(t),y)}\,dy.$$
Our goal is reduced to proving
\begin{equation}\label{gg24}	\Big\|W\mathcal{T}_{\lambda}\mathcal{T}^{*}_{\lambda}\overline{W}\Big\|_{\mathfrak{S}^{2}(L^2(\Sigma))}\lesssim\lambda^{-1/2}(\log\lambda)^{1/2}\|W\|^2_{L^{4}(\Sigma)},~~~{\text{for all}}~ W\in L^{4}(\Sigma),
	\end{equation}
   which is equivalent to 
    \begin{equation}\label{gg25}
    \Big(\int_0^1\int_0^1 |W(x(s))\mathcal{K}(s,t)W(x(t))|^2\,ds\,dt\Big)^{1/2}\lesssim\lambda^{-1/2}(\log\lambda)^{1/2}\|W\|^2_{L^{4}(\Sigma)}.
    \end{equation}

Since $y$ stays in the annulus with inner radius ${\epsilon_0}/3$ and outer radius ${4\epsilon_0}/3$, we can restrict $y$
to the circle with radius $r$. In fact, we can represent $y$ in polar coordinates as $y = r\omega$
(i.e., geodesic polar coordinates on $M$), $\epsilon_0/3\leqslant r\leqslant 4\epsilon_0/3$, $\omega = (\omega_1, \omega_2)\in S^1$ and denote:
\[\psi_r(x(s), \omega) = \psi(x(s), y),~ a_r(x(s), \omega)\overline{a_r(x(t),\omega)} = \kappa(r,\omega)a_r(x(s), \omega)\overline{a_r(x(t),\omega)}\] for some smooth function $\kappa$.
Define 
$$\mathcal{K}_r(s, t)=\int_{\mathbb{S}^{1}} e^{i\lambda[\psi_r(x(s),\omega)-\psi_r(x(t),\omega)]}a_r(x(s),\omega)\overline{a_r(x(t),\omega)}\,d\omega.$$
Then, \[\mathcal{K}(s,t)=\int_{\epsilon_0/3}^{4\epsilon_0/3} \mathcal{K}_r(s,t)\,dr.\]

 By applying \cite[Lemma 3.2]{bgt2007}, we have that $K_r(s,t)$ is bounded by
$$C(1+\lambda|s-t|)^{-1/2},$$ 
and then \[\mathcal{K}(s,t)\lesssim (1+\lambda|s-t|)^{-1/2}.\]
Consequently, the square of the left-hand side of  \eqref{gg25} is bounded by
\begin{equation}\label{gg26}
    \int_0^1\int_0^1 |W(x(s))|^2(1+\lambda|s-t|)^{-1}|W(x(t))|^2\,dt\,ds,
\end{equation}



Applying the Young inequality, we obtain
\begin{align*}
\eqref{gg26}&\leq\|W\|^2_{L^4(\Sigma)}\cdot\Big\|\int^1_0(1+\lambda|s-t|)^{-1}|W(x(t))|^2dt\Big\|_{L^2(0,1)}\\
&\leq\|W\|_{L^4(\Sigma)}^4\cdot\int^1_0(1+\lambda t)^{-1}dt\\
&\lesssim\lambda^{-1}\log\lambda\|W\|_{L^4(\Sigma)}^4.
\end{align*}  
Taking square roots completes the proof of \eqref{gg24}. 

Now we prove the first part of Theorem \ref{d2} (inequality \eqref{f33}), beginning with the case $ 2 \leq p < 4 $.

Let $1<\alpha<2$, and thus $\alpha'>2$. the operator $W\,T_\lambda T_\lambda^{*}\,\overline{W}$
is self-adjoint.  Invoking the Hausdorff–Young theorem for integral
operators \cite[Theorem 1]{russo} and then Young’s inequality we obtain
\begin{align*}
    \Big\|W T_\lambda T_\lambda^* \overline{W}\Big\|_{\mathfrak{S}^{\alpha'}}&\leq\Big(\int^1_0\Big(\int^1_0\big|W(x(s))\mathcal{K}(s,t)\overline{W(x(t))}\big|^{\alpha}\,ds\Big)^{\alpha'/\alpha}\,dt\Big)^{1/\alpha'}\\
    &\leq \|W\|_{L^{2\alpha'}(\Sigma)}\Big(\int^1_0\Big(\int^1_0|W(x(s))|^{\alpha}(1+\lambda|s-t|)^{-\alpha/2}\,ds\Big)^{2\alpha'/\alpha}\,dt\Big)^{1/2\alpha'}\\
    &\le\|W\|^2_{L^{2\alpha'}(\Sigma)}\Big(\int^1_0(1+\lambda|s|)^{-\frac{\alpha}{2}}\,ds\Big)^{1/\alpha}\\
    &\lesssim\lambda^{-1/2}\|W\|^2_{L^{2\alpha'}(\Sigma)}.
\end{align*}

Set $ 2 p / (p - 2) = 2 \alpha' > 4 $, equivalently $ 2 \leq p < 4 $. By the duality principle (Lemma \ref{l1}), the above estimate gives us
\begin{equation}
\label{near2ineq}
\Big\| \sum_j t_j | T_\lambda f_j |^2 \Big\|_{L^{p/2}(\Sigma)} \leq C_p \lambda^{-1/2} \big\| \{t_j\} \big\|_{l^{\alpha}(J)}.
\end{equation}


Since the curve $\Sigma$ is compact, Hölder's inequality implies that for any $2 \le q \le p$, we have
\[
\Big\| \sum_j t_j | T_\lambda f_j |^2 \Big\|_{L^{q/2}(\Sigma)} \leq C_\alpha \lambda^{-1/2} \big\| \{t_j\} \big\|_{l^\alpha(J)}.
\]
Note that we can choose $p$ in \eqref{near2ineq} arbitrarily close to $4$, thus the associated exponent $\alpha$ can be taken arbitrarily close to $2$. This completes the proof for the range $2\le p<4$.


Now let $4<p\leq\infty$.
Note that for any $p_0\in(4,p)$, we have
\begin{align*}
\Big\|WT_{\lambda}T^{\star}_{\lambda}\overline{W}\Big\|_{\mathfrak{S}^2(L^2(\Sigma))}&=\Big(\int^1_0\int^1_0|W(x(s))|^2|\mathcal{K}(s,t)|^2|\overline{W(x(t))}|^2\,ds\,dt\Big)^{1/2}\\
&\leq\|W\|_{L^{2p_0/(p_0-2)}(\Sigma)}\Big\|\int^1_0 |\mathcal{K}(s,t)|^2|W(x(t))|^2\,dt\Big\|^{1/2}_{L^{p_0/2}(0,1)}\\
&\leq\|(1+\lambda|s|)^{-1}\|^{1/2}_{L^{p_0/4}(0,1)}\|W\|^2_{L^{2p_0/(p_0-2)}(\Sigma)}\\
&\leq C_{p_0}\lambda^{-2/p_0}\|W\|_{L^{2p_0/(p_0-2)}(\Sigma)}^2.
\end{align*}
Interpolating this with the trace-class bound 
\eqref{g23} yields
\[
\Big\|WT_{\lambda}T^{\star}_{\lambda}\overline{W}\Big\|_{\mathfrak{S}^{(2p/p_0)'}(L^2(\Sigma))}\leq C_{p_0}\lambda^{-2/p}\|W\|^2_{L^{2p/(p-2)}(\Sigma)}.
\]
By duality this is equivalent to
\[\Biggl\|\sum_{j\in J}t_j|T_{\lambda}f_j|^2\Biggr\|_{L^{p/2}(\Sigma)}\leq C_{p_0}\lambda^{-2/p}\big\|\{t_j\}\big\|_{l^{2p/p_0}(J)}. \]
Since $p_0$ can be taken to be arbitrarily close to $4$, we see that the following holds for any $1\le\alpha<p/2.$
\[\Biggl\|\sum_{j\in J}t_j|T_{\lambda}f_j|^2\Biggr\|_{L^{p/2}(\Sigma)}\leq C_\alpha\lambda^{-2/p}\big\|\{t_j\}\big\|_{l^{\alpha}(J)}, \]
as desired.

\end{proof}




\section{Proof Theorem \ref{codim2} and \ref{codim1}}\label{sec 5}
In this section, we prove Theorem \ref{codim2} and \ref{codim1}. 
Assume that in the geodesic normal coordinate system about $x_0\in M,$ $\Sigma$  is parameterized
by $x(z_1 ,z_2 ,\cdots,z_k),$ $ x(0) = 0$.
Again by a partition of unity, we can assume that (a local piece of) $\Sigma$ is contained
in a small enough geodesic ball about $x_0$, i.e., $|x(z)|\leq \epsilon_0/10,$ which forces $\epsilon_0/3\leq |y| \leq 4\epsilon_0/3$. 
 We write
 $$\mathcal{T}_{\lambda}(f)(z):=T_{\lambda}(f)(x(z))=\int_{M}e^{i\lambda\psi(x(z),y)}a_{\lambda}(x(z),y)f(y)\,dy$$
 and denote by ${K}(x,x')$ the kernel of the operator ${T}_{\lambda}{T}^*_{\lambda}$. Let
 $$\mathcal{K}(z,z'):=K(x(z),x(z'))=\int_Me^{i\lambda[\psi(x(z),y)-\psi(x(z'),y)]}a_{\lambda}(x(z),y)\overline{a_{\lambda}(x(z'),y)}\,dy$$ 
 be the kernel of the operator $\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda}$. We now turn to an estimate from \cite{bgt2007} that will be essential for our analysis.
 \begin{lemma}[Lemma 6.1 in \cite{bgt2007}]\label{l6} For any $(x,x')$,
 	$|{K}(x,x')|\lesssim 1$. 
If $|\psi(x,x')|\gtrsim\lambda^{-1}$, then for  any $N\in\mathbb{Z}^+$, there exists $\epsilon_0\ll1$ so that 
 		\begin{equation}\label{g17}
 		{K}(x,x')=\sum_{\pm}\sum^{N-1}_{n=0}\frac{e^{\pm i\lambda \psi(x,x')}}{(\lambda \psi(x,x'))^{\frac{d-1}{2}+n}}a_n^{\pm}(x,x',\lambda)+b_N(x,x',\lambda),
 		\end{equation}
 	where $a^{\pm}_n,b_n\in C^{\infty}(\mathbb{R}^d\times\mathbb{R}^d\times\mathbb{R})$ and $-\psi(x,y)=d_g(x,y)$ is the geodesic distance
     between $x$ and $x'$.  Furthermore,  $a^{\pm}$ are real, have supports of size $O(\epsilon_0)$ with respect to the first two variables and are uniformly
 	bounded with respect to $\lambda$. Finally
 	\begin{equation}\label{gb}   
 	|b_N(x,x',\lambda)|\lesssim |1+\lambda \psi(x-x')|^{-\frac{d-1}{2}-N}.
  \end{equation}
 \end{lemma}
In view of $$d_g(x(z),x(z'))\sim|z-z'|,$$
 noting that $K$ is bounded, applying Lemma \ref{l6} yields a rough bound on the kernel of $\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda}$
 \begin{equation}\label{g9}
 |K(x(z),x(z'))|\leq C(1+\lambda|z-z'|)^{-\frac{d-1}{2}}.
 \end{equation}
However, this estimate alone is insufficient to achieve our desired bounds. To improve upon it, we follow the approach in \cite{bgt2007} by exploiting the oscillatory nature of the phase in $K(x(z),x(z'))$. This involves dyadically decomposing the kernel based on the size of $|z-z'|$. We now provide a detailed description of this decomposition and collect the key estimates that will be instrumental in our proof.

 We fix a compactly supported bump function $\chi_0\in C^{\infty}_0(\mathbb{R}^k),$ so that $ \mathrm{supp} \,\chi_0\in
\{x\in\mathbb{R}^k:|x|\leq C\}$.
Additionally, let  $\tilde{\chi}\in C^{\infty}_0(\mathbb{R}^k)$  be supported in the set $\{x\in{\mathbb{R}^k}:\frac{1 }{2}<|x|<2\}$ such that there is a partition of unity on $\{x\in\mathbb{R}^k: |x|<1\}$ of the form
\begin{equation}\label{g10}
1=\chi_0(\lambda x)+\sum^{\log\lambda/\log2}_{j=1}\tilde{\chi}(2^jx).
\end{equation}
Using this, we decompose the kernel  $\mathcal{K}(z,z')$ dyadically:
\begin{equation}\label{dyadic}
\begin{aligned}
\mathcal{K}(z,z')&=\mathcal{K}(z,z')\chi_0(\lambda(z-z'))+\sum^{\log\lambda/\log2}_{j=1}\mathcal{K}(z,z')\tilde{\chi}(2^j(z-z'))\\
&= \mathcal{K}_0(z,z')+\sum^{\log\lambda/\log2}_{j=1}\mathcal{K}_j(z,z').
\end{aligned}
\end{equation}
In the proof of Theorem \ref{codim2}, we will estimate the contribution of each dyadic piece $\mathcal K_j$. To facilitate these estimates, we rely on the following crucial estimates from \cite{bgt2007}.
\begin{lemma}[Proposition 6.3 in \cite{bgt2007}]\label{l7}
For sufficiently large $j$, let $(\mathcal{T}_{\lambda}\mathcal{T}_{\lambda}^*)_j$ be the operator whose integral kernel is $\mathcal{K}_j(z,z')$. Then it satisfies the estimate
	\begin{align}
	&\|(\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda})_j f\|_{L^{\infty}(\Sigma)}\lesssim\Big(\frac{2^j}{\lambda}\Big)^{\frac{d-1}{2}}\|f\|_{L^1(\Sigma)},\label{g26}\\
	&\|(\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda})_j f\|_{L^2(\Sigma)}\lesssim2^{-j k}\Big(\frac{2^j}{\lambda}\Big)^{\frac{d-1}{2}+\frac{k-1}{2}}\|f\|_{L^2(\Sigma)}.\label{g27}
	\end{align}
\end{lemma}
We remark that the operator corresponding to $\mathcal K_0$ satisfies \eqref{g26} and \eqref{g27} with $2^j\sim\lambda,$ and thus we do not need to handle it separately. 
    Furthermore, note that the operator $(\mathcal{T}_\lambda\mathcal{T}^*_\lambda)_j$ in Proposition~6.3 of \cite{bgt2007} does not include the remainder term $b_N$. However, one readily verifies that the same estimates hold when $b_N$ is included, provided $N$ is chosen sufficiently large. Indeed, by \eqref{gb}, if $N$ in Lemma~\ref{l6} is sufficiently large, then the operator with kernel
\[
b_N(z,z',\lambda)\,\tilde\chi\bigl(2^j(z-z')\bigr)
\]
satisfies \eqref{g26} and \eqref{g27} via Young’s inequality.
\subsection{Proof of Theorem \ref{codim2}}

We begin by adopting the same strategy used in the two-dimensional case.
By the same reasoning that led to inequality \eqref{g24}, it suffices to establish that for every $ W \in L^{\frac{2p}{p-2}}(\Sigma) $, the following holds:
\begin{equation}\label{g37}
\|W \, \mathcal{T}_\lambda \mathcal{T}_\lambda^* \overline{W}\|_{\mathfrak{S}^{(p/2)'}(L^2(\Sigma))} \lesssim \lambda^{2\delta(d,k,p) - (d-1)} \|W\|_{L^{\frac{2p}{p-2}}(\Sigma)}^2.
\end{equation}

We shall apply the dyadic decomposition \eqref{dyadic} to the kernel of $\mathcal{T}_\lambda \mathcal{T}_\lambda^*$. This decomposition enables us to leverage Proposition \ref{l7} to obtain bounds on the Schatten norms of the operators $ W (\mathcal{T}_\lambda \mathcal{T}_\lambda^*)_j \overline{W} $. Summing these bounds over all dyadic levels $ j $ then yields the desired Schatten bound for $ W \mathcal{T}_\lambda \mathcal{T}_\lambda^* \overline{W} $.

 By Lemmas \ref{z1} and using the fact that the largest singular value of a compact operator is equal to its operator norm, we have
	\begin{equation}
	\begin{aligned}
\Big\|W(\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda})_j\overline{W}\Big\|_{\mathfrak{S}^{\infty}(L^2(\Sigma))}
	&\leq \|W\|^2_{L^{\infty}(\Sigma)}\|(\mathcal{T}_{\lambda} \mathcal{T}^*_{\lambda})_j\|_{\mathfrak{S}^{\infty}(L^2(\Sigma))}\\
 &=\|W\|^2_{L^{\infty}(\Sigma)}\|(\mathcal{T}_{\lambda} \mathcal{T}^*_{\lambda})_j\|_{L^2(\Sigma)\to L^2(\Sigma)}.\\
	\end{aligned}
	\end{equation}
Inserting the operator‐norm bound $\eqref{g27}$ into the above inequality gives
\begin{equation}\label{g15}
\Big\|W(\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda})_j\overline{W}\Big\|_{\mathfrak{S}^{\infty}(L^2(\Sigma))}\leq C_1 2^{-jk}\Big(\frac{2^j}{\lambda}\Big)^{\frac{d-1}{2}+\frac{k-1}{2}}\|W\|^2_{L^{\infty}(\Sigma)},
\end{equation}
where $C_1$ is a constant that
depends only on the fixed data $(M, \Sigma)$.

 Recalling that $\tilde{\chi}$ is supported in the set $\{x\in{\mathbb{R}^k}:\frac{1}{2}<|x|<2\}$ and applying the kernel estimate
\eqref{g9}, or directly using the bound $\eqref{g26}$, one shows
 \begin{equation}\label{q1}
     \begin{aligned}
\Big\|W(\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda})_j\overline{W}\Big\|_{\mathfrak{S}^{2}(L^2(\Sigma))}&=\Big(\iint_{\Sigma\times\Sigma} \Big|W\mathcal{K}_j(\cdot,\cdot)\overline{W}\Big|^2\Big)^{1/2}\\
         &\leq C_2 \Big(\int_{B^{k}}\int_{B^k }\Big|W(x(z))\Big|^2(1+2^{-j}\lambda)^{-(d-1)}\Big|\overline{W(x(z'))}\Big|^2dzdz'\Big)^{1/2}\\
         &\leq C_2 \Big(\frac{2^j}{\lambda}\Big)^{\frac{d-1}{2}}\|W\|^2_{L^2(\Sigma)},
     \end{aligned}
 \end{equation}
where $B^k$ denotes the unit ball in $\mathbb{R}^k$ and $C_2$ is an absolute constant. Here we used the fact that for every operator $T$ acting on functions on $ L^{2}(\Sigma) $,
$$\big\|T\big\|^2_{\mathfrak{S}^2(L^2(\Sigma))}=\int_{\Sigma}\int_{\Sigma}|T(x,y)|^2\,dx\,dy,$$
where $ T(\cdot, \cdot) $ denotes the integral kernel of  $ T $.

 Interpolating between the bounds \eqref{g15} and \eqref{q1} in the Schatten spaces shows that for any $p_0\geq2$,
\begin{equation}
\Big\|W(\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda})_j\overline{W}\Big\|_{\mathfrak{S}^{2p_0/(p_0-2)}(L^2(\Sigma))}\leq C_1^{\frac{2}{p_0}}C_2^{1-\frac2{p_0}}
2^{-\frac{2jk}{p_0}}\Big(\frac{2^j}{\lambda}\Big)^{\frac{d-1}{2}+\frac{k-1}{p_0}}\|W\|^2_{L^{2p_0/(p_0-2)}(\Sigma)},
\end{equation}
where we take $\frac{2p_0}{p_0-2}=\infty$ as $p_0=2$ and $\frac{2p_0}{p_0-2}=2$ as $p_0=\infty$.
Summing over $1\ll j\leq\log{\lambda}/\log{2}$ yields\footnote{Here we may require $j$ to be sufficiently large by choosing $\epsilon_0$ small.}
\begin{equation}\label{nf2}
\begin{aligned}
\Big\|W\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda}\overline{W}\Big\|&_{\mathfrak{S}^{2p_0/(p_0-2)}(L^2(\Sigma))}
\leq C_1^{\frac{2}{p_0}}C_2^{1-\frac2{p_0}}\lambda^{-\frac{d-1}{2}-\frac{k-1}{p_0}}\sum_{j=1}^{\log\lambda/\log2}2^{j(\frac{d-1}{2}-\frac{k+1}{p_0})}\|W\|^2_{L^{2p_0/(p_0-2)}(\Sigma)}\\
&\leq C_1^{\frac{2}{p_0}}C_2^{1-\frac2{p_0}}\begin{cases}
\lambda^{-\frac{d-1}{2}-\frac{k-1}{p_0}+\frac{d-1}{2}-\frac{k+1}{p_0}}\|W\|^2_{L^{2p_0/(p_0-2)}(\Sigma)},\quad
	\text{if}\quad p_0>\frac{2(k+1)}{d-1},\\
	\lambda^{-\frac{d-1}{2}-\frac{k-1}{p_0}}\|W\|^2_{L^{2p_0/(p_0-2)}(\Sigma)},\qquad\qquad\quad\,\text{if}\quad p_0<\frac{2(k+1)}{d-1},\\
	\lambda^{-\frac{d-1}{2}-\frac{k-1}{p_0}}\log\lambda\|W\|^2_{L^{2p_0/(p_0-2)}(\Sigma)},\qquad\quad\text{if}\quad p_0=\frac{2(k+1)}{d-1}.
\end{cases}
\end{aligned}
\end{equation}
Note that estimate \eqref{nf2} remains valid for any $\Sigma$ with $1 \le \dim \Sigma \le d-1$. In particular, we will later apply \eqref{nf2} in the proof of Theorem \ref{codim1}.

Now we first solve the case where $\dim \Sigma < d - 2$. A direct calculation yields
\begin{equation}\label{n20}
\begin{aligned}
\Big\|W\mathcal{T}_{\lambda}\mathcal{T}^*_{\lambda}\overline{W}\Big\|_{\mathfrak{S}^{1}(L^2(\Sigma))}&=\|W\mathcal{T}_{\lambda} \|^2_{\mathfrak{S}^{2}(L^2(M)\to L^2(\Sigma))}\\
&=\int_{\Sigma}|W(x)|^2\int_M| \mathcal{T}_{\lambda}(x,y)|^2dx'dz\\
&\leq C_3\|W\|^2_{L^{2}(\Sigma)},
\end{aligned}
\end{equation}
where $\mathcal{T}_\lambda(x,y) = e^{-i \lambda d_g(x(z), y)} a_\lambda(x,y)$ is the kernel of $\mathcal{T}_\lambda$ and $C_3$ is a constant that
depends only on the fixed data $(M, \Sigma)$.

For $p_0 > \frac{2(k+1)}{d-1}$, interpolating this estimate with the previous Schatten bounds \eqref{nf2} yields
\begin{equation}\label{nf1}
\Big\| W \mathcal{T}_\lambda \mathcal{T}_\lambda^* \overline{W} \Big\|_{\mathfrak{S}^{\frac{2p}{2p - p_0 - 2}}(L^2(\Sigma))} \leq C_1^{\frac2p}C_2^{\frac{p_0}p-\frac2p}C_3^{1-\frac{p_0}p} \lambda^{-\frac{2k}{p}} \|W\|_{L^{2p/(p-2)}(\Sigma)}^2.
\end{equation}

In particular, choosing $p_0 = 2$, we obtain
\[
\Big\| W \mathcal{T}_\lambda \mathcal{T}_\lambda^* \overline{W} \Big\|_{\mathfrak{S}^{\frac{p}{p-2}}(L^2(\Sigma))} \leq C_1^{\frac2p}C_3^{1-\frac{2}p} \lambda^{-\frac{2k}{p}} \|W\|_{L^{2p/(p-2)}(\Sigma)}^2,
\]
which establishes the desired bound $\eqref{g37}$ for $\dim \Sigma = k < d - 2$.

Next,
when $\dim \Sigma = d - 2$, setting $p_0 = 2$ in \eqref{nf2} yields
\[
\Big\| W \mathcal{T}_\lambda \mathcal{T}_\lambda^* \overline{W} \Big\|_{\mathfrak{S}^\infty(L^2(\Sigma))} \leq C_1 \lambda^{-(d-1)+1} \log \lambda \, \|W\|_{L^\infty(\Sigma)}^2,
\]
which aligns with the desired bound $\eqref{g37}$ for the case $p=2$.

For $2 < p_0 \leq p$, applying the duality principle (see Lemma \ref{l1}) shows that \eqref{nf1} is equivalent to
\begin{equation}
\Biggl\|\sum_{j\in J}t_j|f_j|^2\Biggr\|_{L^{p/2}(\Sigma)}\leq C_1^{\frac2p}C_2^{\frac{p_0}p-\frac2p}C_3^{1-\frac{p_0}p}\lambda^{-\frac{2(d-2)}{p}}\Big\|\{t_j\}\Big\|_{l^{\frac{2p}{p_0+2}}(J)}
\end{equation}
Since the right-hand side norm $\left\| \{ t_j \} \right\|_{l^{\frac{2p}{p_0 + 2}}(J)}$ is increasing in $p_0$ , taking the infimum over $p_0 \in (2,p]$ gives
\[
\Biggl\| \sum_{j \in J} t_j |f_j|^2 \Biggr\|_{L^{p/2}(\Sigma)} \leq C_1^{\frac2p}C_3^{1-\frac{2}p} \lambda^{-\frac{2(d-2)}{p}} \left\| \{ t_j \} \right\|_{l^{\frac{p}{2}}(J)}.
\]
Using the duality principle again, we have
\[
\Big\| W \mathcal{T}_\lambda \mathcal{T}_\lambda^* \overline{W} \Big\|_{\mathfrak{S}^{\frac{p}{p-2}}(L^2(\Sigma))} \lesssim \lambda^{-\frac{2(d-2)}{p}}\|W\|_{L^{2p/(p-2)}(\Sigma)}^2,
\]
completing the proof of $\eqref{g37}$ for $\dim \Sigma = d-2$ when $p > 2$.
\qed
 \subsection{Proof of Theorem \ref{codim1}}

We begin by deriving \eqref{j1}. We observe that inequality \eqref{nf2} covers \eqref{j1} when $2 \leq p \leq \frac{2d}{d-1}$. Therefore, it suffices to consider the case $\frac{2d}{d-1} < p \leq \infty$.

Now we consider the range $4 \leq p \leq \infty$. Recall that $\alpha(d-1,d,p) = \frac{p}{2}$. In particular, when $p = 4$, we have $\alpha(d-1,d,4) = 2$. Applying inequality \eqref{g9} and Young's inequality, we obtain
\begin{equation}\label{f11}
\begin{aligned}
\Big\| W \mathcal{T}_{\lambda} \mathcal{T}_{\lambda}^* \overline{W} &\Big\|_{\mathfrak{S}^2(L^2(\Sigma))} 
= \left( \iint_{B^{d-1} \times B^{d-1}} \left| W(x(z)) K(x(z), x(z')) \overline{W(x(z'))} \right|^2 \, dz\, dz' \right)^{1/2} \\
&\lesssim \left( \iint_{B^{d-1} \times B^{d-1}} |W(x(z))|^2 (1 + \lambda |z - z'|)^{-(d-1)} |\overline{W(x(z'))}|^2 \, dz\, dz' \right)^{1/2} \\
&\lesssim \|W\|_{L^4(\Sigma)} \left\| \int_{B^{d-1}} (1 + \lambda |z - z'|)^{-(d-1)} |\overline{W(x(z'))}| \, dz' \right\|_{L^2(\Sigma)}^{1/2} \\
&\leq \|W\|_{L^4(\Sigma)}^2 \left| \int_{B^{d-1}} (1 + \lambda |z|)^{-(d-1)} \, dz \right|^{1/2} \\
&\lesssim \lambda^{-(d-1)/2} (\log \lambda)^{1/2} \|W\|_{L^4(\Sigma)}^2.
\end{aligned}
\end{equation}

Interpolating this estimate with the Schatten bounds given in \eqref{n20} yields
\[
\Big\| W \mathcal{T}_{\lambda} \mathcal{T}_{\lambda}^* \overline{W} \Big\|_{\mathfrak{S}^{p/(p-2)}(L^2(\Sigma))}
\lesssim \lambda^{-2(d-1)/p} (\log \lambda)^{2/p} \|W\|_{L^{2p/(p-2)}(\Sigma)}.
\]
This completes the proof of \eqref{j1} for the case $4 \leq p \leq \infty$.

Next, consider the range $\frac{2d}{d-1} < p < 4$. By interpolating the bound in \eqref{f11} with inequality \eqref{nf2}—which applies when $\dim \Sigma = d-1$ and $p_0 = \frac{2d}{d-1}$—we obtain
\[
\Big\| W \mathcal{T}_{\lambda} \mathcal{T}_{\lambda}^* \overline{W} \Big\|_{\mathfrak{S}^{\frac{2 p(d-2)}{2 p d - 4 d - 3 p + 4}}(L^2(\Sigma))}
\lesssim \lambda^{-2(d-1)/p} (\log \lambda)^{\frac{2 d - p}{p(d-2)}} \|W\|_{L^{\frac{2 p}{p-2}}(\Sigma)}.
\]
This completes the analysis for $\frac{2 d}{d-1} < p < 4$.

Finally, we turn to the proof of inequality \eqref{j2}. The approach follows a similar pattern to the two-dimensional case. For any $p_0 \in (4, p)$, applying the bound \eqref{g9} and Young's inequality gives
\begin{align*}
\Big\| W \mathcal{T}_{\lambda} \mathcal{T}_{\lambda}^* \overline{W} &\Big\|_{\mathfrak{S}^2(L^2(\Sigma))}
= \left( \iint_{B^{d-1} \times B^{d-1}} |W(x(z))|^2 |K(x(z), x(z'))|^2 |\overline{W(x(z'))}|^2 \, dz\, dz' \right)^{1/2} \\
&\leq \|W\|_{L^{2p_0/(p_0-2)}(\Sigma)} \left\| \int_{B^{d-1}} |K(x(z), x(z'))|^2 |W(x(z'))|^2 \, dz' \right\|_{L^{p_0/2}(B^{d-1})}^{1/2} \\
&\leq \left\| (1 + \lambda |s|)^{-(d-1)} \right\|_{L^{p_0/4}(B^{d-1})}^{1/2} \|W\|_{L^{2p_0/(p_0-2)}(\Sigma)}^2 \\
&\leq C_{p_0} \lambda^{-2(d-1)/p_0} \|W\|_{L^{2p_0/(p_0-2)}(\Sigma)}^2.
\end{align*}
Interpolating this with the trace-class bound in \eqref{n20} yields
\[
\Big\| W \mathcal{T}_{\lambda} \mathcal{T}_{\lambda}^* \overline{W} \Big\|_{\mathfrak{S}^{(2p/p_0)'}(L^2(\Sigma))} \leq C_{p_0} \lambda^{-2(d-1)/p} \|W\|_{L^{2p/(p-2)}(\Sigma)}^2.
\]
 By the duality principle (Lemma \ref{l1}), this is equivalent to
\[
\Biggl\| \sum_{j \in J} t_j |T_{\lambda} f_j|^2 \Biggr\|_{L^{p/2}(\Sigma)} 
\leq C_{p_0} \lambda^{-2(d-1)/p} \left\| \{t_j\} \right\|_{\ell^{2p/p_0}(J)}.
\]
Since $p_0$ can be chosen arbitrarily close to 4, it follows that for any $\alpha < p/2$,
\[
\Biggl\| \sum_{j \in J} t_j |T_{\lambda} f_j|^2 \Biggr\|_{L^{p/2}(\Sigma)} 
\leq C_\alpha \lambda^{-2(d-1)/p} \left\| \{t_j\} \right\|_{\ell^\alpha(J)}.
\]
This concludes the proof.
\qed











\section{Sharpness in dimension two}\label{sec 6}
 In this section, we demonstrate that the estimate in Theorem \ref{d2} is essentially sharp for any intermediate value of $\#J$, except for the logarithmic loss on the two-sphere $\mathbb S^2$. 
 To achieve this, we will utilize a key estimate from \cite{frank2017}. 


  When $M$ is the standard sphere $\mathbb{S}^2$ and $2\leq p\leq\infty$,
  consider an increasing function, $t_{\lambda}=t(\lambda),$ $\lambda>0$, satisfying the following conditions:
 $$\lim_{\lambda\to\infty}t_{\lambda}=+\infty,~~~~~~\lim_{\lambda\to\infty}\dfrac{t_{\lambda}}{\lambda}=0.$$
Our goal is to construct, for sufficiently large $\lambda$, geodesic segments  $\gamma\subset\mathbb{S}^2$ and orthonormal systems $\{f_j\}_{j\in J_{\lambda}}\subset E_{\lambda}$ and $ \{g_j\}_{j\in J_{\lambda}}\subset E_{\lambda}$ with $\#J_{\lambda}\sim t_{\lambda}$, such that the following estimates hold:
 \begin{align}
 &\Big\|\sum_{j\in J_{\lambda}}|f_j|^2\Big\|_{L^{p/2}(\gamma)}\gtrsim\lambda^{1-\frac{2}{p}}t_{\lambda}^{\frac{2}{p}};\label{o1}\\
 &\Big\|\sum_{j\in J_{\lambda}}|g_j|^2\Big\|_{L^{p/2}(\gamma)}\gtrsim\lambda^{\frac{1}{2}}t^{\frac{1}{2}}_{\lambda}.\label{o2}
 \end{align}
 For each $\lambda > 0$, we construct orthonormal systems using spherical harmonics of degree $k \sim \lambda$. Recall that for any spherical harmonic $Y(x)$ of degree $k$ on $L^2(\mathbb{S}^2)$, the Laplace--Beltrami operator satisfies
\[
\Delta_{\mathbb{S}^2} Y(x) = -k(k+1) Y(x).
\]
Let $Y_k^{\alpha_k}$ denote an $L^2$-normalized spherical harmonic of degree $k$, where $\alpha_k \in [-k, k]$. Consider a sequence $\{t_k\}_{k\in\mathbb{N}}$ such that
\[
\lim_{k \to \infty} t_k = +\infty, \quad \text{and} \quad \lim_{k \to \infty} \frac{t_k}{k} = 0.
\]
Assuming that for sufficiently large $k$, $t_k \leq \frac{k}{2}$, we claim the following:
\begin{itemize}
 \item  The orthonormal system $\{Y_k^{\alpha_k}\}_{\alpha_k \in [t_k, 2t_k] \cap \mathbb{Z}}$ satisfies the bound corresponding to \eqref{o1}.
\item  The orthonormal system $\{Y_k^{\alpha_k}\}_{\alpha_k \in [k - 2t_k,\, k - t_k] \cap \mathbb{Z}}$ satisfies the bound corresponding to \eqref{o2}.
\end{itemize}
To verify these claims, we will utilize a key estimate from \cite{frank2017}, which provides essential bounds for these spherical harmonics.
\begin{lemma}[Proposition 15 in \cite{frank2017}]\label{l14}
If we parameterize points in $\mathbb{S}^2$ by usual spherical coordinates
$(\theta,\varphi)\in[0,\pi]\times[0,2\pi)
$, then 
\begin{enumerate}[(1)]
    \item 
there exist $\eta_1>0,~K\geq1,$ and $c>0$
such that for all $k\geq K$, $\eta_1t_k/k\leq\theta\leq\frac{\pi}{2}$ and  $0\leq\varphi\leq2\pi$, 
$$\sum_{\alpha_k\in [t_k,2t_k]\cap\mathbb{Z}}|Y^k_{\alpha_k}(\theta,\varphi)|^2\geq c\,\frac{t_k}{\sin \theta};$$ 
\item there exist $\eta_2>0, K\geq 1$, and $c>0$ such that for all $k\geq K$, $0\leq\theta\leq\eta_2(t_k/k)^{1/2}$ and  $0\leq\varphi\leq2\pi$,
$$\sum_{\alpha_k\in [k-2t_k,k-t_k]\cap\mathbb{Z}}|Y^k_{\alpha_k}(\pi/2-\theta,\varphi)|^2\geq c\,k^{1/2}t_k^{1/2}.$$
\end{enumerate}
\end{lemma}
Now, we are prepared to proceed with the proof of our sharpness result.
\begin{theorem}
    There exist $c>0 $, $K\geq1$ and curves $\gamma_1$ and $\gamma_2$ on $\mathbb{S}^2$ so that for all $k\geq K$
    and $2\leq p\leq\infty$ one has 
   \begin{align}
    &\Big\|\sum_{\alpha_k\in [t_k,2t_k]\cap\mathbb{Z}}|Y^k_{\alpha_k}(\theta,\varphi)|^2\Big\|_{L^{p/2}(\gamma_1)}\geq Ck^{1-\frac{2}{p}}t^{\frac{2}{p}}_k;\label{s1}\\
    &\Big\|\sum_{\alpha_k\in [k-2t_k,k-t_k]\cap\mathbb{Z}}|Y^k_{\alpha_k}(\theta,\varphi)|^2\Big\|_{L^{p/2}(\gamma_2)}\geq Ck^{\frac{1}{2}}t^{\frac{1}{2}}_k.\label{s2}
    \end{align}
    In particular, Theorem \ref{d2} is essentially saturated by \eqref{s1} for $4\leq p\leq\infty$, and by $\eqref{s2}$ for $2\leq p\leq 4$.
\end{theorem}
\begin{proof}
   We first establish inequality \eqref{s1}. Consider the curve $\gamma_1$ on $\mathbb{S}^2$ parameterized by $\gamma_1(\theta)=(\sin\theta,~0,~\cos\theta)$, with $\theta\in[0,\pi/2].$ Applying item (1) of Lemma \ref{l14}, we obtain
    \begin{equation*}
        \begin{aligned}
\Big\|\sum_{\alpha_k\in [t_k,2t_k]\cap\mathbb{Z}}|Y^k_{\alpha_k}(\theta,\varphi)|^2\Big\|^{p/2}_{L^{p/2}(\gamma_1)}&\ge\int^{\pi/2}_{\eta_1t_k/k}\Big(\sum_{\alpha_k\in [t_k,2t_k]\cap\mathbb{Z}}|Y^k_{\alpha_k}(\theta,0)|^2\Big)^{p/2}\,d\theta\\
&\gtrsim \int^{\pi/2}_{\eta_1t_k/k}\Big(\frac{t_k}{\sin\theta}\Big)^{\frac{p}{2}}\,d\theta\gtrsim  t^{p/2}_k\int^{2\eta_1t_k/k}_{\eta_1t_k/k}{\theta}^{-\frac{p}{2}}\,d\theta\\
&\gtrsim   k^{\frac p2-1}t_k.\\
        \end{aligned}
    \end{equation*}
Next, to prove \eqref{s2}, consider the curve $\gamma_2$ as the equator, that is, $\theta=\pi/2$. Applying item (2) of Lemma \ref{l14}, we conclude that
\begin{align*}
    \Big\|\sum_{\alpha_k\in [k-2t_k,k-t_k]\cap\mathbb{Z}}|Y^k_{\alpha_k}(\theta,\varphi)|^2\Big\|^{p/2}_{L^{p/2}(\gamma_2)}&=\int^{2\pi}_0\Big(\sum_{\alpha_k\in [k-2t_k,k-t_k]\cap\mathbb{Z}}|Y^k_{\alpha_k}(\pi/2,\varphi)|^2\Big)^{p/2}d\varphi\\
    &\geq \int^{2\pi}_0\big(Ck^{\frac{1}{2}}t_k^{\frac{1}{2}}\big)^{p/2}\,d\varphi\\
    &\gtrsim (k^{1/2}t_k^\frac{1}{2})^{p/2}.
\end{align*}
\end{proof}



\section{Sharpness in hgher dimensions}\label{sec 7}

Finally, we address the sharpness in higher dimensions. Suppose $d\ge3$ and $\dim\Sigma = k$. We work on the standard $d$-sphere. Let 
$$
\lambda^2 = l(l+d-1),\quad l\in\mathbb{N},
$$
and fix an orthonormal basis $\{Y_i\}_{i=1}^{\dim E_\lambda}$ of the eigenspace $E_\lambda$. Define
$$
Z_\lambda(p,x) =\sum_{i=1}^{\dim E_\lambda} Y_i(p)\,Y_i(x).
$$
By symmetry, $Z_\lambda(p,p)=C(\lambda)\sim\lambda^{d-1}$. For any $p\in\mathbb{S}^d$, the normalized zonal eigenfunction concentrated at $p$ is
$$
Z_\lambda^p(x)=\frac{Z_\lambda(p,x)}{\sqrt{Z_\lambda(p,p)}}.
$$

\begin{prop}
For each $p\in\mathbb S^d$,
$$
Z_\lambda^p(x) =
\begin{cases}
O\bigl(\lambda^{\frac{d-1}{2}}\bigr), & \mathrm{dist}(x,p)\le \lambda^{-1},\\
O\bigl(\mathrm{dist}(x,p)^{-\frac{d-1}{2}}\bigr), & \mathrm{dist}(x,p)\ge \lambda^{-1}.
\end{cases}
$$
\end{prop}

\begin{prop}
For any $p_1,p_2\in\mathbb S^d$,
$$
\bigl\langle Z_\lambda^{p_1},Z_\lambda^{p_2}\bigr\rangle
=\frac{Z_\lambda(p_1,p_2)}{C(\lambda)}.
$$
\end{prop}

The proofs of these propositions can be found in \cite[Lemma 1.2.5]{DF2013}.

Let $0<\beta<1$ be a parameter to be chosen later. Fix a sufficiently large constant $C>0$, and select a $C\lambda^{-1+\beta}$–separated set $\{p_j\}_{j\in J}\subset\Sigma$ so that for all $i\neq j$,
\[
C\,\lambda^{-1+\beta}\le\mathrm{dist}(p_i,p_j)\le\frac\pi2.
\]
In this configuration,
\[
|J|=O\bigl(C^{-1}\,\lambda^{\,k(1-\beta)}\bigr).
\]
Moreover, by the preceding propositions, for $i\neq j$ we have
\[
\bigl|\langle Z_\lambda^{p_i},\,Z_\lambda^{p_j}\rangle\bigr|
\lesssim\lambda^{-\frac{d-1}{2}\,\beta}.
\]
We will need the following lemma, which follows from Gerschgorin’s Circle Theorem. For completeness, we include a proof here.
\begin{lemma}\label{l17}
Let $H$ be a Hilbert space, and let $\{e_i\}_{i=1}^n\subset H$ be unit vectors satisfying
\[
|\langle e_i, e_j\rangle|<\frac{\delta}{n-1},\quad i\neq j,
\]
for some $0<\delta<\tfrac12$. Then there exists an $n\times n$ matrix $A=[A_{ij}]$ with
\[
|A_{ij}-\delta_{ij}|\le\delta\quad(1\le i,j\le n),
\]
such that the vectors
\[
f_i=\sum_{j=1}^nA_{ij}e_j,\quad i=1,\dots,n,
\]
form an orthonormal system in $H$.
\end{lemma}

\begin{proof}
Let $G = [\langle e_i,e_j\rangle]_{i,j=1}^n$ be the Gram matrix.  By hypothesis,
\[
G_{ii} = 1,\qquad |G_{ij}| < \frac{\delta}{n-1}\quad(i\neq j),
\]
with $0<\delta<\tfrac12$. 
Write $G=I+E$ with
\[
E_{ij} = \begin{cases}\langle e_i,e_j\rangle,&i\neq j,\\0,&i=j.\end{cases}
\]
Then for  each $i$, the row–sum norm of the off–diagonal part
satisfies
\[
\|E\|_\infty =\max_i\sum_{j\neq i}|E_{ij}|
< (n-1)\cdot\frac{\delta}{n-1} = \delta < 1.
\]
  By Gerschgorin’s theorem, each eigenvalue
$\lambda_i$ of $G=I+E$ lies in $\{\,z:|z-1|\le\delta\}$, so $G$ is positive‐definite
and invertible. Since the spectral norm $\|E\|_2\le\|E\|_\infty<1$, the Neumann series for
$(I+E)^{-1/2}$ converges in operator norm.
Hence we may set
\[
A =G^{-1/2} =(I+E)^{-1/2}.
\]

Define
\[
f_i =\sum_{j=1}^n A_{ij}\,e_j.
\]
Then the Gram matrix of $\{f_i\}$ is
\[
\langle f_i,f_j\rangle =(A\,G\,A^*)_{ij}
=[G^{-1/2}\,G\,G^{-1/2}]_{ij}
=\delta_{ij},
\]
so $\{f_i\}$ is orthonormal.

Finally, we have for all $i,j$
\[
\max_{i,j}|a_{ij}-\delta_{ij}| \le \max_{1\le i\le n}{|\sqrt{\lambda_i}-1|} < \delta.
\]

This completes the proof.
\end{proof}

Let us return to the example.  For simplicity, let $Z_j = Z_\lambda^{p_j}$.  Then there exists a matrix $A = [a_{ij}]$ such that
\[
f_i = \sum_{j\in J} a_{ij}\,Z_j,
\qquad
\bigl|a_{ij}-\delta_{ij}\bigr|\lesssim |J|\,\lambda^{-\frac{d-1}{2}\beta},
\]
and the family $\{f_j\}_{j\in J}$ is orthonormal.

Our goal is to choose $\beta$ so that $\lvert f_i(x)\rvert\approx \lambda^{\frac{d-1}{2}}$ whenever $x$ lies in the $\lambda^{-1}$-neighborhood of $p_i$.  To ensure this, note that for such $x$,
\[
\Bigl|\sum_{j\neq i}a_{ij}\,Z_j(x)\Bigr|
\le
|J|\lambda^{\frac{d-1}{2}(1-\beta)}\lambda^{-\frac{d-1}{2}\beta}|J|
\ll
\lambda^{\frac{d-1}{2}}.
\]
This holds provided
\[
|J|\lambda^{-\frac{d-1}{2}\beta}
=O\bigl(C^{-1}\,\lambda^{(1-\beta)k-\frac{d-1}{2}\beta}\bigr)
\ll1,
\]
which is achieved by taking
\begin{equation}\label{lower beta}
  \frac{2k}{2k + d - 1}\leq\beta<1,  
\end{equation}
and $C$ sufficiently large.
For the system $\{f_j\}$ constructed above, we then have
\[
|f_j(x)| \ge \lambda^{\frac{d-1}{2}}
\quad\text{on }B_{p_j}(\lambda^{-1}),
\]
and $\mathrm{dist}(p_i,p_j)\gg \lambda^{-1}$ for $i\neq j$.  Hence, for $p\ge2$ and $\dim\Sigma\le d-1$,
\[
\begin{aligned}
\Bigl\|\sum_{j\in J}t_j\,|f_j|^2\Bigr\|_{L^{p/2}(\Sigma)}
&\ge
\Bigl(\sum_{j\in J}\int_{B_{p_j}(\lambda^{-1})\cap\Sigma}
t_j^{\frac p2}\,|f_j|^p\Bigr)^{\frac2p}\\
&\ge
\Bigl(\sum_{j\in J}t_j^{\frac p2}\,\lambda^{\frac{(d-1)p}{2}}\,\lambda^{-k}\Bigr)^{\frac2p}\\
&\approx
\lambda^{\,d-1-\frac{2k}{p}}\,
\bigl\|t_j\bigr\|_{\ell^{\frac p2}(J)}.
\end{aligned}
\]
This demonstrates the sharpness of Theorem~\ref{codim2}, and Theorem~\ref{codim1} for the case  $4 \leq p \leq \infty$.

In the case $k = d-1$ and $d\ge3$, one can likewise employ highest‐weight spherical harmonics to construct an orthonormal family $\{f_j\}_{j\in J}$, with $|J|\sim \lambda^{(d-2)(1-\epsilon)}$ for any $0<\epsilon<1$, each concentrating along the geodesic through a chosen point. Consequently, for $p=2$ the exponent $\alpha=1$ is achieved, confirming its sharpness.
\begin{remark}
 Finally, we point out that producing a sharpness example for Theorem~\ref{codim2} requires a nontrivial upper bound on $|J|$—equivalently, a positive lower bound on $\beta$ (see, e.g., \eqref{lower beta}).
 By contrast, Theorem \ref{d2} is sharp for \textbf{all} values of $|J|$.  

  Indeed, take a codimension-2 submanifold $\Sigma\subset S^d$ and let $Q=E_\lambda$, so that
  \[
    |J|=\dim E_\lambda\sim\lambda^{d-1}.
  \]
  The sharp pointwise Weyl law on the sphere gives
  \[
    \sum_{\lambda_j\in I_\lambda}\bigl|e_{\lambda_j}(x)\bigr|^2
    \sim\lambda^{d-1},
    \quad x\in S^d,
  \]
  and hence
  \[
    \Bigl\|\sum_{\lambda_j\in I_\lambda}|e_{\lambda_j}|^2\Bigr\|_{L^{p/2}(\Sigma)}
    \sim\lambda^{d-1}.
  \]
  On the other hand, Theorem \ref{codim2} yields the upper bound
  \[
    \Bigl\|\sum_{\lambda_j\in I_\lambda}|e_{\lambda_j}|^2\Bigr\|_{L^{p/2}(\Sigma)}
    \lesssim
    \lambda^{{d-1}-\frac{2d-4}{p}+\frac{2(d-1)}{p}}
    =
    \lambda^{{d-1}+\frac{2}{p}}.
  \]
  It follows that
  the exponent in Theorem \ref{codim2} strictly exceeds the true exponent $d-1$, so the bound cannot be sharp in this case unless $p=\infty$.
\end{remark}




