	 \left (
		\frac{G^{(\text{th})} \left( S_0,T_i,K_j;\sigma_t^{(r)}, \mu , r_{\text{thr}}, r_{f,t} \right) - G^{(\text{emp})}(S_0,T_i,K_j) }
			{G^{(\text{emp})}(S_0,T_i,K_j)}
	\right )^2 .
\end{equation}
