Here, we will show that for physically relevant states such as the Hartle-Hawking state, it is safe to replace the full length operator, approximated here by
\begin{equation}
    x = \frac{1}{2}\left\lbrace \sqrt{2E} \rho(E), \vartheta\right\rbrace,
\end{equation}
with a ``microcanonical'' length operator $x_{\mc}$~\eqref{eqs:xmcdef} that is block diagonal with respect to some choice of microcanonical energy windows, and directly expressed in terms of the angle variable in each such window.

%\amit{This assumes that $E_1$ is the lowest energy level, check if this is consistent with notation elsewhere...Should be $E_0$ now}
Let $\proj_r$ project onto a Hilbert space $\mathcal{H}_r$ spanned by $d$ consecutive energy levels from $E_{r}$ to $E_{r+d-1}$, each such set of levels constituting a microcanonical window, such that $\sum_r \proj_r = 1$. The index $r = (m-1)d$ represents the ``base index'' of the $m$-th microcanonical window in the energy spectrum. In practice, we will be interested in a subset of these microcanonical windows spanning some interval $[E_{\min}, E_{\max}]$; let $R$ be the set of values of the base index $r$ corresponding to this interval.

While we are interested in the regime where $d$ is very large, we also assume that the density of states scales suitably so as to satisfy
\begin{equation}
    \sqrt{2E_{r+k}} \rho(E_{r+k})-\sqrt{2E_r} \rho(E_r) < \epsilon \sqrt{2E_r} \rho(E_r),\ \text{ for all } 0 < k < d,
\end{equation}
for some small constant $\epsilon$, as long as $E_r \geq E_{\min}$.
In other words, the energy-dependent prefactor $\sqrt{2E} \rho(E)$ in $x$, which increases monotonically with energy, doesn't increase significantly relative to its ``base value'' within each microcanonical window with a minimum energy of at least $E_{\min}$. It is correspondingly convenient to introduce the operator 
\begin{equation}
    \eta_r := \sum_{n=r}^{r+d-1} \eta_r(E_n) \lvert E_n\rangle\langle E_n\rvert = \sum_{n=r}^{r+d-1} \frac{\sqrt{2E_{n}} \rho(E_{n})-\sqrt{2E_r} \rho(E_r)}{\sqrt{2E_r} \rho(E_r)} \lvert E_n\rangle \langle E_n\rvert \label{eq:etardef}
\end{equation}
that measures the  relative variation of the prefactor within the window.
%\amit{Check if any cutoff is needed at low energies...cutoff introduced}

Now, we define the microcanonical length operator,
\begin{equation}
    x_{\mc} :=  \sum_{r\in R}\sqrt{2 E_r} \rho(E_r) \vartheta_r,
    \label{eqs:xmcdef}
\end{equation}
where $\vartheta_r$ represents the absolute value of the angle variable within each microcanonical window, whose eigenstates are the $\lvert C_k(0)\rangle$ in each microcanonical window with eigenvalues $\lvert \qtheta\rvert$ (where $\qtheta \in (-\pi, \pi]$), i.e.
%\amit{Can't decide immediately: Should we construct $\vartheta_r$ to have the $C_k$ as eigenstates (as done below), or should it be constructed instead in terms of an integral over the microcanonical coherent states? In either case, $\vartheta_r$ has a Fourier series like Eq.~\eqref{eq:operator_reconstruction_def}, with $a(\theta)$ either being smooth or a sum of delta functions, both even in $\theta$, so maybe the bump is insensitive to this decision?} \andy{fine to keep as is.}
\begin{equation}
    \vartheta_r \equiv \sum_{k=0}^{d-1} \min\left\lbrace \frac{2\pi k}{d}, \frac{2\pi (d-k)}{d} \right\rbrace \lvert C_{k,r}(0)\rangle \langle C_{k,r}(0)\rvert,
    \label{eqs:varthetadef}
\end{equation}
where
\begin{equation}
    \lvert C_{k,r}(0)\rangle \equiv \frac{1}{\sqrt{d}}\sum_{n=0}^{d-1}\mathrm{e}^{-2\pi \mathrm{i} n k/d}\lvert E_{r+n}\rangle.
\end{equation}

Let $\mathcal{H}_{\mc}(\nu_{\mc})$ be the set of states that are supported on $\nu_{\mc}$ consecutive microcanonical windows spanning $[E_{\min}, E_{\max}]$ and are unbiased in each window: 
\begin{equation}
    \lvert \psi\rangle = \sum_{r\in R} \sqrt{\frac{p_r}{d}} \sum_{n=0}^{d-1} \mathrm{e}^{\mathrm{i}\varphi_{r+n}} \lvert E_{r+n}\rangle,
    \label{eqs:microcanonical_unbiased}
\end{equation}
where $p_r \equiv \langle \psi\rvert \proj_r \lvert \psi\rangle$. Then, we will show that $x$ can be replaced by $x_{\mc}$ for the Hartle-Hawking state in 3 stages:
\begin{enumerate}
\item The microcanonical length operator $x_{\mc}$ and the operator
\begin{equation}
    x_{\text{block}} :=  \sum_{r\in R}\sqrt{2 E_r} \rho(E_r) \proj_r \vartheta \proj_r,
\end{equation}
which is the direct block diagonal restriction of $x$ to microcanonical windows, approach each other as $d\to\infty$ for any state in $\mathcal{H}_{\mc}(\nu_{\mc})$: 
\begin{equation}
    \max_{\lvert \psi\rangle \in \mathcal{H}_{\mc}(\nu_{\mathrm{mc}})} \lvert \langle \psi\rvert (x_{\mc}-x_{\text{block}})\lvert \psi \rangle\rvert \leq \sqrt{2 E_{\max}} \rho(E_{\max})  \frac{c_0 \log d}{d}.
    \label{eqs:xmcminusblockbound}
\end{equation}
Here, $c_0$ is an $O(1)$ constant as $d\to\infty$.
    \item $x$ and $x_{\text{block}}$ have almost the same expectation values for states in $\mathcal{H}_{\mc}(\nu_{\mc})$:
    \begin{equation}
        \max_{\lvert \psi\rangle \in \mathcal{H}_{\mc}(\nu_{\mathrm{mc}})} \lvert \langle \psi\rvert (x-x_{\text{block}})\lvert \psi\rangle \rvert \leq \sqrt{2 E_{\max}} \rho(E_{\max}) \left[c_2 \epsilon + \frac{\nu_{\mc} c(1+\epsilon)\log d}{d}\right],
        \label{eqs:xminusxblockbound}
    \end{equation}
    where $c$, $c_2$ are $O(1)$ constants as $d\to\infty$.
    \item The Hartle-Hawking state has a large overlap with a state in $\mathcal{H}_{\mc}(\nu_{\mathrm{mc}})$.
\end{enumerate}
Combining \eqref{eqs:xmcminusblockbound} and \eqref{eqs:xminusxblockbound} we obtain \begin{equation}
    \max_{\lvert \psi\rangle \in \mathcal{H}_{\mc}(\nu_{\mathrm{mc}})} |\langle \psi|\left(x-x_{\mathrm{mc}}\right)|\psi\rangle| \le \sqrt{2 E_{\max}} \rho(E_{\max}) \left[c_3 \epsilon + \frac{ c_4 \nu_{\mathrm{mc}}\log d}{d}\right],
\end{equation}
for appropriate constants $c_3$ and $c_4$.
%\amit{Maybe just $\nu_{\mathrm{\mc}}$ instead of $(1+\nu_{\mc})$ (because $c_0$ and $c$ are potentially different)?}

%\amit{Ideally should've been updated with new matrix elements by now.}
For the first statement, let us consider the matrix elements of $x_{\mc}$ and $x_{\text{block}}$ within a microcanonical Hilbert space $\mathcal{H}_r$. We have, for $n,m \in [r, r+d)$:
\begin{equation}
\langle E_n\rvert x_{\mc}\lvert E_m\rangle = \sqrt{2E_r} \rho(E_r) \langle E_n\rvert \vartheta_r\lvert E_m\rangle.
\end{equation}
From \eqref{eqs:varthetadef}, we have the matrix elements:
\begin{align}
\langle E_n\rvert \vartheta_r\lvert E_m\rangle &= \frac{1}{d}\sum_{k=0}^{d-1} \min\left\lbrace \frac{2\pi k}{d}, \frac{2\pi (d-k)}{d} \right\rbrace e^{-2\pi i (n-m) k/d} \nonumber \\
&= \begin{dcases}
    \frac{\pi}{2},\ &\text{ for } n=m,\\
    -\frac{\pi (1+(-1)^{m-n})}{d^2 \sin^2\left(\frac{m-n}{d}\pi\right)},\ &\text{ for } n \neq m.
\end{dcases}
\label{eqs:varthetamatrixelements}
\end{align}
For $x_{\text{block}}$, we recall that $\vartheta$ has the matrix elements [from \eqref{eq:Xmatrixelements}]:
\begin{equation}
\langle E_n\rvert \vartheta\lvert E_m\rangle = \begin{dcases}
\dfrac{\pi}{2},\ &\text{ for } n=m \\ \displaystyle -\frac{\left(1-(-1)^{m-n}\right)}{\pi(m-n)^2}, &\text{ for } n \neq m.
\end{dcases}
\label{eqs:Xmatrixelementsagain}
\end{equation}
Intuitively, we note that the difference between the matrix elements of $\vartheta_r$ and $\vartheta$ within $\mathcal{H}_r$ must generally be small, as the off-diagonal elements in \eqref{eqs:Xmatrixelementsagain} are comparable to \eqref{eqs:varthetamatrixelements} for large $d$ (when $\lvert m-n\rvert \ll d$), or both are negligibly small (when $d \sim \lvert m-n\rvert < d(1-\epsilon)$). The difference between the matrix elements is only significant for $\lvert m-n\rvert \approx d$, which occurs when $m \approx r+d$ and $n \approx r$ or vice-versa; however, these are a negligibly small fraction of matrix elements, and should hardly contribute  to expectation values in the unbiased states in $\mathcal{H}_{\mc}(\nu_{\mathrm{mc}})$. Formally, we have for $n\neq m$:
\begin{align}
    \left\lvert \langle E_n\rvert \vartheta_r\lvert E_m\rangle - \langle E_n\rvert \vartheta\lvert E_m\rangle \right\rvert =  \frac{\left(1-(-1)^{m-n}\right)}{\pi(m-n)^2}\left[\frac{1}{\sinc^2\left(\frac{m-n}{d}\pi\right)}-1\right],
\end{align}
while this difference vanishes for $n=m$. For an unbiased state $\lvert \psi\rangle \in \mathcal{H}_{\mc}(\nu_{\mc})$ \eqref{eqs:microcanonical_unbiased}, this gives (using the triangle inequality for the expression in terms of matrix elements, and that $1-(-1)^{m-n} \leq 2$):
\begin{align}
    \left\lvert \langle \psi\rvert (\vartheta_r - \proj_r\vartheta\proj_r)\lvert \psi\rangle\right\rvert &\leq \frac{2 p_r}{\pi d}\sum_{\substack{n,m = r \\ n \neq m}}^{r+d-1}\frac{1}{(m-n)^2}\left[\frac{1}{\sinc^2\left(\frac{m-n}{d}\pi\right)}-1\right] \nonumber \\
    &= \frac{4 p_r}{\pi d} \sum_{q=0}^{d-1} \frac{d-\lvert q\rvert}{q^2} \left[\frac{1}{\sinc^2(\pi q/d)}-1\right].
\end{align}
In the second line, we have set $q = m-n$, used the evenness of the sum in $q$, and noted that $\sinc^2(0) = 1$ by definition to allow $q=0$. Introducing the variable $\xi = q/d$, we can write the sum in the above expression as:
\begin{equation}
    \sum_{q=0}^{d-1} \frac{1}{d}\frac{1-\lvert q/d\rvert}{(q/d)^2} \left[\frac{1}{\sinc^2(\pi q/d)}-1\right]\approx
\int_{0}^{1-(1/d)} \diff \xi\ \frac{1-\lvert \xi\rvert}{\xi^2}\left[\frac{1}{\sinc^2(\pi \xi)}-1\right].
\end{equation}
%which means that for sufficiently large $d$, the sum is bounded by some multiple of the integral. 
This integral diverges as $\log d$ near $\xi \sim 1$, so we conclude that for some O(1) constant $c_0$,
\begin{equation}
    \sum_{q=0}^{d-1} \frac{1}{d}\frac{1-\lvert q/d\rvert}{(q/d)^2} \left[\frac{1}{\sinc^2(\pi q/d)}-1\right] < \frac{\pi c_0}{4} \log d,
\end{equation}
which gives
\begin{equation}
    \left\lvert \langle \psi\rvert (\vartheta_r - \proj_r\vartheta\proj_r)\lvert \psi\rangle\right\rvert \leq \frac{p_r c_0 \log d}{d}.
    \label{eqs:varthetar_difference_1block}
\end{equation}
For the difference between the operators themselves, the triangle inequality gives:
\begin{equation}
    \lvert \langle \psi\rvert (x_{\mc}-x_{\text{block}})\lvert \psi \rangle\rvert \leq \sum_r \sqrt{2 E_r} \rho(E_r)\left\lvert \langle \psi\rvert (\vartheta_r - \proj_r\vartheta\proj_r)\lvert \psi\rangle\right\rvert.
\end{equation}
Using \eqref{eqs:varthetar_difference_1block} with $\sqrt{2E_r}\rho(E_r) \leq \sqrt{2 E_{\max}} \rho(E_{\max})$ and $\sum_r p_r = 1$, we get \eqref{eqs:xmcminusblockbound}.

To show the second statement and \eqref{eqs:xminusxblockbound}, we note that $x$ can be massaged into the following form [recall $\eta_r$ was defined in \eqref{eq:etardef}]:
%(where $\eta_{E_r} \equiv \eta_r \lvert E_r\rangle \langle E_r\rvert$):
\begin{align}
    x &= \frac{1}{2}\sum_r \left[\sqrt{2E} \rho(E) \proj_r \vartheta + \vartheta \sqrt{2E} \rho(E) \proj_r \right] \nonumber \\
    &= \frac{1}{2}\sum_r \sqrt{2E_r}\rho(E_r) \left[ (1+\eta_r)\proj_r \vartheta + \vartheta \proj_r (1+\eta_r)\right] \nonumber \\
    &= \frac{1}{2}\sum_{r,r'} \sqrt{2E_r} \rho(E_r) \left[ (1+\eta_r)\proj_r \vartheta\proj_{r'} + \proj_{r'}\vartheta \proj_r (1+\eta_r)\right] \nonumber \\
    &= x_{\text{block}} + \frac{1}{2}\sum_r \sqrt{2E_r} \rho(E_r) \lbrace \eta_r, \proj_r \vartheta \proj_r\rbrace \nonumber \\ &+ \frac{1}{2}\sum_{r} \sum_{r' \neq r} \sqrt{2E_r} \rho(E_r) \left[ (1+\eta_r)\proj_r \vartheta\proj_{r'} + \proj_{r'} \vartheta \proj_r (1+\eta_r)\right].
\end{align}
For a given state $\lvert \psi\rangle$, the triangle inequality then gives
\begin{align}
    \lvert \langle \psi\rvert (x-x_{\text{block}})\lvert \psi\rangle\rvert \leq  &\left\lbrace\left\lvert \sum_r \sqrt{2E_r} \rho(E_r) \langle \psi\rvert \eta_r \proj_r \vartheta \proj_r\lvert \psi\rangle \right\rvert \right. \nonumber \\
    &+\left. \left\lvert \sum_r \sum_{r' \neq r} \sqrt{2E_r} \rho(E_r) \langle \psi\rvert (1+\eta_r) \proj_r \vartheta \proj_{r'}\lvert \psi\rangle \right\rvert \right\rbrace. 
    \label{eqs:xmctwoterms}
\end{align}
The first term measures the error in replacing the energy dependent prefactor with the base value $\sqrt{2E_r} \rho(E_r)$ in each microcanonical block, while the second term largely measures interference between the different blocks.

We note that both of these contributions consist of terms of the form:
\begin{equation}
    M_{r,r'} = \langle \psi\rvert (\zeta+\eta_r)\proj_r \vartheta \proj_{r'}\lvert \psi\rangle,
\end{equation}
where $\zeta \in \lbrace 0,1\rbrace$; in addition, $\zeta = 0$ when $r=r'$. When $\lvert \psi\rangle$ is given by an unbiased state as in \eqref{eqs:microcanonical_unbiased}, this becomes
\begin{equation}
    M_{r,r'} = \frac{\sqrt{p_r p_{r'}}}{d}\sum_{n=r}^{r+d-1} \sum_{m=r'}^{r'+d-1} (\zeta+\eta_r(E_n)) \mathrm{e}^{\mathrm{i}(\varphi_m-\varphi_n)} \langle E_n\rvert \vartheta\lvert E_m\rangle.
\end{equation}

When $r\neq r'$ in $M_{r,r'}$, i.e. for the interference contributions to \eqref{eqs:xmctwoterms}, only the off-diagonal matrix elements of $X$ \eqref{eqs:Xmatrixelementsagain} are relevant. In this case, we get
\begin{equation}
    M_{r\neq r'} = -\frac{\sqrt{p_r p_{r'}}}{d}\sum_{n=r}^{r+d-1} \sum_{m=r'}^{r'+d-1} (\zeta+\eta_r(E_n)) \mathrm{e}^{\mathrm{i}(\varphi_m-\varphi_n)} \frac{(1-(-1)^{m-n})}{\pi(m-n)^2}.
\end{equation}
Using the triangle inequality to replace each term with its magnitude, together with $\eta_r(E_n) < \epsilon$, $(m+n) \geq (m-n)$ and $2 \geq 1-(-1)^{m-n}$, we get the bound:
\begin{equation}
    \lvert M_{r\neq r'}\rvert \leq \frac{2(\zeta+\epsilon)\sqrt{p_r p_{r'}}}{d^3}\sum_{n=r}^{r+d-1} \sum_{m=r'}^{r'+d-1} \frac{1}{\pi(\frac{m-n}{d})^2}.
\end{equation}
On the right hand side, we have a double sum of positive terms over $d$ values of each of $m$ and $n$, which approaches a double integral as $d\to\infty$. For sufficiently large $d$, it follows that we can bound the sum by a multiple $c_m > 1$ of this integral (where $x$ corresponds to $n/d$ and $y$ to $m/d$):
\begin{align}
    \frac{1}{d^2}\sum_{n=r}^{r+d-1} \sum_{m=r'}^{r'+d-1} \frac{1}{(\frac{m-n}{d})^2} &\leq c_m \int_{r/d}^{(r-1)/d+1}\diff x \int_{r'/d}^{(r'-1)/d+1}\diff y\ \frac{1}{(x-y)^2}.\nonumber \\
    &= c_m \log\frac{(r-r')^2}{(r-r'+d-1)(r-r'-d+1)}.
\end{align}
When $\lvert r-r'\rvert =d$, the second line gives a constant times $\log d$; for $\lvert r-r'\rvert > d$, the second line is at most a constant. In either case, the sum is less than $(\pi c/2) \log d$ for some constant $c$. On the whole, we obtain the bound:
\begin{equation}
    \lvert M_{r\neq r'}\rvert \leq \frac{(\zeta+\epsilon)c \sqrt{p_r p_{r'}} \log d}{d}.
\end{equation}


For $r = r'$, we have
\begin{equation}
    M_{rr} = \frac{p_r}{d}\sum_{n = r}^{r+d-1}(\zeta+\eta_r(E_n))\left\lbrace\frac{\pi}{2} - \sum_{\substack{m = r,\\ m\neq n}}^{r+d-1}\mathrm{e}^{\mathrm{i}(\varphi_m - \varphi_n)}\frac{(1-(-1)^{m-n})}{\pi(m-n)^2}\right\rbrace.
\end{equation}
The inner sum over $m$ converges as each term is $\sim 1/m^2$ (i.e. the magnitude of each term is bounded by the terms of a convergent series), and its magnitude cannot exceed some constant $c_s > 0$ (say) for any value of $n$. The outer sum over $n$ then adds up $d$ finite terms, contributing an $\mathrm{O}(d)$ factor that cancels out the $1/d$ prefactor. On the whole, again using the triangle inequality, $\eta_r(E_n) < \epsilon$, as well as $\zeta=0$ when $r=r'$ in \eqref{eqs:xmctwoterms}, we get the inequality
\begin{equation}
    \lvert M_{rr}\rvert \leq p_r \epsilon c_2,
\end{equation}
for some constant $c_2$.

Substituting these bounds on $M_{r,r'}$ in \eqref{eqs:xmctwoterms}, and noting that they hold for any unbiased state of the form in \eqref{eqs:microcanonical_unbiased}, we get
\begin{equation}
\max_{\lvert \psi\rangle \in \mathcal{H}_{\mc}(\nu_{\mathrm{mc}})} \lvert \langle \psi\rvert (x-x_{\text{block}})\lvert \psi\rangle \rvert  \leq \sum_r \sqrt{2E_r} \rho(E_r)\left[p_r \epsilon c_2 +\sum_{r' \neq r} \frac{(1+\epsilon)c\sqrt{p_r p_{r'}} \log d}{d}\right]
\label{eqs:xminusxblockbound_part}
\end{equation}
As these states are supported on $\nu_{\mc}$ microcanonical windows with $\sum_r p_r = 1$, we also have $\sum_r \sqrt{p_r} \leq \sqrt{\nu_{\mc}}$; using these inequalities in \eqref{eqs:xminusxblockbound_part}, together with $\sqrt{2 E_r}\rho(E_r) < \sqrt{2 E_{\max}}\rho(E_{\max})$, we get \eqref{eqs:xminusxblockbound}.

%\amit{Check for subtleties: can $\epsilon$ be comfortably smaller than $1/(\sqrt{2 E_{\max}} \rho(E_{\max}))$? If not, just note that the relative error is small anyway. The main issue is apparently the $E_{r+n} \approx E_r$ part rather than interference...} \andy{it seems to me like the idea for highly excited states would be to take $\epsilon \sim e^{-S\cdot a}$ (crudely speaking) so that the $\epsilon$-dependent error coming from neglecting the variation of the overall coefficient is very small, as this is the dominant source of error.  that seems totally fine to me.} \amit{An (apparently) different perspective: I think the point is more like $\epsilon \sim 1$, and this approximation is only accurate over $x \sim \sqrt{2 E_{\max}} \rho(E_{\max})$ values and makes errors that are little-$o$ of this scale. This corresponds to $\theta \sim 1$, but this error is fine because our reconstruction of $\theta$ is anyway accurate only over $\theta \sim 1$ scales. But it also remains this accurate at all times, without time evolution magnifying the error (related to the point after \eqref{eq:reconstruction_error_tolerance}).} \andy{I don't really understand this point.   I think it would make sense to choose an $\epsilon$ such that $\epsilon$ and $\nu_{\mathrm{mc}}\epsilon$ both scale as $\mathrm{e}^{-O(S)}$, then we would have extreme accuracy at all times anyway.}

Finally, to show that the Hartle-Hawking state~\eqref{eq:HHstate} 
can be approximated by a microcanonical state in $\mathcal{H}_{\mc}(\nu_{\mathrm{mc}})$, we define its (normalized) microcanonical approximation as (recalling that the $r$-th microcanonical window has $d$ levels):
\begin{equation}
    \lvert \beta_{\mc}\rangle := \frac{1}{\sqrt{Z_{\mc}(\beta)}} \sum_{r \in R} d \mathrm{e}^{-\beta E_r/2}.
\end{equation}
Normalization $\langle \beta_{\mc}\vert \beta_{\mc}\rangle = 1$ then gives
\begin{equation}
    Z_{\mc}(\beta) = \sum_{r \in R} d \mathrm{e}^{-\beta E_r}.
    \label{eqs:partitionfunctionmc}
\end{equation}
The overlap between these two states is given by:
\begin{align}
    \lvert \langle \beta_{\mc}\vert \beta\rangle\rvert &= \frac{1}{\sqrt{Z(\beta)Z_{\mc}(\beta)}} \sum_{r\in R} \sum_{k=0}^{d-1} \mathrm{e}^{-\beta (E_r + E_{r+k})/2} \nonumber \\
    &= \sqrt{\frac{Z(\beta)}{Z_{\mc}(\beta)}} \frac{1}{Z(\beta)} \sum_{r\in R} \sum_{k=0}^{d-1} \mathrm{e}^{-\beta E_{r+k}} \mathrm{e}^{\beta(E_{r+k}-E_r)/2}
     \geq \sqrt{\frac{Z(\beta)}{Z_{\mc}(\beta)}}.
\end{align}
The last inequality follows from noting that $E_{r+k} \geq E_r$.

Now focusing on $Z_{\mc}(\beta)$, we can rewrite \eqref{eqs:partitionfunctionmc} as:
\begin{equation}
    Z_{\mc}(\beta) = Z(\beta) + \sum_{r\in R} \sum_{k=0}^{d-1} \mathrm{e}^{-\beta E_{r+k}} (\mathrm{e}^{\beta(E_{r+k}-E_r)}-1).
\end{equation}
We expect that the microcanonical windows are such that
\begin{equation}
    e^{\beta(E_{r+d-1}-E_r)}-1 < \epsilon_{\beta},
\end{equation}
for some small $\epsilon_\beta > 0$ (note that the density of states is monotonically increasing with energy, so if this can be established for the $d$ lowest levels in $[E_{\min}, E_{\max}]$, we should expect it to be the case for [almost] all energy levels throughout the spectrum, especially given spectral rigidity, as successive sets of $d$ levels span increasingly narrower energy ranges). We get
\begin{equation}
    Z_{\mc}(\beta) \leq Z(\beta) (1+\epsilon_\beta),
\end{equation}
which implies
\begin{equation}
  \lvert \langle \beta_{mc}\vert \beta\rangle\rvert \geq \frac{1}{\sqrt{1+\epsilon_\beta}}.  
\end{equation}
As we discuss in Sec.~\ref{sec:HHstate}, most of the probability of the Hartle-Hawking state can be found in a finite ($\beta$-dependent) energy range, which we choose to be $[E_{\min}, E_{\max}]$, we can truncate the support of $\lvert \beta_{\mc}\rangle$ to this range and normalize this truncated version so that it formally belongs to $\mathcal{H}_{\mc}(\nu_{\mathrm{mc}})$. But it is also the case that to accurately capture expectation values such as $\langle x^q\rangle$, the choice of microcanonical windows that must be accounted for is rather different: see Appendix \ref{app:HH}.

\section{Dynamics of the Hartle-Hawking state}
\label{app:HH}
This appendix contains explicit calculations for the dynamics of the Hartle-Hawking state.
\subsection{Probability distribution of wormhole lengths}
Here we present the derivation of \eqref{eq:longtailed_x_dist} and \eqref{eq:HHEq}, starting with the former.  Recall that the length operator is approximated well by its truncation to microcanonical windows in \eqref{eq:xwindow}.  In each window, $\langle\vartheta\rangle\approx \pi/2$ at late times.  Let \begin{equation}
    x_{\mathrm{sat}}(E) = \sqrt{2E}\rho(E)\cdot \frac{\pi}{2} \label{eq:xsatE}
\end{equation}
denote the average value of $x$ at late times, in a microcanonical window centered around $E$.  Since we know the distribution of energy $E$ in the Hartle-Hawking state is given by \eqref{eq:HHdistribution}, we wish to invert this relation to find a distribution of $x_{\mathrm{sat}}$.
Introducing the function $W_s(z)$ via the following property (for $y\geq 0$):\footnote{$W_s(z)$ reduces to the Lambert product logarithm function $W_0(z)$ for large argument ($y e^{y} = z \iff y = W_0(z)$ for $y\geq 0$).}
\begin{equation}
2 y \sinh(y) = z \iff y = W_s(z),
\end{equation}
we get the expression
\begin{equation}
2\pi \sqrt{2 E(x_{\text{sat}})} = W_s\left(\mathrm{e}^{-\widetilde{S}_0} x_{\text{sat}}\right), \label{eq:WsE}
\end{equation}
where \begin{equation}
    \mathrm{e}^{-\widetilde{S}_0} = 32\pi^2 \mathrm{e}^{-S_0}
\end{equation}
is introduced for future convenience.  We also note the approximation \begin{equation}
    W_s(z)\approx \log z\;\;\;\; (z\gg 1)
\end{equation}
which will prove useful later.  Combining \eqref{eq:HHdistribution} with \eqref{eq:WsE}, we obtain the following distribution of saturation values:  %\amit{There was a missing factor in the denominator (the stuff within the square root --- the original expression was for $W_0(z)$ rather than $W_s(z)$) that potentially makes this a bit more tedious, wondering if it's better just to have the approx $\exp(-\beta (\log x)^2)$ form here instead of the exact expression. Rewrote a bit...maybe it's compact enough now.}
\begin{align}
\mathcal{P}_{\text{sat}}(x_{\text{sat}}) &= \frac{\diff E}{\diff x_{\text{sat}}} \mathcal{P}(E(x_{\text{sat}})) \nonumber \\
&= 8 \pi \frac{W_s\left(\mathrm{e}^{-\widetilde{S}_0} x_{\text{sat}}\right) \exp\left[-\frac{\beta}{8 \pi^2}W_s^2\left(\mathrm{e}^{-\widetilde{S}_0} x_{\text{sat}}\right)\right]}{Z(\beta) \left[1+W_s\left(\mathrm{e}^{-\widetilde{S}_0} x_{\text{sat}}\right)\sqrt{1+\left\lbrace\frac{2 W_s\left(\mathrm{e}^{-\widetilde{S}_0} x_{\text{sat}}\right)}{\mathrm{e}^{-\widetilde{S}_0} x_{\text{sat}}}\right\rbrace^2}\right]} \notag \\
&\approx \frac{8 \pi}{Z(\beta)} \exp\left[-\frac{\beta}{8\pi^2}\left\lbrace\log\left(\mathrm{e}^{-\widetilde{S}_0} x_{\text{sat}}\right)\right\rbrace^2\right],    
\end{align}
for large $x_{\text{sat}} \gg \mathrm{e}^{S_0}$. The distribution of $x$ itself at extremely long times (after almost all of the distribution saturates) can be modeled by a uniform probability $1/(2 x_{\text{sat}})$ in $x \in [0, 2 x_{\text{sat}}]$ for each microcanonical window with respective saturation length $x_{\text{sat}}$. This gives the following late-time probability distribution of $x\gg \mathrm{e}^{S_0}$:
\begin{align}
\mathcal{P}_x(x; t\to\infty) &= \int_{x/2}^{\infty}\diff x_{\text{sat}}\ \frac{\mathcal{P}_{\text{sat}}(x_{\text{sat}})}{2x_{\text{sat}}} \nonumber \\
&\approx \frac{8 \pi }{Z(\beta)}\int_{\ln(x/2)}^{\infty}\diff (\ln x_{\text{sat}})\ \exp\left[-\frac{\beta}{8\pi^2}\left\lbrace \ln\left(\mathrm{e}^{-\widetilde{S}_0} x_{\text{sat}}\right)\right\rbrace^2\right] \nonumber \\
&= \frac{8\pi^2}{Z(\beta)} \sqrt{\frac{2\pi}{\beta}}\erfc\left[\sqrt{\frac{\beta}{8\pi^2}}\ln\left(2\mathrm{e}^{-\widetilde{S}_0} x\right)\right] 
\end{align}
which leads to \eqref{eq:longtailed_x_dist} in the main text at large $x$.   

We now calculate the moments $\langle x^q\rangle$ with respect to this late time distribution, which we see is approximately Gaussian in $\log x$.  Observe that (dropping algebraic factors in $\log x$) we find \begin{align}
    \left\langle \mathrm{e}^{q\log x}\right\rangle &\propto \int\limits_{-\infty}^\infty \left(x \mathrm{d}\log x\right)\mathrm{e}^{q\log x - \beta (\log (2\mathrm{e}^{-\widetilde{S}_0}x))^2/8\pi^2}\notag \\
    &\sim\int\limits_{-\infty}^\infty  \mathrm{d}\log x\mathrm{e}^{- \beta (\log (2\mathrm{e}^{-\widetilde{S}_0}x)-(q+1)4\pi^2 T)^2/8\pi^2} \mathrm{e}^{(q+1)^22\pi^2T-(q+1)\log(2\mathrm{e}^{-\widetilde{S}_0})} \notag \\
    &\sim \mathrm{e}^{(q+1)^22\pi^2T-(q+1)\log(2\mathrm{e}^{-\widetilde{S}_0})}.
\end{align}
From the middle line above, together with \eqref{eq:xsatE} and \eqref{eq:JTinftyDOS}, we can deduce the typical energy of the microcanonical windows which dominate $\langle x^q\rangle$ to be given by \eqref{eq:HHEq}.  Notice that even the average wormhole length, $q=1$, is dominated by completely \emph{atypical} parts of the Hartle-Hawking state, with $E_{q=1}-E_{q=0} \sim T^2 \gg \sigma_E$.  More generally, each higher moment is dominated by a completely different (and even more atypical) part of the Hartle-Hawking state.


