%\end{eqnarray}
Here, $m_t, m_b$ are the measured masses of the top and bottom quarks at $T=0$ and so on.



Within this regularization framework, the choice of the renormalization scale $\mu$ introduces an inherent uncertainty in the determination of the critical temperature and other related quantities~\cite{Chiang:2018gsn,Athron:2022jyi,Croon:2020cgk,Gould:2021oba}. To mitigate these uncertainties, several approaches have been employed for computing the Coleman-Weinberg (CW) potential, notably the on-shell (OS) and on-shell-like (OS-like) schemes. Among these, the OS-like scheme is extensively adopted in the literature, as it prescribes fixed renormalization scales for each particle species and maintains the tree-level parameter relations even at higher-loop levels, closely mirroring the behavior of the OS scheme. In this formalism, for instance, the CW potential takes the form:
%
%
 %Here, $q$ and $\ell$ represent the quarks and charged leptons. In this regularization scheme, the choice of $\mu$ leads to uncertainty in critical temperature and other related quantities~\cite{Chiang:2018gsn,Athron:2022jyi,Croon:2020cgk,Gould:2021oba}. However, different approaches can be employed to compute the CW potential and address the associated uncertainty, including the on-shell (OS) and on-shell-like (OS-like) schemes. In the literature, the OS-like scheme is widely used, as it provides a fixed prescription for the renormalization scales of each particle and preserves the tree-level parameter relations even at higher-loop orders, similar to the OS scheme. For example, in this framework, the CW potential takes the form: 
\begin{equation} \label{}
V_{\rm 1-loop}^{\rm CW} (h,\phi_1,..\phi_n)
= \frac{1}{64\pi^2} \sum_{i} n_i \left\{  m_i^4(h,\phi_i) \left[ \log\left( \frac{m_i^2(h,\phi_i)}{m_i^2(v,0 )}\right)  - \frac{3}{2} \right] 
+ 2 m_i^2(h,\phi_i)m_i^2(v,0)  \right\},
\end{equation}
%
where $m_i^2(v,0)$ is the mass-squared of the species $i$ at zero temperature.  However, both OS schemes exhibit an infrared divergence arising from the Goldstone bosons, which become massless at zero temperature. Although this subtle issue can be addressed using the approaches outlined in Refs.~\cite{Martin:2014bca,Elias-Miro:2014pca}, our study primarily employs the $\overline{MS}$ scheme throughout. Next, we compute the thermal corrected potential.

 The one-loop potential at $T\neq 0$ is given as~\cite{Dolan:1973qd,Weinberg:1974hy}:
\begin{equation} \label{eq:finiteT}
\begin{split}
V^T_{\rm 1-loop} (h, \phi_1,..\phi_n, T)
&= \frac{T^4}{2\pi^2} \left[ \sum_{B} n_B J_B \left(\frac{m_B^2(h,\phi_i)} {T^2}\right) + \sum_{F} n_F J_F \left(\frac{m_F^2(h,\phi_i)} {T^2}\right)  \right],
\end{split}
\end{equation}
Here, B stands for all bosonic degrees of freedom that couple directly to the Higgs boson; therefore, B = $\{W, Z, \phi_1,.. \phi_n, \chi_{1,2,3}\}$ and F stands for three charged leptons and six quarks as mentioned earlier. $J_B$ and $J_F$ are the thermal bosonic and fermionic functions, which are as follows.
\begin{eqnarray}
J_{B/F} \left(\frac{m^2(h,\phi_i)} {T^2}\right)& = & \int_0^\infty dx x^2 \log\left( 1 \mp e^{-\sqrt{x^2+\frac{m^2(h,\phi_i)} {T^2}}}\right) 
%J_{F} \left(\frac{m_F^2(h,\phi_i)} {T^2}\right)& = & \int_0^\infty dx x^2 \log\left( 1 + e^{-\sqrt{x^2+\frac{m_F^2(h,\phi_i)} {T^2}}}\right)
\end{eqnarray}
For $T^2\gg m^2$, thermal bosonic and fermionic functions take an expansion as~\cite{Quiros:1999jp}
\begin{eqnarray} \label{eq:expn1}
&& J_B \left[\frac{m_B^2}{T^2} \right] = -\frac{\pi^4}{45} + \frac{\pi^2}{12T^2} m_B^2 - \frac{\pi}{6T^3} (m_B^2)^{3/2} - \frac{1}{32T^4}m_B^4 \ln \frac{m_B^2}{a_b T^2} + \cdots,   \\ \label{eq:expn2}
&&J_F \left[\frac{m_F^2}{T^2} \right] =  \frac{7\pi^4 }{360} - \frac{\pi^2}{24T^2} m_F^2 - \frac{1}{32T^4}m_F^4 \ln \frac{m_F^2}{a_f T^2} + \cdots, 
\end{eqnarray}
%{\color{red}where $a_f = \pi^2\exp \left(3/2-2\gamma_E\right)$ and $a_b = 16 \pi^2\exp \left(3/2-2\gamma_E\right)$ with Euler-Mascheroni  constant, $\gamma_E = 0.577$. Numerical analysis indicates that the high-temperature expansion, including the logarithmic term, maintains an accuracy better than $5\%$ for $y \left(=\sqrt{m^2/T^2}\right)\leq1.6$ in the case of fermions and $y\leq 2.2$ for bosons~\cite{Laine:2016hma,Anderson:1991zb}. Furthermore, this approximation—both for the potential and its derivatives—agrees with the exact expressions to within approximately $10\%$ for $y\leq 1–3$, depending on the specific function considered~\cite{Curtin:2016urg}.}
The high-temperature expansion with logarithmic terms, where $a_f = \pi^2 e^{3/2 - 2\gamma_E}$, $a_b = 16\pi^2 e^{3/2 - 2\gamma_E}$, and $\gamma_E = 0.577$, is accurate within $5\%$ for $y = \sqrt{m^2/T^2} \leq 1.6$ (fermions) and $y \leq 2.2$ (bosons)~\cite{Laine:2016hma,Anderson:1991zb}, and agrees with exact results to within $10\%$ for $y \leq 1\!-\!3$~\cite{Curtin:2016urg}.

\paragraph{}
Here, we also need to consider the contribution of the ring diagram to take care of infrared divergences at finite temperatures. This contribution can be given by:
\begin{equation}\label{eq:ring}
V_{\rm ring}(h ,\phi_1,..\phi_n, T)=-\frac{T}{12\pi}n_i\Big[\big(m_i^2(h, \phi_1,..\phi_n, T)\big)^{3/2}-\big(m_i^2(h, \phi_1,..\phi_n)\big)^{3/2}\Big],
\end{equation}
where $m_i^2(h, \phi_1,..\phi_n, T)$ are thermal masses called Debye masses which can be given as~\cite{Weinberg:1974hy} 
\begin{equation}\label{eq:massT}
m_i^2(h, \phi_1,..\phi_n) \rightarrow m_i^2(h, \phi_1,..\phi_n, T) = m_i^2(h, \phi_1,..\phi_n)+  \Pi_iT^2 ,
\end{equation}
where the temperature-dependent self-energy contribution $\Pi_i$ corresponding to the one-loop resumed diagrams to leading powers of the temperature from bosons and fermions is discussed in the next subsection.
\subsection*{Thermal self-energy corrections}
From the high temperature expansion of the thermal functions, the self-energy correction to the thermal masses of the CP-even scalar can be written as
\begin{align}\label{eq:daisy}
&\Pi_{h h} = \frac{3g^2}{16}  + \frac{g^{\prime 2}}{16}  + \frac{y_q^2}{4} + \frac{y_\ell^2}{12} + \frac{\lambda_H}{2} + \sum_i \frac{\lambda_{H\phi_i}}{24}
,  \\
%
&\Pi_{\phi_i\phi_i} = \frac{\lambda_{\phi_i}}{4} + \frac{\lambda_{H\phi_i}}{6}+ \sum_j \frac{\lambda_{ij}}{24}  , \\
%
&\Pi_{h \phi_i} = \frac{\lambda_{H\phi_i}}{12},\quad \Pi_{\phi_i \phi_j} = \frac{\lambda_{ij}}{12}.\label{eq:daisy1}
\end{align}
%%%
The thermal re-summation masses of the CP-odd Goldstone bosons $\chi_i$ are
\begin{eqnarray}
    \Pi_{\chi_i} = \frac{3g^2}{16}  + \frac{g^{\prime2}}{16}  + \frac{y_q^2}{4} +\frac{y_\ell^2}{12} + \frac{\lambda_H}{2} + \sum_i \frac{\lambda_{H\phi_i}}{24}.
\end{eqnarray}
Therefore, unlike $T=0$, the Higgs boson and singlet scalars mix at higher temperatures because of their non-zero $vev$s. The temperature-dependent $(n+1)\times (n+1)$ symmetric mass-square matrix for the CP-even scalars, in terms of classical background fields, is given as
\begin{equation}\label{mat:massT}
  M^2(h,\phi_1,..\phi_n,T)  =
  \begin{pmatrix}
      m_{hh}^2 & m_{h\phi_1}^2 &...m_{h\phi_n}^2\\ 
      m_{h\phi_1}^2 & m_{\phi_1\phi_1}^2 &...m_{\phi_1\phi_n}^2\\ 
    .......&........&.........\\
      m_{h\phi_n}^2 & m_{\phi_1\phi_n}^2 &...m_{\phi_n\phi_n}^2\\ 
  \end{pmatrix}+
  T^2\begin{pmatrix}
      \Pi_{hh} & \Pi_{h\phi_1} &...\Pi_{h\phi_n}\\ 
      \Pi_{h\phi_1} & \Pi_{\phi_1\phi_1} &...\Pi_{\phi_1\phi_n}\\ 
      .....&...&...\\
      \Pi_{h\phi_n} & \Pi_{\phi_1\phi_n} &...\Pi_{\phi_n\phi_n}\\ 
  \end{pmatrix},
\end{equation}
where the field-dependent mass-square matrix elements are given in Eqs.~\eqref{eq:masses}-\eqref{eq:masses1} and the daisy contributions are given in Eqs.~\eqref{eq:daisy}-\eqref{eq:daisy1}.
