\title{Subpixel correction of diffraction pattern shifts in ptychography via automatic differentiation}

\author{Zhengkang Xu,\authormark{1,2,$\dag$} Yanqi Chen,\authormark{2,$\dag$} Hao Xu,\authormark{1} Qingxin Wang,\authormark{2} Jin Niu,\authormark{1,2}  Lei Huang,\authormark{1,2} Jiyue Tang,\authormark{1,2} Yongjun Ma,\authormark{1} Yutong Wang,\authormark{1} Yishi Shi,\authormark{1,2,3} Changjun Ke,\authormark{1,2} Jie Li,\authormark{1,2,4} and Zhongwei Fan\authormark{2,*}}

