\section{Monodromy matrix}\label{app a}

\begin{algorithm}[H]
    \caption{Floquet multipliers from monodromy matrix $\mathbf{\phi}$} \label{algo 2}
    \begin{algorithmic}[!]
    \State 1. Initialize: $\mathbf{x}(0)$ ensuring $H(\mathbf{x}) \geq 0$ and $\omega$ or $\alpha$ \Comment{Bifurcation parameter}
    \State 2. Initialize: $\mathbf{\Phi} = \textit{I}_{n \times n}$, T$ = 100$, count $= 0$, $n_{max}$ \Comment{Maximum allowable impacts}
    \While{count $\leq$ $n_{max}$}
    \State Integrate: $\dot{\mathbf{x}} = \mathbf{F}(\mathbf{x})$
    \If{$H(\mathbf{x}) = 0$} \Comment{Occurrence of impact}
        \State Reset Map: $\mathbf{x} \gets \mathbf{R}(\mathbf{x})$
    \EndIf
    \If{$\dot{x} = 0$ $\&\&$ count $\geq n_{max}/2$}
        \State $T = \{t \in \mathbb{R}^1:x(t + \tilde{n}T) = x(t), \tilde{n}\in \mathbb{I} \}$ \Comment{Store $x$, $t$ for evaluation of time period $T$}
    \EndIf
    \If{count $=$ $n_{max}$ - 100} \Comment{Remove transients}
        \State Store: $\mathbf{x}_{init}$ $\gets \mathbf{x}(t)$ and $t_{init} \gets t$ 
    \EndIf
    \EndWhile
    \State Initialize: $\mathbf{x} \gets \mathbf{x}_{init}$ at $t_{init}$ \Comment{Begin at steady state} 
    \State Initialize: $r_0 \ll 1$, $\mathbf{Y}_1(0) = r_0 \textit{I}_{n \times n}$, $\mathbf{Y}_2(0) = \textit{I}_{n \times n}$ \Comment{Evaluation of $\mathbf{S}_2$ and $\mathbf{\Phi}_i$}
    \While{$t_{init} \leq t \leq (t_{init} + T)$} \Comment{Integrate over period $T$}
        \State Integrate: $\dot{\mathbf{x}} = \mathbf{F}(\mathbf{x})$, $\dot{\mathbf{Y}_1} = (\nabla \mathbf{F})^T\cdot\mathbf{Y}_1$ and $\dot{\mathbf{Y}_2} = (\nabla \mathbf{F})^T\cdot\mathbf{Y}_2$ 
        \If{$H(\mathbf{x}) = 0$} \Comment{Occurrence of impact}
        \State $\mathbf{\Phi}_i \gets \mathbf{Y}_2$ and $\mathbf{\Phi} \gets \mathbf{\Phi}_i\cdot\mathbf{\Phi}$
        \State Evaluate $\delta$ and $\mathbf{y}_+$ from $\mathbf{x}_4$ for all $\mathbf{y}_i$ \Comment{TDM}
        \State Evaluate $\mathbf{Y}_{+, impact}$ from $\mathbf{y}_+$ and $\mathbf{Y}_{-\text{, impact}} \gets \mathbf{Y}_1$
        \State Evaluate $\mathbf{S}_2 \gets \mathbf{Y}_{+, impact}\cdot\mathbf{Y}_{-, impact}^{-1}$ and set $\mathbf{\Phi} \gets \mathbf{S}_2 \cdot \mathbf{\Phi}$ \Comment{saltation matrix}
        \State Reset Map: $\mathbf{x} \gets \mathbf{R}(\mathbf{x})$
        \State Reinitialize: $\mathbf{Y}_1 \gets r_0 \textit{I}_{n \times n}$ and $\mathbf{Y}_2 \gets \textit{I}_{n \times n}$
        \EndIf
    \EndWhile
    \State 3. $\mathbf{\Phi} \gets \mathbf{Y}_2\cdot\mathbf{\Phi}$ \Comment{Evaluate monodromy matrix}
    \State 4. Evaluate eigenvalues of $\mathbf{\Phi}$ to get Floquet multipliers
   \end{algorithmic}
\end{algorithm}

\section{Lyapunov exponents}\label{app b}

\begin{algorithm}[H]
    \caption{Lyapunov exponent for hybrid systems using TDM} \label{algo 1}
    \begin{algorithmic}
    \State 1. Initialize: $\mathbf{x}(0)$ ensuring $H(\mathbf{x} \geq 0)$ and $\omega$ or $\alpha$ \Comment{Bifurcation parameter} 
    \State 2. Initialize: $\mathbf{y}_i(0)$ for $i \leq n$ using QRD 
    \State 3. Rescale: $\mathbf{y}_i(0) \gets r_0\times \mathbf{y}_i(0)$ and set $n_{max}$ \Comment{Maximum allowable impacts}
    \While{count $\leq n_{max}$}
    \State Integrate: $\dot{\mathbf{x}} = \mathbf{F}(\mathbf{x})$
    \If{$H(\mathbf{x}) = 0$} \Comment{Occurrence of impact}
        \State Evaluate: $\delta$, $\mathbf{R}(\mathbf{x})$ and $\mathbf{y}_+$
        \State Apply reset maps: $\mathbf{x} \gets \mathbf{R}(\mathbf{x})$ and $\mathbf{y}_i \gets \mathbf{y}_{i,+}$ \Comment{Implement TDM} 
    \EndIf
    \If{$\big( t \% \dfrac{2\pi}{\omega} \big) = 0$}
        \If{count $\geq n_{max}/2$}
            \State Store: $r_i \gets \dfrac{1}{r_0} \| \mathbf{y}_i \|$ \Comment{store the growth rate}
        \EndIf
    \State Reinitialize: $\mathbf{y}_i \gets r_0 \times \text{QRD of } \mathbf{y}_i$ 
    \EndIf
    \EndWhile
    \State 4: Evaluate: $\log_e r_i$ \Comment{Store all $log_e r_i$}
    \State 5: LE$_i \gets \dfrac{\omega}{2\pi} \times \text{Partial sum of } \log_e r_i$
    \State 6: $\lambda_i \gets \langle \text{LE}_i \rangle$ \Comment{Mean of all LEs}
    \end{algorithmic}
\end{algorithm}

