  \includegraphics[width=0.4\linewidth]{figures/lagrangepoly_nr=4_mr=8_6} \\
  \textrm{(a)} & \textrm{(b)}
  \end{array}$
  \end{center}
  \vspace{-4mm}
  \caption{(a) $\phi_i(r)$, $i=1 \dots 4$, Lagrange interpolants. (b) Cubic 1D function $u(r)$ with nodal coefficients $u_i=\{-2.4,0.8,1.4,-1\}$ in \eqref{eq_1D_function}.}
\label{fig_1D_function}
\end{figure}

We simplify the bound computation problem for \eqref{eq_1D_function} by  determining piecewise linear bounds $\uv_i (r)$ and $\ov_i (r)$ of the bases such that $\phi_i(r) \in [\uv_i (r),\ov_i (r)]$.
These bounding functions are represented using their values at Chebyshev interval points $\uv_i(\eta_j)$ and $\ov_i(\eta_j)$, where
\begin{equation}
  \label{eq_chebyshev}
  \eta_j = -\cos\bigg(\frac{j-1}{M-1}\pi\bigg), \qquad j=1\dots M.
\end{equation}
% Assuming that the bounding functions $\uv_i$ and $\ov_i$ are represented using their values at interval points $\eta_j \in [-1, 1]$, $j=1 \dots M$, the compactness of the bounds naturally depends on how the bounding functions are computed and the number of points ($M$) used to represent them.
% % For example, we could sample each basis function at a high number (e.g., $M \approx 100$) of equally spaced points and set the bounding values $\uv_i(\eta_j)$ and $\ov_i(\eta_j)$ at an offset below and above the sampled value, respectively. This technique would produce tight bounds for the bases, but requires a high number of interval points, and is thus sub-optimal.
% We use Chebyshev points as the interval points due to their superiority in interpolating high-order functions with a bounded error,
% \begin{equation}
%   \label{eq_chebyshev}
%   \eta_j = -\cos\bigg(\frac{j-1}{M-1}\pi\bigg), \qquad j=1\dots M.
% \end{equation}
Then, using subscripts $()_{ij}$ to represent quantities associated with the $i$th basis function and the $j$th interval point, superscript $()^{'}$ to represent the derivative of the basis function, and $j^+$ and $j^-$ to represent the midpoint between the $j$th interval point and the interval point to its right- and left-hand side, respectively, the bounding functions are:
\begin{eqnarray}
  \label{eq_1D_bases_bounds}
  \underline{v}_{ij}=\min V_{ij},\,\,\bar{v}_{ij}=\max V_{ij},\qquad i = 1 \dots N, j = 1 \dots M \\
  \label{eq_1D_bases_bounds_2}
  V_{ij} =
  \begin{cases}
  {\delta_{ij}} & \text{if j=1 or j=M} \\
  \bigg\{\phi_{ij},\,\,
  \phi_{ij^-} + (\eta_j - \eta_{j-1})\cdot\phi_{ij^-}^{'}, \,\,\,
  \phi_{ij^+} - (\eta_{j+1} - \eta_{j})\cdot \phi_{ij^+}^{'} \bigg\}  & \text{otherwise},
\end{cases} \\
  \label{eq_1D_bases_bounds_3}
\eta_{j^{+}} = \frac{\eta_j + \eta_{j+1}}{2},\,\,\,\eta_{j^{-}}= \frac{\eta_j + \eta_{j-1}}{2}\end{eqnarray}
The idea in \eqref{eq_1D_bases_bounds}-\eqref{eq_1D_bases_bounds_3} is to bound the basis function in each interval between the line segment connecting the function evaluated at interval end points and the line segment that is tangent to the curve at the interval midpoint. Bounding each interval independently would result in piecewise discontinuous bounds so the more conservative of the incident bounds at each interval point is chosen to obtain piecewise continuous linear bounds.
This approach is guaranteed to work for a function that is strictly convex/concave in each interval.
For sufficiently large $M > N$, the Lagrange interpolants are \emph{predominantly} convex/concave in each interval with at-most one change in sign of their first derivatives, and we have empirically verified that the proposed approach works with $M=2N$ points for at-least $N \leq 30$ ($p \leq 29$)\footnote{The minimum number of points needed to bound the bases using \eqref{eq_1D_bases_bounds}-\eqref{eq_1D_bases_bounds_3} for $N=2 \dots 12$ represented as $(N,M_{\min})$ pairs are: (2,2), (3,4), (4,7), (5,9), (6,11), (7,12), (8,14), (9, 16), (10, 18), (11, 20), and (12, 21).}.
Figure \ref{fig_1D_basis_bound} shows the Lagrange interpolants $\phi_i(r)$ at $N=4$ GLL points along with the piecewise linear bounds constructed with $M=8$ Chebyshev interval points.
% In future work, we will develop techniques to construct theoretically provable bounds for general high-order bases.

