  \begin{center}
  $\begin{array}{c}
  \includegraphics[width=0.8\linewidth]{figures/OBBTransformation}
  \end{array}$
  \end{center}
  \vspace{-4mm}
  \caption{Jacobian of the transformations used to compute the oriented bounding box around an element. The original element $\Omega$ is shown in top-right, the modified element $\check{\Omega}$ with its center at the origin is in top-center, the reference element $\bar{\Omega}$ is in top-left, and the element $\tilde{\Omega}$ transformed to align with the Cartesian axes is at the bottom. The AABB around $\tilde{\Omega}$, the OBB around the original element $\Omega$, and relevant transformations are shown in red.}
