%%%
\subsubsection{Validation of Eq.~\eqref{eq:ZDiagramaticExpansion}}\label{sec:On->0model-ii}
%%%
To show how by these ingredients one can construct the correct partition function~\eqref{eq:ZDiagramaticExpansion} of the system, consider the example conformations in Fig.~\ref{fig:IllustrativeConfigurations}.

%%%
\noindent
Fig.~\ref{fig:IllustrativeConfigurations}(a) --
%%%
This conformation is represented by the term:
%
\begin{equation}\label{eq:TreeExample1-a}
\kappa_b^3 \,
\langle
S_1({\mathbf x}_0)
(\bar{\mathbf S}({\mathbf x}_0) \cdot {\mathbf S}({\mathbf x}_3))
(\bar{\mathbf S}({\mathbf x}_3) \cdot {\mathbf S}({\mathbf x}_4))
(\bar{\mathbf S}({\mathbf x}_3) \cdot {\mathbf S}({\mathbf x}_6))
\rangle \, ,
\end{equation}
%
which is equivalent to
%
\begin{equation}\label{eq:TreeExample1-b}
\kappa_b^3 \,
\sum_{j_1} \sum_{j_2} \sum_{j_3}
\langle
S_1({\mathbf x}_0) \,
\bar{S}_{j_1}({\mathbf x}_0) S_{j_1}({\mathbf x}_3) \, 
\bar{S}_{j_2}({\mathbf x}_3) S_{j_2}({\mathbf x}_4) \, 
\bar{S}_{j_3}({\mathbf x}_3) S_{j_3}({\mathbf x}_6)
\rangle \, .
\end{equation}
%
By exploiting trace property (I) (spin vectors on different sites are independent), Eq.~\eqref{eq:TreeExample1-b} becomes:
%
\begin{equation}\label{eq:TreeExample1-c}
\kappa_b^3 \,
\sum_{j_1} \sum_{j_2} \sum_{j_3} \,
\langle S_1({\mathbf x}_0) \bar{S}_{j_1}({\mathbf x}_0) \rangle \,
\langle S_{j_1}({\mathbf x}_3) \bar{S}_{j_2}({\mathbf x}_3) \bar{S}_{j_3}({\mathbf x}_3) \rangle \,
\langle S_{j_2}({\mathbf x}_4) \rangle \,
\langle S_{j_3}({\mathbf x}_6) \rangle \, ,
\end{equation}
%
which, by the rest of the properties (II)-(VI), simplifies to
%
\begin{equation}\label{eq:TreeExample1-d}
\kappa_b^3 \, \kappa_3 \,
\sum_{j_1}\sum_{j_2}\sum_{j_3} \,
\delta_{1,j_1} \, \delta_{j_1,j_2,j_3} = \kappa_b^3 \, \kappa_3 \, .
\end{equation}
%

%%%
\noindent
Fig.~\ref{fig:IllustrativeConfigurations}(b) --
%%%
By the same procedure as before, one gets
%
\begin{equation}\label{eq:TreeExample1-e}
\kappa_b^5
\sum_{\substack{j_1, j_2, j_3 \\ j_4, j_5}}
\langle S_1({\mathbf x}_0) \bar{S}_{j_1}(\bold{x}_0) \bar{S}_{j_2}({\mathbf x}_0)\rangle \,
\langle S_{j_2}({\mathbf x}_3) \bar{S}_{j_3}({\mathbf x}_3) \bar{S}_{j_4}({\mathbf x}_3) \bar{S}_{j_5}({\mathbf x}_3) \rangle \,
\langle S_{j_1}({\mathbf x}_1) \rangle \,
\langle S_{j_3}({\mathbf x}_4) \rangle \,
\langle S_{j_4}({\mathbf x}_5) \rangle \,
\langle S_{j_5}({\mathbf x}_6) \rangle \, ,
\end{equation}
%
which leads to:
%
\begin{equation}\label{eq:TreeExample1-f}
\kappa_b^5 \, \kappa_4
\sum_{\substack{j_1, j_2, j_3 \\ j_4, j_5}}
\delta_{1,j_1,j_2} \, \delta_{j_2,j_3,j_4,j_5}
= \kappa_b^5 \, \kappa_4 \, .
\end{equation}
%

%%%
\noindent
Fig.~\ref{fig:IllustrativeConfigurations}(c) --
%%%
Here we show how the trace properties rule out any {\it disconnected} conformation from the partition function.
In fact, the one in the figure corresponds to the term:
%
\begin{equation}\label{eq:TreeExample1-g}
\kappa_b^4 \,
\langle
S_1({\mathbf x}_0) \,
(\bar{{\mathbf S}}({\mathbf x}_0) \cdot {\mathbf S}({\mathbf x}_3)) \,
(\bar{\mathbf S}({\mathbf x}_3) \cdot {\mathbf S}({\mathbf x}_4)) \,
(\bar{\mathbf S}({\mathbf x}_3) \cdot {\mathbf S}({\mathbf x}_6)) \,
(\bar{\mathbf S}({\mathbf x}_5) \cdot {\mathbf S}({\mathbf x}_8))
\rangle \, .
\end{equation}
%
It is easy to see that, after factorization, the expression~\eqref{eq:TreeExample1-g} contains a factor $\sim \langle \bar{S}_j({\mathbf x}_5) \rangle$ which, by the trace property (V), is $=0$ and so the weight of the entire conformation.

%%%
\noindent
Fig.~\ref{fig:IllustrativeConfigurations}(d) --
%%%
Similarly, the trace properties rule out any conformation that contains a {\it loop}.
For the conformation in the figure, we have the term:
%
\begin{equation}\label{eq:TreeExample1-h}
\kappa_b^5 \,
\langle
S_1({\mathbf x}_0) \,
(\bar{\mathbf S}({\mathbf x}_0) \cdot {\mathbf S}({\mathbf x}_3)) \,
(\bar{\mathbf S}({\mathbf x}_3) \cdot {\mathbf S}({\mathbf x}_4)) \,
(\bar{\mathbf S}({\mathbf x}_3) \cdot {\mathbf S}({\mathbf x}_6)) \,
(\bar{\mathbf S}({\mathbf x}_6) \cdot {\mathbf S}({\mathbf x}_7)) \,
(\bar{\mathbf S}({\mathbf x}_4) \cdot {\mathbf S}({\mathbf x}_7))
\rangle \, .
\end{equation}
%
Again, after factorization, it is straightforward to see that Eq.~\eqref{eq:TreeExample1-h} contains a factor $\sim \langle S_{j_1}({\mathbf x}_7) S_{j_2}({\mathbf x}_7) \rangle$ that is $=0$ because of the trace property (IV).

%%%
\noindent
Fig.~\ref{fig:IllustrativeConfigurations}(e) --
%%%
The latest possible situation, and probably the trickiest, is the one shown in the last panel.
It corresponds to the term:
%
\begin{equation}\label{eq:TreeExample1-i}
\kappa_b^4 \,
\langle S_1({\mathbf x}_0) \,
(\bar{\mathbf S}({\mathbf x}_4) \cdot {\mathbf S}({\mathbf x}_7)) \,
(\bar{\mathbf S}({\mathbf x}_7) \cdot {\mathbf S}({\mathbf x}_8)) \,
(\bar{\mathbf S}({\mathbf x}_8) \cdot {\mathbf S}({\mathbf x}_5)) \,
(\bar{\mathbf S}({\mathbf x}_5) \cdot {\mathbf S}({\mathbf x}_4))
\rangle \, ,
\end{equation}
%
and, as it can be easily verified, is $\neq 0$ even though it corresponds to a prohibited conformation.
In fact, Eq.~\eqref{eq:TreeExample1-i} is just equal to:
%
\begin{equation}\label{eq:TreeExample1-l}
\kappa_b^4 \,
\sum_{\substack{j_1,j_2 \\ j_3, j_4}} \,
\langle S_1({\mathbf x}_0) \rangle \,
\langle \bar{S}_{j_1}({\mathbf x}_4) S_{j_4}({\mathbf x}_4) \rangle \,
\langle \bar{S}_{j_4}({\mathbf x}_5) S_{j_3}({\mathbf  x}_5) \rangle \,
\langle \bar{S}_{j_2}(\bold{x}_7)S_{j_1}({\mathbf x}_7) \rangle \,
\langle \bar{S}_{j_3}({\mathbf x}_8) S_{j_2}({\mathbf x}_8) \rangle \, ,
\end{equation}
%
which, based on the trace properties, simplifies to:
%
\begin{equation}
\kappa_b^4 \,
\sum_{\substack{j_1,j_2 \\ j_3,j_4}} 
\delta_{j_1,j_2} \delta_{j_2,j_3} \delta_{j_3,j_4} \delta_{j_4,j_1} = \kappa_b^4 \, n \, .
\end{equation}
%
The weight of the conformation is thus proportional to $n$ yet, owing to the limit $n \to 0$ (see Eq.~\eqref{eq:ZDiagramaticExpansion}), these conformations are also removed from the partition function.

To summarize, we have shown that Eq.~\eqref{eq:ZDiagramaticExpansion} effectively counts {\it only} rooted directed SAT conformations and, importantly, with the expected statistical weight given by the fugacities $\kappa_b$ and $\{ \kappa_f \}$.
We can now proceed with the derivation of the field-theoretic form of Eq.~\eqref{eq:ZDiagramaticExpansion}.

%%%
\subsubsection{Field-theoretic form of Eq.~\eqref{eq:ZDiagramaticExpansion}}\label{sec:On->0model-iii}
%%%
According to the trace properties (I)-(VI) and taking into account the discussion of Sec.~\ref{sec:On->0model-ii}, Eq.~\eqref{eq:ZDiagramaticExpansion} can be written as the following:
%
\begin{equation}\label{eq:ZDiagramaticExpansion-exp}
\Xi %{\mathcal Z}
= \lim_{n \to 0}
\bigg\langle
S_1({\mathbf x}_0)
\prod_{{\mathbf x}, {\mathbf x}'}
\exp\bigg[ \kappa_b \bar{\mathbf S}({\mathbf x}) \cdot {\mathbf S}({\mathbf x}') \, \Delta({\mathbf x}, {\mathbf x}') \bigg] \bigg\rangle =
\lim_{n \to 0} \bigg\langle S_1({\mathbf x}_0) \exp\bigg[ \kappa_b \sum_{{\mathbf x}, {\mathbf x}'} \bar{\mathbf S}({\mathbf x}) \cdot {\mathbf S}({\mathbf x}') \, \Delta({\mathbf x}, {\mathbf x}') \bigg] \bigg\rangle \, ,
\end{equation}
%
where the first equality is justified by the fact that in the expansion of the exponential all terms beyond first order have weight $=0$ (see Sec.~\ref{sec:On->0model-ii} for an explanation of this point). %At this point we want to rewrite the previous expression in a field-theoretic form.
In order to obtain the field-theoretic form of Eq.~\eqref{eq:ZDiagramaticExpansion-exp}, we apply a generalization of the standard Hubbard-Stratonovich formula~\cite{ZinnJustin2021} to it and get:
%
\begin{multline}\label{eq:ZDiagramaticExpansion-Factor}
\exp\bigg[ \kappa_b \sum_{{\mathbf x}, {\mathbf x}'} \bar{\mathbf S}({\mathbf x}) \cdot {\mathbf S}({\mathbf x}') \, \Delta({\mathbf x}, {\mathbf x}') \bigg] =
\prod_{\alpha=1}^n \exp\bigg[ \kappa_b \sum_{{\mathbf x}, {\mathbf x}'} \bar{S}_\alpha({\mathbf x}) S_\alpha({\mathbf x}') \, \Delta({\mathbf x}, {\mathbf x}') \bigg] = \\
\prod_{\alpha=1}^n (\det \Delta^{-1}) \int\prod_{\mathbf x} \frac{d\varphi_\alpha({\mathbf x}) \, d\bar{\varphi}_{\alpha}({\mathbf x})}{2\pi i} \, \exp\bigg[ -\sum_{{\mathbf x}, {\mathbf x}'} \bar{\varphi}_{\alpha}({\mathbf x}) \, \Delta^{-1}({\mathbf x}, {\mathbf x}') \, \varphi_\alpha({\mathbf x}') + \sqrt{\kappa_b} \, \sum_{{\mathbf x}} \bigg( \bar{S}_\alpha({\mathbf x}) \varphi_\alpha({\mathbf x}) + S_{\alpha}({\mathbf x}) \bar{\varphi}_\alpha({\mathbf x}) \bigg) \bigg] = \\
(\det \Delta^{-1})^n \int \prod_{\mathbf x} \frac{d\boldsymbol{\varphi}({\mathbf x}) \, d\bar{\boldsymbol{\varphi}}({\mathbf x})}{(2\pi i)^n} \exp\bigg[ -\sum_{{\mathbf x}, {\mathbf x}'} \bar{\boldsymbol{\varphi}}({\mathbf x}) \cdot \boldsymbol{\varphi}({\mathbf x}') \, \Delta^{-1}({\mathbf x}, {\mathbf x}') + \sqrt{\kappa_b} \, \sum_{\mathbf x} \bigg( \bar{\mathbf S}({\mathbf x}) \cdot \boldsymbol{\varphi}({\mathbf x}) + {\mathbf S}(\bold{x}) \cdot \bar{\boldsymbol{\varphi}}({\mathbf x}) \bigg) \bigg] \, ,
\end{multline}
%
where $\boldsymbol{\varphi}({\mathbf x})$ and $\bar{\boldsymbol{\varphi}}({\mathbf x})$ are $n$-component vector fields relative to the lattice site ${\mathbf x}$.
By plugging Eq.~\eqref{eq:ZDiagramaticExpansion-Factor} back into the expression for $\Xi$ %$\mathcal Z$
we get
%
\begin{eqnarray}
\Xi %{\mathcal Z}
= \lim_{n \to 0} \int \prod_{\mathbf x} d\boldsymbol{\varphi}({\mathbf x}) \, d\bar{\boldsymbol{\varphi}}({\mathbf x}) \exp\bigg[ -\sum_{{\mathbf x}, {\mathbf x}'} \bar{\boldsymbol{\varphi}}({\mathbf x}) \cdot \boldsymbol{\varphi}({\mathbf x}') \, \Delta^{-1}({\mathbf x}, {\mathbf x}') \bigg] \bigg\langle S_1({\mathbf x}_0) \exp\bigg[ \sqrt{\kappa_b} \, \sum_{\mathbf x} \bigg( \bar{\mathbf S}({\mathbf x}) \cdot \boldsymbol{\varphi}({\mathbf x}) + {\mathbf S}({\mathbf x}) \cdot \bar{\boldsymbol{\varphi}}({\mathbf x}) \bigg) \bigg] \bigg\rangle \, , \nonumber\\
\end{eqnarray}
%
where we have already taken the limit for $(\det\Delta^{-1})^n \to 1$ and $(2\pi i)^n \to 1$.
At this point, the term inside the $\langle \rangle$ can be factorized, making the calculation of the trace much easier.
By expanding again the exponential and using the trace properties (I)-(VI), one finally gets the expression:
%
\begin{eqnarray}\label{eq:FieldTheoreticZ}
\Xi %\mathcal{Z}
& = &
\lim_{n \to 0} \int\prod_{\mathbf x} d\boldsymbol{\varphi}(\bold{x}) \, d\bar{\boldsymbol{\varphi}}({\mathbf x}) \exp\bigg[ -\sum_{{\mathbf x}, {\mathbf x}'} \, \Delta^{-1}({\mathbf x}, {\mathbf x}') \, \bar{\boldsymbol{\varphi}}({\mathbf x}) \cdot \boldsymbol{\varphi}({\mathbf x}') \nonumber\\
& & + \log\bigg( 1+ \sqrt{\kappa_b} \, \varphi_1({\mathbf x}_0) + \frac{\kappa_b}2 \, \varphi_1({\mathbf x}_0)^2 + \sum_{f=3}^q \kappa^{f/2}_b \, \kappa_f \, \frac{\varphi_1^f({\mathbf x}_0)}{f!} \bigg) \nonumber\\
& & + \sum_{{\mathbf x} \neq {\mathbf x}_0} \log \bigg( 1 + \sqrt{\kappa_b} \, \sum_{\alpha=1}^n \bar{\varphi}_{\alpha}({\mathbf x}) + \kappa_b \sum_{\alpha=1}^n \bar{\varphi}_{\alpha}({\mathbf x}) \, \varphi_{\alpha}({\mathbf x}) + \sum_{\alpha=1}^n \bar{\varphi}_{\alpha}({\mathbf x}) \sum_{f=3}^q \kappa^{f/2}_b \, \kappa_f \, \frac{\varphi_{\alpha}^{f-1}({\mathbf x})}{(f-1)!} \bigg) \bigg] \, .
\end{eqnarray}
%
Notice that Eq.~\eqref{eq:FieldTheoreticZ} is formally {\it exact}.

%%%
\subsection{Saddle-point approximation}\label{sec:SaddlePointApprox}
%%%
Although exact, the integral in Eq.~\eqref{eq:FieldTheoreticZ} cannot be computed directly.
We are therefore looking for a uniform saddle-point (or, mean-field-like~\cite{Orland1985,Orland1996,Higuchi1998,Marcato2023,Marcato2024}) approximation.
First, we search for the stationary points of the integrand and then look for solutions of the saddle-point equations of the kind $\boldsymbol{\varphi}({\mathbf x}) = (\varphi, 0, \dots, 0)$ and $\bar{\boldsymbol{\varphi}}({\mathbf x}) = (\bar{\varphi}, 0, \dots, 0)$, $\forall \bold{x}$. 
This particular choice is justified by the explicit presence of the term $S_1$ that breaks the $n$-vector symmetry.
The approximate expression for the partition function then becomes:
%
\begin{equation}\label{eq:ApproximateZ}
\Xi %{\mathcal Z}
\simeq \exp\bigg[ -V \frac{\varphi\bar{\varphi}}{q} + \log\bigg( 1 + \sqrt{\kappa_b} \, \varphi + \frac{\kappa_b}2 \varphi^2 + \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \, \frac{\varphi^f}{f!} \bigg) \, + \, (V-1) \log\bigg( 1 + \sqrt{\kappa_b} \bar{\varphi} + \kappa_b \bar{\varphi}\varphi + \bar{\varphi} \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!} \bigg)\bigg] \, ,
\end{equation}
%
where $\varphi$ and $\bar{\varphi}$ are the solutions of the following saddle-point equations:
%
\begin{eqnarray}
\frac{\bar{\varphi}}{q}
& = & \frac1V \frac{\sqrt{\kappa_b} + \kappa_b\varphi + \sum_{f=3}^{q}\kappa^{f/2}_b\kappa_f \frac{\varphi^{f-1}}{(f-1)!}}{1 + \sqrt{\kappa_b}\varphi + \kappa_b\varphi^2 + \sum_{f=3}^{q}\kappa^{f/2}_b\kappa_f \frac{\varphi^f}{f!}} + \frac{V-1}{V} \frac{\kappa_b\bar{\varphi} + \bar{\varphi} \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-2}}{(f-2)!}}{1 + \sqrt{\kappa_b}\bar{\varphi} + \kappa_b \bar{\varphi}\varphi + \bar{\varphi} \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}} \, , \label{eq:SaddlePointEq-1}\\
%
\frac{\varphi}{q}
& = & \frac{V-1}V \frac{\sqrt{\kappa_b} + \kappa_b \varphi + \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}}{1 + \sqrt{\kappa_b} \bar{\varphi} + \kappa_b \bar{\varphi}\varphi + \bar{\varphi}\sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}} \, .
\end{eqnarray}
%
Note that with this approximation, every dependence upon ${\mathbf x}_0$ disappears.
In order to simplify the calculations and proceed analytically, we now take the thermodynamic limit $V \gg 1$ and neglect terms ${\mathcal O}(1/V)$.
This leads to
%
\begin{eqnarray}
\Xi %{\mathcal Z}
& \simeq &
\exp\bigg[ -V \frac{\varphi\bar{\varphi}}q + V\log\bigg( 1 + \sqrt{\kappa_b}\bar{\varphi} + \kappa_b\bar{\varphi}\varphi + \bar{\varphi}\sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!} \bigg) \bigg] \, , \label{eq:MFPartitionFunction}\\
%
\frac{\bar{\varphi}}q
& = &
\frac{\kappa_b \bar{\varphi} + \bar{\varphi} \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-2}}{(f-2)!}}{1 + \sqrt{\kappa_b} \bar{\varphi} + \kappa_b \bar{\varphi}\varphi + \bar{\varphi}\sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}} \, , \label{eq:SP1}\\
%
\frac{\varphi}q
& = &
\frac{\sqrt{\kappa_b} + \kappa_b\varphi + \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}}{1 + \sqrt{\kappa_b}\bar{\varphi} + \kappa_b\bar{\varphi}\varphi + \bar{\varphi}\sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}} \, . \label{eq:SP2}
\end{eqnarray}
%
At this point, one can solve (eventually through numerical methods) Eqs.~\eqref{eq:SP1} and~\eqref{eq:SP2} and plug the solutions for $\varphi$ and $\bar{\varphi}$ back into Eq.~\eqref{eq:MFPartitionFunction} to have the mean field estimate of $\Xi$. %$\mathcal Z$.
The saddle-point equations can also be recast in an equivalent form that will be useful in the next Section.
By multiplying both sides of Eq.~\eqref{eq:SP2} by $\bar{\varphi}$ it is easy to see that
%
\begin{equation}\label{eq:RHS1}
1 - \frac{\varphi\bar{\varphi}}q = \frac1{1 + \sqrt{\kappa_b} \bar{\varphi} + \kappa_b \bar{\varphi}\varphi + \bar{\varphi} \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}} \, .
\end{equation}
%
We can now do the same with Eq.~\eqref{eq:SP1} by multiplying both sides by $\varphi$ and get:
%
\begin{equation}\label{eq:RHS2}
1-\frac{\varphi\bar{\varphi}}q = \frac{1 + \sqrt{\kappa_b} \,  \bar{\varphi} - \bar{\varphi} \sum_{f=3}^q \kappa^{f/2}_b\kappa_f\frac{(f-2)\varphi^{f-1}}{(f-1)!}}{1 + \sqrt{\kappa_b} \bar{\varphi} + \kappa_b \bar{\varphi}\varphi + \bar{\varphi}\sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}} \, .
\end{equation}
%
Then, by equating the right-hand sides of Eqs.~\eqref{eq:RHS1} and~\eqref{eq:RHS2} we get the following relation:
%
\begin{equation}\label{eq:UsefulIdentity}
\sqrt{\kappa_b} = \sum_{f = 3}^q \kappa_b^{f/2} \kappa_f \frac{(f-2)}{(f-1)!} \varphi^{f-1} \, .
\end{equation}
%

%%%
\subsection{Legendre transform}\label{sec:LegendreTransform}
%%%
Now that we have an estimate of $\Xi$, %$\mathcal Z$,
we need to switch back to the ``more convenient'' ensemble where the total node density $\rho$ and the branch-node fractions $\phi_f = N_f/N$ (with $f \geq 3$) are fixed. 
To this purpose, we employ the Legendre-transform technique, which requires to find a way to express the fugacities in terms of $\rho$ and $\{ \phi_f \}$.
First, since only a single tree is present, we have that $N = N_b + 1$.
Therefore, since we neglect terms ${\mathcal O}(1/V)$, the total node density can be approximated by the total {\it bond} density.
Thus, we can write:
%
\begin{equation}\label{eq:ApproximateRho-1}
\rho \simeq \frac{\kappa_b}{V} \frac{\partial \log(\Xi)}{\partial \kappa_b} %\frac{\partial \log({\mathcal Z})}{\partial \kappa_b}
= \frac{\sqrt{\kappa_b} \frac{\bar{\varphi}}2 + \kappa_b \varphi\bar{\varphi} + \frac{\bar{\varphi}}2 \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{f}{(f-1)!} \varphi^{f-1}}{1 + \sqrt{\kappa_b} \bar{\varphi} + \kappa_b \bar{\varphi}\varphi + \bar{\varphi} \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}} \, .
\end{equation}
%
Using Eq.~\eqref{eq:UsefulIdentity}, it is easy to see that:
%
\begin{equation}\label{eq:ApproximateRho-2}
1-\rho = \frac{1}{1 + \sqrt{\kappa_b}\bar{\varphi} + \kappa_b\bar{\varphi}\varphi + \bar{\varphi}\sum_{f=3}^q \kappa^{f/2}_b\kappa_f \frac{\varphi^{f-1}}{(f-1)!}} \, ,
\end{equation}
%
and thus, because of Eq.~\eqref{eq:RHS1}, we have that:
%
\begin{equation}\label{eq:ApproximateRho-3}
\rho = \frac{\varphi\bar{\varphi}}q \, .
\end{equation}
%
The $f$-functional branch-node density is instead given by
%
\begin{equation}\label{eq:ApproximatePhiF}
\frac{N_f}V = \frac{\kappa_f}V \frac{\partial \log (\Xi)}{\partial \kappa_f} %\frac{\kappa_f}V \frac{\partial \log ({\mathcal Z})}{\partial \kappa_f}
= \frac{\bar{\varphi} \, \kappa_b^{f/2} \, \kappa_f \, \frac{\varphi^{f-1}}{(f-1)!}}{1 + \sqrt{\kappa_b} \, \bar{\varphi} + \kappa_b \, \bar{\varphi}\varphi + \bar{\varphi}\sum_{f'=3}^q \kappa_b^{f'/2} \, \kappa_f' \, \frac{\varphi^{f'-1}}{(f'-1)!}} \, .
\end{equation}
%
At this point, we can obtain an expression for $N_2/V$, namely
%
\begin{equation}\label{eq:BifunctionalPoints}
\frac{N_2}V =
\rho - \sum_{f=3}^{q}(f-1)\frac{N_f}{V} = 
\frac{\sqrt{\kappa_b} \frac{\bar{\varphi}}2 + \kappa_b \varphi\bar{\varphi} -\frac{\bar{\varphi}}2 \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{(f-2)}{(f-1)!}\varphi^{f-1}}{1 + \sqrt{\kappa_b}\bar{\varphi} + \kappa_b \bar{\varphi}\varphi + \bar{\varphi} \sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}} \, ,
\end{equation}
%
where, we recall, the first equality is true since we keep neglecting terms ${\mathcal O}(1/V)$.
Then, again by using Eq.~\eqref{eq:UsefulIdentity}, we get:
%
\begin{equation}
\frac{N_2}V = \frac{\kappa_b\varphi\bar{\varphi}}{1 + \sqrt{\kappa_b}\bar{\varphi} + \kappa_b \bar{\varphi}\varphi + \bar{\varphi}\sum_{f=3}^q \kappa_b^{f/2} \kappa_f \frac{\varphi^{f-1}}{(f-1)!}} = \kappa_b \, q \, \rho (1-\rho) \, .
\end{equation}
%
Therefore, we are able to express the bond fugacity as a function of $\phi_2$ and $\rho$, {\it i.e.}
%
\begin{equation}\label{eq:BondFugacity}
\kappa_b = \frac{\phi_2}{q(1-\rho)} \, .
\end{equation}
%
We can now repeat a similar procedure for all the $\kappa_f$'s.
To this end, it is useful to notice that
%
\begin{equation}
\frac{N_1}{V} = \sum_{f=3}^q (f-2) \frac{N_f}V = (1-\rho)\sqrt{\kappa_b} \, \bar{\varphi} \implies \bar{\varphi} = \frac{\rho\phi_1}{(1-\rho)\sqrt{\kappa_b}} \, .
\end{equation}
%
Then, by simple manipulations, we obtain:
%
\begin{equation}\label{eq:BranchingPointFugacity}
\kappa_f = (f-1)! \, \phi_f \frac{\phi^{f-2}_1}{\phi^{f-1}_2} \, .
\end{equation}
%
We now have all the elements to compute the Legendre transform analytically, and the entropy per lattice site
%
\begin{equation}\label{eq:SperLatticeSite}
s^{{\mathbf x}_0} = \frac1V \log(\Xi) %\frac1V \log({\mathcal Z})
- \rho\log(\kappa_b) - \rho\sum_{f=3}^q \phi_f \log(\kappa_f) = -\rho + \log(1-\rho)  - \rho\log(\kappa_b) - \rho\sum_{f=3}^q \phi_f \log(\kappa_f) \, .
\end{equation}
%
With Eqs.~\eqref{eq:BondFugacity} and~\eqref{eq:BranchingPointFugacity}, Eq.~\eqref{eq:SperLatticeSite} becomes equivalent to Eq.~(5) %\eqref{eq:MFFreeEnergy}
in main text.
This concludes the derivation.


%%%
\section{A note on [Wagner, Erdemci-Tandogan, Zandi, J. Phys.: Condensed Matter (2015), Ref.~\cite{Wagner2015}]}\label{sec:CommentOnZandiWork}
%%%
In Ref.~\cite{Wagner2015}, Wagner {\it et al.} proposed a field-theoretic approach based on the $O(n\to0)$-model to describe polydisperse solutions of branching polymers {\it without} loops. 
However, as we are going to show here, an overlooked technical detail in their derivation implies that the statistical weight of looped conformations in the field-theoretic expression for the partition function of the system is strictly $\neq 0$, namely loops are effectively present.

Essentially, the work of Wagner {\it et al.}\footnote{Notice that similar ideas can be found in works~\cite{LubenskyIsaacson1979,Safran2002}.} is based on the idea of introducing apt external fields in the Hamiltonian of the magnet such that the ``$n \to 0$''-limit becomes equivalent to considering only conformations of self-avoiding branched polymers.
Rephrasing in the same language and notation of Sec.~\ref{sec:FieldTheoryCompleteDerivation}, we denote here with $J_1({\mathbf x})$ and $J_3({\mathbf x})$ the value of the external fields at lattice site of spatial coordinate $\mathbf x$.
Then, the formalism by Wagner {\it et al.} is equivalent to introducing the following trace properties (to be compared to our rules (I)-(VI) presented in Sec.~\ref{sec:FieldTheoryCompleteDerivation}) for the spins:
%
\begin{itemize}
%
\item[(I)]
Spins on different sites are independent of each other.
%
\item[(II)]
$\langle 1 \rangle = 1$.
%
\item[(III)]
$\langle S_i({\mathbf x}) \rangle = 0$.
%
\item[(IV)]
$\langle S_i({\mathbf x}) S_j({\mathbf x}) \rangle = \delta_{ij}$.
%
\item[(V)]
$\langle S_{i_1}({\mathbf x}) S_{i_2}({\mathbf x}) \dots S_{i_p}({\mathbf x}) \rangle = 0$ for $p \geq3$.
%
\item[(VI)]
$\langle S_{i}({\mathbf x}) J_1({\mathbf x}) \rangle = \delta_{i,1}$.
%
\item[(VII)]
$\langle S_{i_1}({\mathbf x}) S_{i_2}({\mathbf x}) S_{i_3}({\mathbf x}) J_3({\mathbf x}) \rangle = \delta_{i_1, i_2, i_3, 1}$.
%
\end{itemize}
%
At the same time, all the other traces involving the external fields $J_1$ and $J_3$ are set $=0$.
In terms of these rules, the Wagner-Erdemci-Tandogan-Zandi grand canonical partition function $\Xi_{\rm WETZ}$ of the system is given by
%
\begin{equation}\label{eq:WETZ-GrandCanonical}
\Xi_{\rm WETZ} = \lim_{n \to 0} \bigg\langle e^{\frac12 \sum_{{\mathbf x}, {\mathbf x}'} {\mathbf S}({\mathbf x}) \cdot {\mathbf S}({\mathbf x}') \Delta({\mathbf x}, {\mathbf x}')}\prod_{\mathbf x} \bigg( 1 + J_1({\mathbf x}) + J_3({\mathbf x}) \bigg) \bigg\rangle \, ,
\end{equation}
%
where all fugacities have been set to $=1$ for simplicity.
Now notice that, due to the trace rules, the exponential term in Eq.~\eqref{eq:WETZ-GrandCanonical} can be Taylor-expanded and only terms up to the first order need to be retained, since the rest of higher order terms contribute ${\mathcal O}(n)$ and, therefore, disappear in the $n \to 0$ limit.

%%%
\begin{figure}
%\centering
\includegraphics[scale=0.40]{zandi_example.png}
\caption{
Illustrative conformation of a branched polymer containing a loop on a $3\times3$ square lattice.
Sites of the lattice are numbered from $0$ to $8$.
}
\label{fig:LoopExample}
\end{figure}
%%%

Similarly to Sec.~\ref{sec:On->0model-ii}, every term in the sum can be illustrated with a graphical example.
Thus a term $\sim J_1({\mathbf x})$ corresponds to the presence of an end-point on lattice site ${\mathbf x}$, while a term $\sim J_3({\mathbf x})$ indicates the presence of a branch-node (with functionality $=3$).
Then, analogously to our model (see Sec.~\ref{sec:On->0model-i}), a term ${\mathbf S}({\mathbf x}) \cdot {\mathbf S}({\mathbf x}')$ represents an {\it undirected} bond between lattice positions ${\mathbf x}$ and ${\mathbf x}'$. 
Consider now the conformation depicted in Fig.~\ref{fig:LoopExample}, whose weight corresponds to the expression:
%
\begin{equation}\label{eq:LoopedExample}
\sum_{\substack{j_1, j_2, j_3 \\ j_4, j_5}} \langle J_1({\mathbf x}_0) \, S_{j_1}({\mathbf x}_0) S_{j_1}({\mathbf x}_3) \, J_3({\mathbf x}_3) \, S_{j_2}({\mathbf x}_3) S_{j_2}({\mathbf x}_4) \, S_{j_3}({\mathbf x}_4) S_{j_3}({\mathbf x}_7) \, S_{j_4}({\mathbf x}_7) S_{j_4}({\mathbf x}_6) \, S_{j_5}({\mathbf x}_6) S_{j_5}({\mathbf x}_3) \rangle \, .
\end{equation}
%
By factorizing terms referring to different sites and after using the trace properties, it is easy to see that the weight of the conformation is $\neq 0$ despite the conformation contains a loop.
In other words, the choice of Wagner {\it et al.} of breaking the $O(n)$-symmetry by choosing a privileged component for the external fields (the component $1$, see Eqs.~(A.20) and~(A.21) in the appendix of Ref.~\cite{Wagner2015}) is not harmless, and ultimately leads to polymer configurations containing loops:
for further validation, notice that the partition function for branching polymers of Wagner {\it et al.} (see Eq.~(A.22) in their work~\cite{Wagner2015}) is in essence identical to the partition function of the model by Lubensky and Isaacson~\cite{LubenskyIsaacson1979} (see Eqs.~(A11),~(A12) and~(A13) therein) who, as pointed out by the same authors, includes indeed loops.


