\subsection{Contribution I: \useieee{Reducing }\uselipics{A Reduction from }\#SAT to Two Calls of \#2DNF}
We provide a new reduction from $\Lang{\#sat}$ to \emph{two} calls to a
\Lang{\#2sat} or \Lang{\#2dnf} oracle. Crucially, we only need a \emph{single subtraction} to combine the
results (no involved postprocessing or modulo computations). All our reductions are logspace computable and,
thus, we can phrase our $\Lang{\#2sat}$ reduction as follows:

\begin{restatable}{theorem}{maintheorem}\label{theorem:main}%
\begin{enumerate}[label=(\arabic*)]
    \item $\Lang{\#sat}\in[\Lang{\#2sat}-\Lang{\#2sat}]^{\log}$
    \item $[\Lang{\#2sat}-\Lang{\#2sat}]^{\log}=[\Lang{\#2dnf}-\Lang{\#2dnf}]^{\log}$
\end{enumerate}  
\end{restatable}

Since \Lang{\#2sat} does not admit an $\Class{FPRAS}$ under common assumptions~\cite{sly2010computational}, we have
$\Lang{\#2sat}\not\in[\Lang{\#2dnf}]^{\log}$ and, hence, an
Immerman-Szelepcsényi-type theorem does \emph{not hold} in the counting
world. Theorem~\ref{theorem:main}, however, establishes a theorem of this type
if \emph{two} calls are permitted. 
In fact, we prove a stronger form of the first part of the theorem:
we reduce to restricted versions of \Lang{\#2sat}; the reduction
can be implemented either in logspace or in linear time; and it %the reduction
preserves important structural and symmetry properties of the input.

\begin{restatable}[Main Lemma]{lemma}{mainlemma}\label{lemma:main}%  
  There is a $\{$ linear-time, logspace $\}$ algorithm mapping a \Lang{cnf} $\phi$ and a corresponding tree decomposition to \Lang{cnf}s $\psi_1$ and $\psi_2$ with at most two variables per clause such that, for $\rho\in\{\tw, \itw, \bw, \ibw\}$,%
  \footnote{Here $\tw(\phi), \itw(\phi), \bw(\phi), \ibw(\phi)$ denote treewidth and bandwidth of two different graphs associated with formula $\phi$; see Section~\ref{sec:contrib-iv}.}
  ~\\[-1em]\[ %~\\[-2.5em]
  \#(\phi) = \#(\psi_1) - \#(\psi_2)%
  \quad\text{and}\quad\useieee{\]\vspace{-1.7em}\[}%
  \max\{\rho(\psi_1),\rho(\psi_2)\}\leq \alpha\cdot\rho(\phi) +
  14\text{ with } %\rho\in\{\bw, \itw\}, 
  \alpha = 1.%
  \]
  \noindent For $\rho\in\{\tw,\itw\}$, the resulting formulas can be restricted to the following fragments:
  \begin{enumerate}[label=(\Alph*)]
  \item $\alpha=1$ and $\psi_1, \psi_2$ are \emph{monotone}, i.e., do not contain negations; or
  \item $\alpha=3$ and $\psi_1, \psi_2$ comprise binary \emph{implications} and are \emph{cubic} and \emph{bipartite}, i.e., every variable occurs at most three times and the primal graph does not contain an odd~cycle.
  \end{enumerate}  
\end{restatable}
%\medskip

The second part of Theorem~\ref{theorem:main} follows because
$[\Lang{\#2sat}-\Lang{\#2sat}]^{\log}$ and
$[\Lang{\#2dnf}-\Lang{\#2dnf}]^{\log}$ both turn out to be precisely
$\Gap\Class{P}$. We discuss this further in the next subsection.
While Lemma~\ref{lemma:main} is the key to all our contributions, a direct consequence is the following:

\begin{corollary}\label{cor:sharpmon}
  $\Class{\#P}{\,\subsetneq\,}[\Lang{\#mon2sat}{-}\Lang{\#mon2sat}]^{\log}{\,\subseteq\,}\Gap\Class{P}$.
\end{corollary}
\begin{proof}
  Containment follows from Lemma~\ref{lemma:main}; it must be
  strict as functions in $\Class{\#P}$ cannot map to
  negative numbers but functions in $[\Lang{\#mon2sat}-\Lang{\#mon2sat}]^{\log}$ can. 
\end{proof}

\noindent Interestingly, we do not expect to improve the reduction of Lemma~\ref{lemma:main} for planarity while keeping linear time.


\begin{proposition}\label{proposition:planar}
	There is no $c$-monious$^{\ref{sec:cmonious}}$ linear-time Turing reduction from $\Lang{3sat}$ to $\Lang{\#planar3sat}$ (under $\Class{ETH}$).
	%\textcolor{red}{todo 3: under eth we can't improve to a planar version without quadratic blow-up!}
\end{proposition}


\subsection{Contribution II: New Characterization of GapP}

%\textcolor{red}{Focus on \#2DNF is the easiest problem with known gapP-C. FP - TotP is also GapP-C, but we have an open problem about one call to spanL. (maybe progress toward negative result)}

Because subtracting the model counts of two monotone formulas is
enough to capture~$\Class{\#P}$, the natural next question is
what is needed to capture $\Gap\Class{P}$. While $\Gap\Class{P}$ is still defined on non-deterministic Turing machines, in contrast to $\#\Class{P}$ it amounts to the number of \emph{accepting paths minus} the number of \emph{rejecting paths}. We show that even this class can
be characterized by two calls to oracles of restricted fragments of
$\Lang{\#2sat}$ or $\Lang{\#2dnf}$. In the following theorem,
$\Class{\#P} - \Class{\#P}$ (respectively $\Span\Class{L} - \Span\Class{L}$)
refers to the subtraction of the results of two~$\Class{\#P}$
(respectively $\Span\Class{L}$) oracle calls. Since it is open whether
$\Lang{\#dnf}$ is $\Span\Class{L}$-hard, and since it is \emph{not expected}~\cite[Theorem 2]{sly2010computational} for $\Lang{\#2sat}$ to be in $\Span\Class{L}$ (unless we have $\Class{RP}=\Class{NP}$), this makes our characterization of $\Class{\#P}-\Class{\#P}$ 
via $[\Lang{\#2sat}-\Lang{\#2sat}]^{\log}$ \emph{and its dual}
$[\Lang{\#2dnf}-\Lang{\#2dnf}]^{\log}$ significant; the result holds even in the absence of negation. %, even without negation.
%problems and their duals. % possibly stronger than spanL-spanL. 
%
Below, $\Lang{\#impl2sat}$ is strictly in $\Lang{\#Horn2sat}$ and $\Lang{\#0,1-2dnf}$ is its dual over~$\Lang{dnf}$.

\begin{restatable}[Characterization of GapP]{theorem}{gaptheorem}\label{theorem:gapp}\useieee{\quad\quad$\Gap\Class{P}=$}%
  ~\\[-1.75em]\begin{align*}
    %~\\[-2em]&\Gap\Class{P} \\ %\Class{\#P} - \Class{\#P} = [\#3\Lang{sat} - \#3\Lang{sat}]^{\log} \\
    %%&= [\#3\Lang{dnf} - O(1)]^{\log}
   %% = [O(1)-\#3\Lang{dnf}]^{\log}\\
    \uselipics{\Gap\Class{P}}&= [\Lang{\#2sat}{-}\Lang{\#2sat}]^{\log} = [\Lang{\#impl2sat}{-}\Lang{\#impl2sat}]^{\log}\\[-0.25em]
    &= [\Lang{\#0,1-2dnf}{-}\Lang{\#0,1-2dnf}]^{\log} = [\Lang{\#2dnf}{-}\Lang{\#2dnf}]^{\log} \useieee{\\[-0.25em]&}= [\Lang{\#dnf}{-}\Lang{\#dnf}]^{\log}\uselipics{\\
    &}= [\#\Lang{mon2sat} {-} \#\Lang{mon2sat}]^{\log} \useieee{\\[-0.25em]&}= [\#\Lang{mon2dnf} {-} \#\Lang{mon2dnf}]^{\log}
    = \Span\Class{L} {-} \Span\Class{L}.
    \end{align*}~\\[-1.5em]
The characterization extends to \emph{cubic} and \emph{bipartite} restrictions of $\Lang{\#impl2sat}$ and $\Lang{\#0,1-2dnf}$;
	even if both formulas use the same variables and differ by only one literal/variable occurrence. %if restricted to ~formulas.
\end{restatable}

%
This result illustrates the
\emph{power of subtraction}, which by the theorem compensates for both the
absence of negation \emph{and} clauses of size at least three. Since
it is known that
$\Lang{\#2dnf}\in\Span\Class{L}$ with
$\Span\Class{L}\subsetneq\Class{\#P}$ (unless
$\Class{NL}=\Class{NP}$~\cite[Proposition 4.10]{AlvarezJenner93}) and $\Class{\#P}\subsetneq\Gap\Class{P}$ by
Corollary~\ref{cor:sharpmon}, Theorem~\ref{theorem:gapp} implies
that $\Class{\#P}$ is \emph{strictly sandwiched} between one and two 
\Lang{\#2dnf} oracle calls: 

\begin{corollary}
  $[\Lang{\#2dnf}]^{\log}\subsetneq \Class{\#P}$ unless $\Class{NL}=\Class{NP}$; and $\Class{\#P} \subsetneq [\Lang{\#2dnf}-\Lang{\#2dnf}]^{\log}$ unless $\Class{UP}=\Class{SPP}$.
\end{corollary}

