Formally, we define the construction of the symmetric rogue model as follows. %covered next.

\begin{definition}[Symmetric Rogue Model]\label{def:roguesymm}
%
Let $M$ be a model of a formula~$\phi'$ with~$\phi'\supseteq R(\phi, {\mathcal{T}})$
that is rogue at~$t$. 
%
Assume that (1) there is no ancestor~$t'$ of~$t$ in~$T$ such that~$M$ is rogue at~$t'$,
and that (2) $t$ is on the lexicographic smallest root-to-leaf path in~$T$.
%
%
Then, the \emph{symmetric rogue model $M'$
(of~$M$)} is constructed as:
\begin{itemize}
    \item If $x\notin M$, we define $M'=M$
    \item Otherwise, if $x\in M$:
    \begin{itemize}
    \item Replace $o_t\in M$ by $e_t\in M'$ (and vice versa, i.e., $e_t\in M$ iff $o_t\in M'$).
    \item For every ancestor~$t'$ of~$t$ in~$T$, we replace $o_{t'}\in M$ by $e_{t'}\in M'$ and vice versa (i.e., $e_{t'}\in M$ iff $o_{t'}\in M'$), as well as $o1_{t'}\in M$ by $e1_{t'}\in M'$, $e1_{t'}\in M$ by $o1_{t'}\in M'$, $o2_{t'}\in M$ by $e2_{t'}\in M'$, $e2_{t'}\in M$ by $o2_{t'}\in M'$ (and vice versa)
    \item If (a) either\footnote{``Either $\ldots$ or'' refers to an exclusive disjunction.} $o_t\in M$ or $e_t\in M$, and (b) $|M\cap \{o1_t, o2_t, e1_t, e2_t\}|\geq 1$, 
    we additionally replace $o1_t\in M$ by $e2_t\in M'$, $o2_t\in M$ by $e1_t\in M'$ and vice versa (i.e., $e1_t\in M$ by $o2_t\in M'$, $e2_t\in M$ by $o1_t\in M'$)
    \end{itemize}
\noindent We say that $M$ is the \emph{symmetric rogue model} of~$M'$.
\end{itemize}
\end{definition}

With this definition at hand, we commence with proving correctness
of the reduction. To that end, we need to show that
symmetric rogue models are well-defined, i.e., that the construction
ensures that a symmetric rogue model~$M'$ of a rogue model~$M$ is
\emph{(a)} a model and \emph{(b)} rogue at a node~$t$ if and only $M$
is rogue at~$t$. This is established by Lemmas~\ref{lem:welldef} and \ref{lem:symmetry}, where full proof details are given in Appendix~\ref{sec:mainproof}. % the following two lemmas.
In Appendix~\ref{sec:structure} we show that \emph{structural parameters are linearly preserved}.

\subsection{Reducing to Monotone Formulas}\label{section:monotone}
We reuse the same construction as in
Equations~(\ref{lab:wcnf})--(\ref{eq:e2}), but in the following assume
\emph{fully labeled tree decompositions}, where also every variable is
a label of a tree decomposition node.  For a literal~$l$ over variable~$v$, we let~$inv(l)$ be the
variable~$\top_v$ if $l=\neg v$ and be~$\bot_v$ otherwise. Intuitively these auxiliary variables are used to refer to the truth value for $v$. We update
the inclusion-exclusion reduction such that
for every clause~$c=l_1 \vee l_2 \vee\cdots \vee l_k$ we construct \emph{positive clauses}:
\begin{flalign}
    \label{lab:wcnf2}& \overline{\text{\d{$c$}}} \vee inv(l_1)\qquad \overline{\text{\d{$c$}}} \vee inv(l_2)\qquad\ldots\uselipics{\qquad}\useieee{\quad} \overline{\text{\d{$c$}}} \vee inv(l_k) &&\text{}\useieee{\raisetag{1.15em}}
\end{flalign}

Additionally, for every node~$t$ with $t'\in\children(t)$ and $v\in\delta(t)\cap\vars(\phi)$, we add:
\begin{flalign}
    &\overline{v} \vee \top_v & \overline{v} \vee  \bot_v && \top_v\vee \bot_v&&\text{Choosing $v$ sets $v$ to true}\notag\\[-.5em] &&&&&&\text{and to false.\qquad\qquad\quad}\raisetag{1.15em} \label{eq:var}
\end{flalign}

We slightly adapt Equations~(\ref{eq:o1})--(\ref{eq:e2}) such that for every node~$t$ in~$T$ with $t'\in\children(t)$ and label $\alpha\in\delta(t)$, which can be either a clause or a variable, we construct:
\begin{flalign}
    & \overline{o1_t} \vee e_{t'} & \overline{o1_t} \vee \alpha && \overline{o1_t} \vee o_t &&& \text{Case 1: odd by}\notag\\[-.5em] &&&&&&&\text{choosing $\alpha$}\label{redpos:o1}\\
    & \overline{o2_t} \vee o_{t'} & \overline{o2_t} \vee \overline{\alpha} && \overline{o2_t} \vee o_t &&& \text{Case 2: odd by}\notag\\[-.5em] &&&&&&&\text{not choosing $\alpha$}\\[.75em]
    %
    & \overline{e1_t} \vee o_{t'} & \overline{e1_t} \vee \alpha && \overline{e1_t} \vee e_t &&& \text{Case 1: even by}\notag\\[-.5em] &&&&&&&\text{choosing $\alpha$}\\
    & \overline{e2_t} \vee e_{t'} & \overline{e2_t} \vee \overline{\alpha} && \overline{e2_t} \vee e_t &&& \text{Case 2: even by}\notag\\[-.5em] &&&&&&&\text{not choosing $\alpha$}\hspace{.75em}\label{redpos:e2}%\\[1.5em]
    %
\end{flalign}
%
By adapting Equation~\ref{red:leaf}, we obtain:
\begin{flalign}
    \label{redpos:leaf} & \overline{x} \vee e_t && \text{Initially, we choose $0$ clauses \& variables.}
\end{flalign}


\begin{example}\label{ex:running3}
    Recall the reduction given in Example~\ref{ex:running2}. Assume a labeled tree decomposition~$\mathcal{T}=(T,\chi,\delta)$ comprising the nodes~$t_0$, $t_1$, $\ldots$, $t_6$ such that $\delta(t_1)=c_1$, $\delta(t_2)=c_2$,  $\delta(t_3)=c_3$, $\delta(t_4)=a$, $\delta(t_5)=b$, and $\delta(t_6)=c$.
    %
    Then, by constructing Equations~(\ref{lab:wcnf2})--(\ref{redpos:leaf}) similarly to Example~\ref{ex:running2}, we obtain a formula~$\varphi'$. 
    %
 %   
In order to count~$\#(\varphi)$, we can compute~$\#(\varphi' \cup \{\overline{x} \vee e_6\})-\#(\varphi' \cup \{\overline{x} \vee o_6\})=$ $2{,}110{,}863{,}758-2{,}110{,}863{,}756=2$.
\end{example}

Note that, as above, one can easily adapt to the simpler types of tree decomposition nodes, see Equations~(\ref{eq:simple})--(\ref{eq2:e2}).
We refer to the adapted reduction comprising
Equations~(\ref{lab:wcnf2})--(\ref{eq:var}),
(\ref{redpos:o1})--(\ref{redpos:e2}), and (\ref{redpos:leaf})
by~${R}'(\phi,\mathcal{T})$. 
%
%
%
Roughly, the idea is to introduce an additional type of label (for variables) and ensure that Equations~(\ref{redpos:o1})--(\ref{redpos:e2}) work for \emph{both clause and variable labels}. By construction, a node of a labeled tree decomposition can only have one label (and therefore only one type). However, we do not care to manage these labels individually, but the idea is to keep track of the \emph{parity of the combined number} of corresponding variables being true.
%
Let us, as in the previous
section, also stipulate
\(
\psi_1'\coloneq R'(\phi, \mathcal{T}) \cup \{\overline{x} \vee e_{\rootOf(T)} \}
\)
and
\(
\psi_2'\coloneq
R'(\phi, \mathcal{T}) \cup \{\overline{x} \vee o_{\rootOf(T)} \}.
\)

Extensions of rogue models for \emph{monotone formulas} and proofs are given in Appendix~\ref{section:proofmonotone}.
Appendix~\ref{section:cubic-bipartite} generalizes the reduction to %monotone formulas, which is then further generalized to 
\emph{cubic and bipartite formulas}. % in Section~\ref{section:cubic-bipartite}.

