\section{Proof of the Main Lemma}\label{sec:mainproof}


\begin{lemma}[Well-Definedness]
\label{lem:welldef}
    Let~$\phi$ be a \Lang{cnf}, $\mathcal{T}$ be a tree
    decomposition of it, and $M$ be a satisfying assignment of~$\psi_1$ that is rogue.
    The symmetric rogue model $M'$ of $M$ is a satisfying assignment of~$\psi_2$. Vice versa, the result holds if roles of $M$ and $M'$ are swapped. 
\end{lemma}
\begin{proof}
Let $M$ be rogue at a node $t$.  Assume that (1) there is no
indirect ancestor node of $t$ (e.g., parent node) such that $M$ is
rogue at this node. So $t$ is the node closest to the root of $T$ with
$M$ being rogue at this node. Further, (2) $t$ is on the lexicographic smallest root-to-leaf path in~$T$. Let $M'$ be the symmetric rogue model
of~$M$.  We proceed by case distinction on \emph{why} $M$ is rogue at $t$.

\begin{description}
  \item[Case \emph{(i)}.] We have $x\notin M$ and, therefore, $M'$ is
unique for $M$ and vice versa.
\end{description}

In the following cases we have $x\in M$ and, thus, $e_{\rootOf(T)}\in
M$. Furthermore,
since $t$ is also the first node such that $M$ is rogue at $t$
and $M$ is a model of $\psi_1$, we conclude that $o_t\in M$ or $e_t\in M$.
(Either $t=\rootOf(T)$ or $M$ is not rogue at the parent node of $t$, requiring $o_t\in M$ or $e_t\in M$).
Consequently, $M$ can only be rogue at $t$ due to property
\emph{(ii)}, \emph{(iii)}, or \emph{(iv)} in Definition~\ref{def:rogue} if both
$o_t\in M$ and $e_t\in M$.

\begin{description}
\item[Case \emph{(iv)}.]  Since both $o_t, e_t\in M$, the construction
  of $M'$ results in $M'$ being a model of $\psi_2$,
  i.e., the replacement of $o_t$ by $e_t$ (and vice versa) does not
  destroy model status of $\psi_2$.
  %
  %
  %
\item[Case \emph{(iii)}.]  If $M \cap \{\text{\d{$c$}}, \overline{\text{\d{$c$}}}\}=\emptyset$,
  we have $M\cap \{o1_t, o2_t, e1_t, e2_t\}\allowbreak=\emptyset$.
  The replacement of $o_t\in M$ by $e_t\in M'$ (and vice versa)
  results in $M'$ being a model of $\psi_2$.  If $\text{\d{$c$}}, \overline{\text{\d{$c$}}}\in
  M$ and $|M\cap \{o1_t, o2_t, e1_t, e2_t\}|< 1$, again, it is easy to
  see that replacing $o_t\in M$ by $e_t\in M'$ (and vice versa)
  results in $M'$ being a model of $\psi_2$. Otherwise, if $\text{\d{$c$}},
  \overline{\text{\d{$c$}}}\in M$ and $|M\cap \{o1_t, o2_t, e1_t, e2_t\}|\geq 1$,
  note that $M'$ is obtained from~$M$ by \emph{additionally replacing}
  $o1_t\in M$ by $e2_t\in M'$ and $o2_t\in M$ by $e1_t\in M'$ (and
  vice versa, respectively). Since both $\text{\d{$c$}},\overline{\text{\d{$c$}}}\in M$, this
  ensures that therefore $M'$ is a model of $\psi_2$.
  %
  %
  %
\item[Case \emph{(ii)}.]  If $M\cap \{o1_t, o2_t, e1_t,
  e2_t\}=\emptyset$, indeed, $M'$ is a model
  of~$\psi_2$ as well. Note that $|M\cap \{o1_t,
  o2_t, e1_t, e2_t\}|>1$ can never occur, assuming we have neither
  Case \emph{(iv)} nor Case \emph{(iii)}. The roles of~$M$ and~$M'$ can be easily
  switched, as the replacements of Definition~\ref{def:roguesymm} are
  completely symmetric. \qedhere
\end{description}
\end{proof}

\begin{lemma}[Symmetry]
\label{lem:symmetry}
    Let~$\phi$ be a \Lang{cnf}, $\mathcal{T}$ be a tree
    decomposition of it, and
    $M$ be a satisfying assignment of~$\psi_1$ that is rogue.
    Then, (I) a model $M$ of~$\psi_1$ is rogue at a node $t$ iff the symmetric rogue model $M'$ of~$\psi_2$ is rogue at $t$ (and vice versa with swapped $M$ and $M'$);
    and, (II) mapping the rogue model of~$\psi_1$ to its symmetric rogue model forms a bijection.
\end{lemma}
\begin{proof}
We define a function~$f$ mapping models~$M$ of~$\psi_1$ to corresponding symmetric rogue models~$M'$ of~$\psi_2$.
Suppose $M$ is rogue at a node~$t'$ of~$T$.
In order to show that \emph{(I)} $M'=f(M)$ is also rogue at $t'$, let
$t^\star$ be the node of $T$ such that $M$ is rogue at~$t^\star$ with
$M$ not being rogue at an ancestor of~$t^\star$.  We distinguish the following cases:
\begin{description}
\item[Case $t'$ is an ancestor of~$t^\star$.]%\useieee{~\\}
  By construction $M$ is not rogue at~$t^\star$ iff $M'$ is not rogue
  at~$t^\star$.
  %
  %
\item[Case $t'$ is a descendant of~$t^\star$.]%\useieee{~\\}
  Since $M$ and $M'$ are by construction identical regarding
  Definition~\ref{def:rogue} \emph{(i)}--\emph{(iv)}, we conclude that
  $M$ is rogue at~$t^\star$ iff $M'$ is not rogue at~$t^\star$.
  %
  %
\item[Case $t'=t^\star$.]%\useieee{~\\}
  Holds as the construction of Definition~\ref{def:roguesymm} does not change the rogue status of a model.
\end{description}

The proof works analogously if the roles of $M$ and $M'$ are swapped.
It remains to show~\emph{(II)}: $f$ is indeed a bijection. By
Lemma~\ref{lem:welldef}, $f$ is well-defined. Further, by the
construction given in Definition~\ref{def:roguesymm}, $f$ is also
injective. Suppose towards a contradiction that there was a rogue
model~$M_2$ of $\psi_2$ and two rogue models~$M_1, M_1'\in
f^{-1}(M_2)$. One can proceed by case distinction.  Since we start
replacing $o_{t'}$ by $e_{t'}$ (and vice versa) for nodes~$t'$ from
${t^\star}$ upwards in the direction towards the root of~$T$, $M_1$
and $M_1'$ coincide on the assignment of $o_{t'}$ and $e_{t'}$.  The
remaining interesting case is the last item of
Definition~\ref{def:roguesymm}. Observe that we only replace
$o1_{t^\star}$ by $e2_{t^\star}$, $o2_{t^\star}$ by $e1_{t^\star}$
(and vice versa) if without this replacement the result is not a
model.  Therefore, $M_1=M_1'$, which shows that $f$ is injective.

It remains to show that $f$ also is surjective. Suppose towards a contradiction that there is a rogue model~$M''$ of~$\psi_2$ such that $f^{-1}(M'')$ is not defined.
However, we can construct a rogue model~$M'''$ of~$M''$ according to
Definition~\ref{def:roguesymm}. Then, by Lemma~\ref{lem:welldef} and
(i) above, $M'''$ is indeed a rogue model
of~$\psi_1$. This contradicts the assumption that
$f^{-1}(M'')$ is not defined, since $M'''=f^{-1}(M'')$. 
\end{proof}

\begin{lemma}
\label{lem:nonmodels}
    %Let~$\phi$ be a \Lang{cnf} and $\mathcal{T}$ be a tree decomposition of it.
