 \begin{enumerate}[label=(\roman*)]
 \item $x\notin M$,
 \item $|M\cap \{o1_t, o2_t, e1_t, e2_t\}|\neq 1$, 
 %
 \item $|M\cap \{\text{\d{$c$}}, \overline{\text{\d{$c$}}}\}|\neq 1$, $|M\cap \{\text{\d{$c$}}, c', c''\}| \notin \{0,3\}$, or $|M\cap \{\overline{\text{\d{$c$}}}, \overline{c}', \overline{c}''\}| \notin \{0,3\}$ with $c{\in}\delta(t)$,~or
 %
 %
 %\item  with $c\in\delta(t)$,
 %
 %
 %\item  with $c\in\delta(t)$, or
 %
 %
 \item $|M\cap \{o_t, e_t\}|\neq 1$, $|M\cap \{o_t, o_t', o_t''\}| \notin \{0,3\}$, or $|M\cap \{e_t, e_t', e_t''\}| \notin \{0,3\}$.
 \end{enumerate}
\end{definition}

Then, we can still bijectively translate rogue models between $\psi^{\text{C+B}}_1$ and $\psi^{\text{C+B}}_2$.

\begin{definition}[Symmetric Rogue Model For Cubic and Bipartite]\label{def:roguesymm_3}
%
Let $M$ be a rogue model at~$t$ of a formula~$\phi'$ with~$\phi'\supseteq R^{\text{C+B}}(\phi, {\mathcal{T}})$. 
%
Assume that (1) there is no ancestor~$t'$ of~$t$ in~$T$ such that~$M$ is rogue at~$t'$ and that (2) $t$ is on the lexicographic smallest root-to-leaf path of~$T$.
%
The \emph{symmetric rogue model $M'$
(of~$M$)} is constructed as follows.
\begin{itemize}
    \item If $x\notin M$, we define $M'=M$
    \item Otherwise, if $x\in M$:
    \begin{itemize}
    \item Replace $o_t\in M$ by $e_t\in M'$, $o_t'\in M$ by $e_t'\in M'$, and $o_t''\in M$ by $e_t''\in M'$ (as well as vice versa, i.e., $e_t\in M$ iff $o_t\in M'$, $e_t'\in M$ iff $o_t'\in M'$, and $e_t''\in M$ iff $o_t''\in M'$).
    %
    \item For every ancestor~$t'$ of~$t$ in~$T$, we replace $o_{t'}\in M$ by $e_{t'}\in M'$, $o_{t'}'\in M$ by $e_{t'}'\in M'$, $o_{t'}''\in M$ by $e_{t'}''\in M'$, and vice versa (i.e., $e_{t'}\in M$ iff $o_{t'}\in M'$, $e_{t'}'\in M$ iff $o_{t'}'\in M'$, $e_{t'}''\in M$ iff $o_{t'}''\in M'$), as well as $o1_{t'}\in M$ by $e1_{t'}\in M'$, $e1_{t'}\in M$ by $o1_{t'}\in M'$, $o2_{t'}\in M$ by $e2_{t'}\in M'$, $e2_{t'}\in M$ by $o2_{t'}\in M'$ (and vice versa)
    %
    \item If (a) either $o_t\in M$ or $e_t\in M$, and (b) $|M\cap \{o1_t, o2_t, e1_t, e2_t\}|\geq 1$, 
    we additionally replace $o1_t\in M$ by $e2_t\in M'$, $o2_t\in M$ by $e1_t\in M'$ and vice versa (i.e., $e1_t\in M$ by $o2_t\in M'$, $e2_t\in M$ by $o1_t\in M'$).
    %
    \item If (a), (b), and (c) $|M\cap \{\text{\d{$c$}}, \overline{\text{\d{$c$}}}\}|=1$ with $c\in\delta(t)$, 
    we additionally replace $\text{\d{$c$}}\in M$ by $\overline{\text{\d{$c$}}}\in M'$, $c'\in M$ by $\overline{c}'\in M'$, $c''\in M$ by $\overline{c}''\in M'$ and vice versa (i.e., $\overline{\text{\d{$c$}}}\in M$ by $\text{\d{$c$}}\in M'$, $\overline{c}'\in M$ by $c'\in M'$, $\overline{c}''\in M$ by $c''\in M'$).
    \end{itemize}
   \noindent We say that $M$ is the \emph{symmetric rogue model} of~$M'$.
\end{itemize}
\end{definition}

With these key definitions, we can establish correctness similarly to Lemmas~\ref{lem:welldef}--\ref{lem:nonmodels} and Proposition~\ref{prop:corr}.
