	\title{Dynamic Fingerprint of Controlled Structural Disorder in Artificial Spin Lattices} 

	\author{Vinayak Shantaram Bhat}\email[]{Authors to whom correspondence should be addressed: vbhat@udel.edu, mbj@udel.edu}
	\affiliation{Department of Physics and Astronomy, University of Delaware, Newark, DE 19716, USA}%
