\section{The implementation of the Gibbs sampler for the mixture of normals}\label{a:mnms-gibbs}

With $\mu_0 = 0$ and $\sigma_0^2 = 10^4$, the steps for a Gibbs sampler with a Dirichlet prior are
\begin{enumerate}
    \item Initialize $\pi^{(1)}_1, \dots, \pi_1^{(K)}$ and $\phi^{(1)}, \dots, \phi^{(K)}$ such that $\sum_{i=1}^K \pi_1^{(i)} = 1$ and $\phi_{i}^{(1)} \leq \phi_{i+1}^{(i)}$ for all $i \in 1, 2,\dots, K-1$.
    \item Sample the augmented variable $$Z^{(t)}_i\sim P(Z_i = k | \pi^{(t)}_1, \dots, \pi^{(t)}_K, \phi^{(t)}_1, \dots, \pi^{(t)}_K) \propto \pi^{(t)}_{k} \exp\left(-\frac{(Y_i - \phi_i^{(t)})^2}{2}\right)$$
    for $i = 1, \dots, n$.
    \item Using $\eta_k^{(t)} = \sum_{i=1}^n \mathbb{I}(Z_i^{(t)} = k)$ for $k = 1,\dots, K$, sample 
    $$(\pi^{(t+1)}_1, \dots, \pi^{(t+1)}_K) \sim \text{Dirichlet}(1 + \eta_1^{t}, \dots, 1+\eta_K^{(t)})$$
    \item Let $\bar \phi_k = \frac{1}{\eta_k^{(t)}} \sum_{i=1}^n Y_i\mathbb{I}(Z_i^{(t)} = k)$, and sample the posterior means
    $$\phi_i^{(t+1)} \sim N\left(\frac{\frac{\mu_0}{\sigma^2_0}+ \eta_k^{(t)}\bar\phi_k^{(t)}}{\frac{1}{\sigma^2_0} + \eta_k^{(t)}}, \left(\frac{1}{\sigma^2_0} + \eta_k^{(t)}\right)^{-1}\right)$$
    and go to step 2 to repeat.
\end{enumerate}
If instead, we wish to calculate the MLE for the initial estimate, for brevity, we present that case when $K_n=2$, where the $k^{th}$ expectation step is

$$w_i^{(k)} = \frac{\hat\pi_1^{(k-1)}\exp\left(-(y_i-\hat\phi_1^{(k)})^2\right)}{\hat\pi_1^{(k-1)}\exp\left(-(y_i-\hat\phi_1^{(k)})^2\right)+\left(1-\hat\pi_1^{(k-1)}\right)\exp\left(-(y_i-\hat\phi_2^{(k-1)})^2\right)},\qquad i = 1,\dots,n$$
and the $k^{th}$ maximization step is
$$\hat\pi_1^{(k)} = \frac{1}{n}\sum_{i=1}^n w_i^{k},\quad \hat\phi_1^{(k)} = \frac{\sum_{i=1}^n w_i^{(k)}Y_i}{\sum_{i=1}^n w_i^{(k)}},\quad\text{and}\quad \hat\phi_2^{(k)} = \frac{\sum_{i=1}^n (1-w_i^{(k)})Y_i}{\sum_{i=1}^n (1-w_i^{(k)})}.$$
By choosing some reasonable initialization values, such as $\pi_1^{(0)} = 0.5$, $\phi_1^{(0)} = \bar{Y} - 1$, and $\phi_2^{(0)} = \bar{Y}-1$, and iterating until the $\|\hat{\pi}^{(k)} - \hat{\pi}^{(k-1)}\|<10^6$, we obtain an approximate value for the MLE of the model parameters. The analogous setup where $K_n>2$ has a separate $w_i$ calculated for each component to estimate a larger set of $\pi_i$ values. Then, the $\phi_i$ are calculated similarly to above for each of the components.
