\begin{remark}\label{rmk:primeideal}\rm
Note that $CV_T^\MM$ is an irreducible variety, and hence its vanishing ideal $I^\MM_T$ is prime. Therefore, when computing phylogenetic invariants, we can factor out all variables $\tilde{p}_{i_1i_2i_3i_4}$ that do not belong to the ideal. In the case of $T_{12}$, those variables are the ones not listed in \Cref{prop:quartet-zeroes} except for $\tilde{p}_{3434},\tilde{p}_{4343},\tilde{p}_{3443},\tilde{p}_{4334}$ (see \cite[Remark 5.12]{CHT}).
%\mc{Revise, write for 12|34: that is, those not listed in \Cref{prop:quartet-zeroes} (nor any of the four topology zeroes in \Cref{prop:4quartetEq84,prop:4quartetEq} for $T=12\mid 34$)}. %{Revise: Also, note that such coordinates are generically non-zero for points in the phylogenetic variety. Indeed, since $\pi$ is assumed to be generic (\Cref{rmk:generic_pi}), such $\tilde{p}_{i_1i_2i_3i_4}$ are non-zero for nonsingular matrices $\Lambda^e$ (with the only possible exception of $\tilde{p}_{3344}=\tilde{p}_{4433}$ for $T=12\mid 34$ which additionally requires $\lambda_1\neq\lambda_2$ in the interior edge); see the parametrization of $\tilde{q}_{i_1i_2i_3i_4}$ in the proof of \Cref{prop:4quartetEq84} for further details.}
\end{remark} 

\subsection{Rank conditions for F84}

\begin{prop}\label{prop:4quartetEq84}
Let $T=T_{12}$ be a quartet and consider the F84 model on it. The following equations hold for any point in $CV_T \subseteq \F_4^{F84}\cap\Z_4$: 
\begin{itemize}
    \item[(a)] $\tilde{p}_{3434}=\tilde{p}_{3443}=0$;
    \item[(b)] $\tilde{p}_{2424}=\tilde{p}_{2323}$, $\tilde{p}_{2442}=\tilde{p}_{2332}$, $\tilde{p}_{4224}=\tilde{p}_{3223}$, $\tilde{p}_{4242}=\tilde{p}_{3232}$.
\end{itemize}
\end{prop}  
\begin{proof}
Since $\tilde{p}_{3434}=\tilde{p}_{3443}=0$ are topology invariants for $T_{12}$ in the TN93 model, equations in (a) hold for F84. We now consider submatrices $A^{14,24}_{14,24}$ and $A^{13,23}_{13,23}$ of rank 1 in Table \ref{tab:flatF84rk1}. Then 

\begin{eqnarray*}
0&=&\bar{\rho}_{1233}^2\left|A^{14,24}_{14,24}\right|-\bar{\rho}_{1244}^2\left|A^{13,23}_{13,23}\right|
    =\bar{\rho}_{1233}^2\bar{\rho}_{1144}\bar{\rho}_{2244}\tilde{p}_{1414}\tilde{p}_{2424}-\bar{\rho}_{1244}^2\bar{\rho}_{1133}\bar{\rho}_{2233}\tilde{p}_{1414}\tilde{p}_{2323}\\
    &=&\frac{1}{\left(\pi_1\pi_2\pi_3\pi_4\right)^2}\tilde{p}_{1414}\left(\tilde{p}_{2424}-\tilde{p}_{2323}\right),
\end{eqnarray*}


\noindent where the last equality is obtained by substituting the coordinates of the no-evolution point in \eqref{eq:rho_quartet}.
%Generically, {$\tilde{p}_{1414}\neq 0$}, hence
%this proves $\tilde{p}_{2424}=\tilde{p}_{2323}$ in an open set of the irreducible variety $CV_T^{F84}$, hence the equation holds in the whole variety. 
By \Cref{rmk:primeideal} we can factor $\tilde{p}_{1414}$ out, and hence $\tilde{p}_{2424}=\tilde{p}_{2323}$ in $CV_T^{F84}$.
The rest of equations in (b) can be proven analogously by considering submatrices $A^{1j,j2}_{1j,2j}$, $A^{1j,2j}_{1j,j2}$ and $A^{1j,j2}_{1j,j2}$, respectively, with $j\in\{3,4\}$. 
\end{proof}

\begin{remark}\label{rem:nonzero_F84}
\rm Note that the equations in \Cref{prop:4quartetEq84} have been obtained by imposing only the rank conditions on flattenings and the symmetry equations defining $\F_4^{F84}$. The rest of the proof only uses that $\tilde{p}_{1414}$ is different from zero. As a consequence of Corollary \ref{cor:mixt_tree}, 
 the ideal of $CV_T^{F84}$ is generated in degree 1 by the linear polynomials that correspond to the above equations.
