\noindent since each of the minors involved arises from a rank condition in Table \ref{tab:flatrank2}. Expanding each matrix in (\ref{eq:53aA}), via the third row and regrouping terms based on the column involved gives 
\begin{equation}\label{eq:53aB}
\begin{array}{l}
\left|A_{11,12}^{22,12}\right|\tilde{p}_{4411}(a\pp_{1144}+b\pp_{1122}+c\pp_{1133})  - \left|A_{11,12}^{11,12}\right|(a\pp_{2244}\tilde{p}_{2244}+b\pp_{2222}\tilde{p}_{2222}+c\pp_{2233}\tilde{p}_{2233}) \\
+  \left|A_{11,12}^{11,22}\right|(a\pp_{1244}+b\pp_{1222}+c\pp_{1233})=0.
\end{array}
\end{equation}

