        \item[(d)] $\pi_1\pi_2\pi_3\pi_4\tilde{p}_{3344}=\pi_{12}^2(\tilde{p}_{2233}-\tilde{p}_{2444})$;
        \item[(e)] $\pi_1\pi_2\pi_3\pi_4\tilde{p}_{3434}=\pi_{12}^2(\tilde{p}_{2323}-\tilde{p}_{2444})$;
        \item[(f)] $\pi_1\pi_2\pi_3\pi_4\tilde{p}_{3443}=\pi_{12}^2(\tilde{p}_{2332}-\tilde{p}_{2444})$;
        \item[(g)] $\pi_1\pi_2\pi_3\pi_4(\tilde{p}_{3344}+\tilde{p}_{3434}+\tilde{p}_{3443})=(\pi_{12}^3+\pi_{34}^3)(\tilde{p}_{2222}-\tilde{p}_{2444})$

