        \node (v) [right of = u] {$v$};
        \node (w) [right of = v] {$w$};
        \draw[->] (u) to node {$x$}(v);
        \draw[->] (v) to node {$y$} (w);
    \end{tikzpicture}
\end{center} 
\[\downarrow{F}\]
