\begin{center}
\Large\bf
Algebra of double cosets of a symmetric group by a smaller symmetric group

\bigskip

\large\sc Yu. A. Neretin%
\footnote{Supported by the grant FWF (The Austrian Scientific Funds),
Project PAT5335224.}

\end{center}

{\small Fix a natural $\alpha$. Let $n\ge \alpha$ be an integer.
Consider the symmetric group $S_{\alpha+n}$ and
its subgroup $S_n$. We consider the group algebra of  
$S_{\alpha+n}$ and its subalgebra $\bbO[\alpha;n]$ consisting
of $S_n$-biinvariant functions, i.e., functions, which are constant
on double cosets of $S_{\alpha+n}$ with respect to
$S_n$. We obtain a simple description of $\bbO[\alpha;n]$
in terms of generators and relations. We also construct an
interpolating family  
of algebras $\bbO[\alpha;n]$ depending on a complex parameter $n$. 
}

\section{\bf Introduction. Algebras of double cosets}

\COUNTERS

{\bf \punct 
Algebras of double cosets. Preliminaries.%
\label{ss:preliminaries}} For a group $G$ and its subgroup $K$
we denote by $K g K$, where $g\in G$, double cosets of $G$ with respect
to $K$. By $K\backslash G/K$ we denote the space of double cosets,
i.e., the quotient of $G$ with respect to the equivalence relation
$$
 k_1 gk_2\sim g,\qquad\text{where $k_1$, $k_2\in K$.} 
$$

Let a group $G$ be finite. Let $\C[G]$ be its group algebra, we denote
the product in $\C[G]$ (the convolution) as the usual product.
 We say, that a function on $G$ is {\it $K$-biinvariant}
if it is constant on double cosets $K g K$.
 Denote 
by
$$
\C[K\backslash G/K]\subset \C[G]
$$
the subalgebra consisting of $K$-biinvariant functions
(for more details, see, e.g., \cite{Bum}).

For $g\in G$, denote by $\delta_g$ the element $g$ considered as an 
element of $\C[G]$. Denote 
$$
\delta_K=\frac{1}{\#K} \sum_{k\in K}\delta_K,
$$
where the symbol $\# X$ denotes the number of elements of a finite set $X$. 
 For a double coset $\frg=KgK$,  we define
 $$\delta_\frg=\delta_K\cdot\delta_g\cdot\delta_K
=\frac{1}{\# (KgK)}\sum_{q\in KgK} \delta_q.
 $$ 


 Let $\rho$ be an irreducible representation of $G$
 in a Euclidean space $H_\rho$. Denote by $H_\rho^K\subset H_\rho$
 the subspace of $K$-fixed vectors (it can be trivial).
 Denote by $P_\rho^K$ the operator
 of orthogonal projection to $H_\rho^K$,
 $$
 P_\rho^K=\rho(\delta_K).
 $$
 For $g\in G$ we define the operator
 $$
 \wt\rho(g):H_\rho^K \to H_\rho^K
$$
by 
$$
\wt \rho(g):=P_\rho^K\rho(g)\Bigr|_{H_\rho^K}.
$$
It is easy to see that this operator depends only on the double
coset $\frg$ containing $g$, so we can write $\wt\rho^K(\frg)$. Decomposing
$H_\rho=H_\rho\oplus(H_\rho^K)^\bot$, we get
$$
\rho(\delta_\frg)=\rho(\delta_K)\,\rho(g)\,\rho(\delta_K)
=\begin{pmatrix}
\wt \rho^K(\frg)&0\\0&0
\end{pmatrix}.
$$ 
So, $\wt\rho(\frg)$ is a representation of the algebra
$\C[K\backslash G/K]$ in $H_\rho^K$.

This easily implies that $\C[K\backslash G/K]$ is isomorphic
to a direct sum
of matrix algebras,
\begin{equation}
\C[K\backslash G/K]\simeq \bigoplus_{\rho\in \wh G}
\End(H_\rho^K),
\label{eq:oplus} 
\end{equation}
where the summation is taken over the set $\wh G$ of
 all irreducible representations
of $G$ (actually we have only summands, for which
$H_\rho^K\ne 0$).
So,
$$
\dim \C[K\backslash G/K]= \sum_{\rho\in \wh G}
(\dim H_\rho^K)^2.
$$ 

\sm

Next, we define some additional simple structures
on algebras $\C[K\backslash G/K]$.
 We have a {\it trace} on $\C[G]$ defined by
$$
\tr \Bigl(\sum_{g\in G} c_g \delta_g\Bigr):= c_1,
$$
where $1$ is the unit of the group. It is easy to see
that this trace satisfies 
$$
\tr (\Phi\Psi)=\tr(\Psi\Phi).
$$
Restricting the trace to $\C[K\backslash G/ K]$
we get a trace on $\C[K\backslash G/ K]$,
$$
\tr \Bigl(\sum_{\frg\in K\backslash G/ K} a_\frg\delta_\frg \Bigr)=
\frac 1{\# K} a_K,
$$
where $a_K$ is the coefficient at $\delta_K$.



\sm

We  define an antilinear {\it involution} in $\C[G]$ by
$$
\bigl(\,\sum c_g \delta_g \,\bigr)^*:=\sum \ov c_g \delta_{g^{-1}}.
$$ 
Clearly,
$$
(\Phi+\Psi)^*=\Phi^*+\Psi^*,\quad (\Phi\Psi)^*=\Psi^*\Phi^*,
\quad \Phi^{**}=\Phi.
$$

Also, we  have a positive definite  {\it inner product}
$$
\la \Phi,\Psi\ra:=\tr (\Phi\Psi^*),
$$
Equivalently,
$$
\bigl\la \sum b_g \delta_g, \sum c_g \delta_g\bigr\ra
=\sum_{g\in G} b_g \ov c_g.
$$
So, we get the involution and the inner product on $\C[K\backslash G/K]$.

Finally, we have a homomorphism $\C[G|\to \C$ defined by
$$
\iota \Bigl(\sum c_g \delta_g\Bigr):=\sum c_g.
$$
Its restriction to $\C[K\backslash G/K]$ is given by
$$
\iota\Bigl(\sum_{\frg\in K\backslash G/ K} a_\frg\delta_\frg \Bigr)=
\sum a_\frg.
$$


\sm

These considerations%
\footnote{With some care with  traces.} can be easily extended to the case, when 
$G$ is a locally compact group and $K$ is a compact subgroup.
Now the convolution algebra $\C[K\backslash G/K]$
consists of (compactly supported) $K$-biinvariant complex-valued measures
on $G$.

\sm


{\bf \punct Some important cases.}

\sm

a) Let $G$ be a linear semisimple Lie group and $K\subset G$ the maximal 
compact subgroup.
According  Gelfand theorem  \cite{Gel},
the algebras $\C[K\backslash G/K]$ are commutative, for this reason
$\dim H_\rho^K\le 1$. The same statement holds if $G$ is a compact Lie group and $K$ is its symmetric subgroup.
 These algebras were
algebras have been extensively studied and applied since \cite{Gel} and \cite{BG}; as far as I know their nice descriptions are
not invented. 

Consider the case of rank one Lie groups.
Let $\K$ denotes the reals $\R$, complex numbers $\C$, 
or quaternions $\mathbb{H}$, let $\kappa:=\dim\K$. Consider a space
$\K^n$
 equipped with an Hermitian form with inertia indices
$(n-1,1)$. Consider the groups $G:=\U(n-1,1;\K)$
preserving these forms;
their maximal compact subgroups are $K=\U(n-1;\K)\times \U(1;\K)$.
In the standard notation, for $\K=\R$, $\C$, $\mathbb{H}$  a group 
$G=\U(n-1,1;\K)$ is respectively
\begin{equation}
G=\O(n-1,1),\quad \U(n-1,1), \quad \Sp(n-1,1).
\label{eq:ranl-one}
\end{equation}
In all cases,  convolutions of  delta-functions
are determined by  ${\vphantom{F}}_2F_1$-hypergeometric expressions.
There is a common formula for these expressions including $n$
and $\kappa$ as parameters. More precisely, 
there is a meromorphic family of associative algebras depending on two complex parameters
$n$, $\kappa$ whose elements are
functions on the half-line, and a product
$$
f_1\circ f_2(z)=\int_0^\infty \cL(x,y;n,\kappa)\, f_1(x)\,f_2(y)\,
dx\,dy
$$
 is determined by a certain hypergeometric kernel $\cL$, which  for  integer positive $n$
and $\kappa=1$, $2$, $4$ gives algebras $\C[K\backslash G/K]$ 
for the cases \eqref{eq:ranl-one} (for $n=2$ and $\kappa=8$
we get the double coset algebra for one of real forms 
of the exceptional Lie group $F_4$, the number 8 is the dimension of the octaves). See \cite{FJK},  \cite{Koo}, Sect 7.
\hfill $\boxtimes$

\sm

2) {\it Hecke algebras}, Iwahori \cite{Iwa}. Consider a group $G:=\GL(n;\F_q)$
 over a finite field $\F_q$ with $q$ elements,
let $K$ be the group of upper-triangular matrices. It is easy to see that 
each
double coset $K\backslash G/K$ contains a unique matrix-permutation.
Denote by $T_i$ the double coset containing the matrix of 
the transposition $\bigl(i(i+1)\bigr)$. Then $\C[K\backslash G/K]$
is the algebra with generators $T_i$ and relations
$$
(T_i-q)(T_i+1)=0,\quad
T_i T_{i+1}T_i=T_{i+1} T_i T_{i+1},\quad
T_i T_j=T_j T_i \quad\text{if $|i-j|\ge 2$.}
$$ 
This algebra makes sense for all $q\in \C$ 
and always has dimension $n!$. For $q=1$
we get the group algebra of the symmetric group $S_n$
(the first relation gives $T_i^2=1$, therefore $(T_i T_{i+1})^3=1$,
and we get relations for $S_n$ generated by transpositions). See,
e.g., \cite{DG}, \cite{Bum}, Sect.~48. This algebra can live by its own life
without the groups $\GL(n;\F_q)$ and $S_n$.

If $G:=\GL(n;\F_q)$ and $K$ is the group of strictly upper triangular
matrices,
then the algebra of double cosets admits a nice description
\cite{Yok}, but it does not admit an interpolation in the parameter $q$.
\hfill $\boxtimes$

\sm

3) {\it The  affine Hecke algebra}, Iwahori, Matsumoto \cite{IwaMats}.
Let $\Q_p$ be $p$-adic field, $\Z_p$ be $p$-adic integers.
 Now $G$ is the general Lie group $\GL(n;\Q_p)$
over a $p$-adic field, $K$ is the group of matrices
whose entries over the diagonal $\in \Z_p$, on the diagonal
$\in\Z_p\setminus p\Z_p$, and under the diagonal $\in p\Z_p$
(the Iwahori subgroup). Then $\C[K\backslash G/K]$ has a nice description and admits an interpolation with respect to $p$.
Again, this algebra lives by its own life independently on groups
over locally compact fields, see \cite{Mac1}. On the variant
$G=\GL(n,\Q_p)$, $K=\GL(n,\Z_p)$, see \cite{Mac}, Chapter V.
\hfill $\boxtimes$

\sm

Algebras of types 1)-3) have some relatives, but in any case
a  list of known  algebras
of double cosets with simple nice descriptions is short.
More general algebras of double cosets were topics
of numerous efforts, see, e.g., \cite{FH}, \cite{IK}, \cite{Mel}, \cite{Tou}, \cite{KR}.

\sm

For infinite-dimensional groups $G$
quite often there appear natural associative multiplications on 
sets $K\backslash G/K$, such semigroups act in spaces of $K$-fixed
vectors of unitary representations of $G$. These semigroups admit
transparent descriptions, see, e.g.,
 \cite{Olsh1}, \cite{Olsh}, \cite{Ner-bist},
  \cite{Ner-book}, Chapter VIII, Sect.IX.3-4, \cite{Ner-umn}, \cite{Ner-coll}, \cite{Ner-finite}.
 There arises a question about descent to finite-dimensional level.   The author made several attempts in this direction, see, e.g.,
 \cite{Ner-zametki}, \cite{Ner-ivanov}. 

\sm

 {\bf \punct The purpose of the paper.} Fix $\alpha>0$, $n\ge \alpha$.
 Consider a group $G=S_{\alpha+n}$.
 For algebras of double cosets 
 $\bbO[\alpha;n]:=
\C[S_n\backslash S_{\alpha+n}/S_n]
 $,
 we obtain a   description in the terms of generators
 and relations. We also construct a family $\bbO[\alpha;\nu]$
 of algebras depending on a complex parameter $\nu$
 interpolating algebras $\C[S_n\backslash S_{\alpha+n}/S_n]$.





\sm

{\bf \punct The structure of the paper.}
We formulate our statements in Sect.~2, proofs are contained in Sect.~3.














\section{\bf The statements}

\COUNTERS



 We denote by $S_m$ the symmetric group
of order $m$.   We also realize symmetric groups as group of matrices,
 composed of 0 and 1 having precisely one unit in each column and each
 row. Denote by $(ij)\in S_m$ the transposition of $i$ and $j$.

\sm

{\bf\punct  Double cosets $S_n\backslash S_{\alpha+n}/S_n $.%
\label{ss:Pi}}
Let $S_{\alpha+n}$ denote the group
of permutations of the set 
$\{1, \dots, \alpha;
\alpha+1, \dots, \alpha+n\}$.
{\it Below $\alpha$ is fixed and $n$ varies.}
 Let $S_\alpha$ be the group of permutations of 
 the set $\{1, \dots, \alpha\}$, and $S_n$
 be the group of permutations  of $\{\alpha+1, \dots, \alpha+n\}$.


Denote by $\Pi_\alpha$ the set of all
 matrices of order $\alpha$
consisting of 0 and 1 and having $\le 1$  units in each column.
 Such matrices can be regarded
 as partial bijections of the set 1, 2, \dots, $\alpha$.
 The number of elements of $\Pi_\alpha$ is%
 \footnote{In the formula, ${\vphantom{F}}_1F_1$ is a confluent hypergeometric function, this does not matter.}
 \begin{equation}
 \# \Pi_\alpha=
 \sum_{r=0}^\alpha\frac{(\alpha!)^2}{(\alpha-r)!\,(r!)^2}
 = \alpha!\, {\vphantom{F}}_1F_1[-\alpha;1;-1].
 \label{eq:number-Pi}
 \end{equation}


Let $i_1<i_2<\dots < i_k\le \alpha$.
We denote by
\begin{equation}
T_{i_1,\dots,i_k}
\label{eq:idempotent}
\end{equation}
the diagonal element of $\Pi_\alpha$ whose $i_1$, \dots, $i_k$-th
 entries are 0 and the remaining diagonal entries are units.
 Such  elements are idempotents in $\Pi_\alpha$.


For $Q\in S_{n+\alpha}$ we denote by $[Q]_\alpha$ 
its left upper corner of size $\alpha$.


The following important  statement (\cite{Olsh}) 
is obvious.

\begin{theorem}
{\rm a)} The map $Q\mapsto [Q]_\alpha$
is constant on double cosets $S_n\cdot g\cdot S_n$
and is an injective map 
\begin{equation}
S_n\backslash S_{\alpha+n}/S_n\to \Pi_\alpha.
\end{equation}

\sm

{\rm b)} If $n\ge \alpha$, when this map is a bijection.
If $n<\alpha$, then the image consists of elements
of $\Pi_\alpha$ of rank $\ge\alpha-n$.
\end{theorem}



The number of elements of a double coset corresponding to an element
 $\sigma\in \Pi_\alpha$ of rank $\alpha-r$ 
is
\begin{equation}
n!\,(n-r)!
\label{eq:preimage}
\end{equation}

\begin{proposition}
\label{pr:isomorphic}
For fixed $\alpha$ and
 $n\ge\alpha$ all algebras $\C[S_n\backslash S_{\alpha+n}/S_n]$
 are\footnote{Noncanonically.} isomorphic.
\end{proposition}



\sm

{\bf \punct Algebras $\bbO[\alpha,\nu]$.}
Let $\alpha\ge 0$ be integer. Let $\nu\in\C$.
 Consider an associative algebra $\bbO[\alpha,\nu]$
with generators 
$$
\text{$A(g)$, where $g$ ranges in $S_\alpha$,
and $\Theta_1$, \dots, $\Theta_\alpha$}
$$
and the relations
\begin{align}
A(g_1)A(g_2)&=A(g_1 g_2);
\label{eq:rel1}
\\
A(g)\Theta_i A(g^{-1})&=\Theta_{g(i)};
\label{eq:rel2}
\\
\Theta_j^2&=(\nu-1)\Theta_j+ \nu A(1);
\label{eq:rel3}
\\
\Theta_j \Theta_i-\Theta_i \Theta_j&=A((ij))\,(\Theta_j-\Theta_i);
\label{eq:rel4}
\\
\bigl(A((ij))-A(1)\bigr)\, \Theta_j (\Theta_i+A(1))&=0.
\label{eq:rel5}
\end{align}


\sm

{\sc Remark.} So $A(1)$ is a unit of the algebra, 
and all elements $A(g)$ are invertible, $A(g)^{-1}=A(g^{-1})$. 
\hfill $\boxtimes$

\begin{theorem}
\label{th:homomorphism}
{\rm a)} $\dim  \bbO[\alpha,\nu]=\#\Pi_\alpha$.

\sm 

{\rm b)} Let $n\ge 0$ be integer. 
Assign for any $g\in S_\alpha$ the element
$$
 a(g):=
\frac1{n!}\sum_{\sigma\in S_n}\delta_{g\times \sigma}
\in \C[S_n\backslash S_{\alpha+n}/S_n].
$$ 
 For any $i\le \alpha$ denote
 $$
 \theta_i:=\frac{1}{n!}\sum_{h\in K(i(\alpha+1))K}
 \delta_h\in \C[S_n\backslash S_{\alpha+n}/S_n].
 $$
 Then the map
 $$
 \Theta_i\mapsto \theta_i, \qquad A(g)\mapsto a(g) 
 $$
 determines a homomorphism $\bbO[\alpha;n]\to \C[S_n\backslash S_{\alpha+n}/S_n]$.

 \sm

 {\rm c)} If $n\ge \alpha$, then this homomorphism is an isomorphism.
 If $0\le n<\alpha$, then it is surjective.

\sm  

 {\rm d)} For all $\nu\in \C$ except finite collection
 of values, the algebras $\bbO[\alpha;\nu]$ are%
 \footnote{Noncanonically.}  isomorphic
 (and are direct sums of matrix algebras). 
 \end{theorem}

{\bf\punct A basis in $\bbO[\alpha;\nu]$.}
Clearly, any element of our algebra can be represented 
as a sum of  {\it monomials}
$$
A(g)\,\Theta_{i_1}\dots\Theta_{i_k},
$$
where $i_1$, \dots, $i_k$ are pairwise distinct.
We define a {\it $\Theta$-degree} of a monomial as
$$
\deg_\Theta\bigl(A(g)\,\Theta_{i_1}\dots\Theta_{i_k}\bigr)=k.
$$
We define the $\Theta$-degree of a polynomial as the maximum of degrees of monomials
and the $\Theta$-degree of an element $H\in \bbO[\alpha,\nu]$
as the minimum of $\Theta$-degrees of polynomials representing $H$.
Clearly,
$$
\deg_\Theta(H_1 H_2)\le \deg_\Theta(H_1)+\deg_\Theta(H_2).
$$





\begin{lemma}
\label{l:A-1}
Let $h\in S_\alpha$ be a permutation supported by the set
$\{i_1,\dots,i_k\}$, where all $i_m$ are distinct. Then
$$\deg_\Theta\Bigl(\bigl((A(h)-A(1)\bigr)\,
\Theta_{i_1}\dots \Theta_{i_k}\Bigr)<k.$$
\end{lemma}

\begin{theorem}
\label{th:basis}
The following elements form a basis in the algebra
$\bbO[\alpha;\nu]$:
\begin{equation}
A(g)\, \Theta_{i_1}\dots \Theta_{i_k},
\label{eq:basis}
\end{equation}
where

\sm

--- $i_1<i_2<\dots<i_k$;

\sm

--- $g(i_1)<g(i_2)<\dots<g(i_k)$.
\end{theorem}

{\bf \punct The trace.}
We define a trace on $\bbO[\alpha;\nu]$ as a linear functional
$\Tr:\bbO[\alpha;\nu]\to\C$
that is defined on basis elements \eqref{eq:basis}
by
$$
\Tr\bigl(A(1))=1
$$
and $\Tr(A(g)\,\Theta_{i_1}\dots \Theta_{i_k})=0$
for all other cases.

\begin{proposition}
\label{pr:trace}
\begin{equation}
\Tr(H_1 H_2)=\Tr(H_2 H_1)
\end{equation}
\end{proposition}

{\bf \punct The involution.} Now let $\nu\in \R$.
Consider the antilinear involution of
$\bbO[\alpha;\nu]$ 
defined by
$$
A(g)^*=A(g^{-1}),\qquad \Theta_j^*=\Theta_j
$$
We define an Hermitian form on $\bbO[\alpha;\nu]$
by 
$$
\la H_1,H_2\ra:=\Tr H_1 H_2^*.
$$

\begin{proposition}
\label{pr:positivity}
For sufficiently large $\nu\in \R$ this form is positive definite.
\end{proposition}

{\bf \punct The homomorphism $\boldsymbol{I}$.}
Clearly, we have a homomorphism 
$$I:\bbO[\alpha;\nu]\to\C$$
defined on generators by
$$
I:\,A(g)\mapsto 1,\qquad \Theta_j\mapsto \nu.
$$
By \eqref{eq:preimage}, for $\nu=n$ it coincides 
with the homomorphism $\iota:\bbO[\alpha;n]\to\C$.

\sm

{\bf \punct The limit as $\boldsymbol{\nu\to\infty}$.}
 Olshanski \cite{Olsh} (1985) considered  the algebras $\C[S_n\backslash S_{\alpha+n}/S_n]$ and showed that at the limit $n\to\infty$
there appears a multiplication on the set $S_n\backslash S_{\alpha+n}/S_n$. This multiplication is a product of matrices in $\Pi_\alpha$.
 Here we show how this follows from our relations
\eqref{eq:rel1}--\eqref{eq:rel5}.

Let us modify the generators of $\bbO[\alpha;\nu]$ assuming 
$$
\Theta'_j=\frac 1\nu \Theta_j
$$
(and $A(g)$ remain the same).
Then
\begin{align*}
%A(g_1)A(g_2)&=A(g_1 g_2);
%\label{eq:rel1}
%\\
A(g)\Theta'_i A(g^{-1})&=\Theta'_{g(i)};
%\label{eq:rel2}
\\
(\Theta'_j)^2&=\bigl(1-\tfrac 1\nu\bigl)\Theta'_j+ \tfrac 1\nu A(1);
%\label{eq:rel3}
\\
\Theta'_j \Theta'_i-\Theta'_i \Theta'_j&=\tfrac 1\nu
A((ij))(\Theta'_j-\Theta'_i);
%\label{eq:rel4}
\\
\bigl(A((ij))-A(1)\bigr) \Theta'_j \bigl(\Theta'_i+\tfrac 1\nu\bigr)&=0.
%\label{eq:rel5}
\end{align*}
Passing to the limit as $\nu\to\infty$, we get
the algebra $\bbO[\alpha]$ with the same generators and relations
\begin{align*}
A(g_1)A(g_2)&=A(g_1 g_2);
%\label{eq:rel1}
\\
A(g)\Theta'_i A(g^{-1})&=\Theta'_{g(i)};
%\label{eq:rel2}
\\
(\Theta'_j)^2&=\Theta'_j;
%\label{eq:rel3}
\\
\Theta'_j \Theta'_i&=\Theta'_i \Theta'_j;
%\label{eq:rel4}
\\
A((ij))\, \Theta'_j \Theta'_i&=\Theta'_j \Theta'_i.
%\label{eq:rel5}
\end{align*}
We see that elements of the basis \eqref{eq:basis}
form a semigroup with respect of multiplication.
We observe the following statement:

\begin{theorem}
The limit algebra $\bbO[\alpha]$ is the semigroup
algebra $\C[\Pi_\alpha]$.
\end{theorem}

Indeed, the isomorphism is defined by
$$
g T_{i_1, \dots, i_k}\mapsto
A(g)\, \Theta_{i_1}\dots \Theta_{i_k},
$$
where $T_{i_1, \dots, i_k}$ was defined above
\eqref{eq:idempotent}

\begin{proposition}
\label{pr:limit}
The algebra $\bbO[\alpha]$ is%
\footnote{Noncanonically.} isomorphic to the algebras
$\bbO[\alpha;n]$ for $n\ge \alpha$.
\end{proposition}

