\section{Formulae}
\label{sec:C}
We collect formulae concerning the Laplace transform
and loop integrals.


\subsection{Laplace transform}

\begin{align}
&\int_0^{\infty} \dd z \, z^{-v-1/2} \frac{1}{P^2+z}
=\frac{\pi}{\cos(\pi v)} \frac{1}{(P^2)^{v+1/2}} , \non
&\int_0^{\infty} \dd z \, z^{-v-1/2} \frac{1}{(P^2+z)^2}
= \frac{1}{2} (1+2v)\frac{\pi}{\cos(\pi v)} \frac{1}{(P^2)^{v+3/2}} . \label{Laplace}
%&\int_0^{\infty} d m^2 (m^2)^{-v-1} \frac{m}{(P^2+m^2)^3}
%= \frac{1}{8} (1+2v)(3+2v)\frac{\pi}{\cos(\pi v)} \frac{1}{(P^2)^{v+5/2}} .
\end{align}
$P$ denotes a linear combination of (dimensionless) loop momenta.


\subsection{Loop integrals}

\begin{align}
%first eq
&\int_p \frac{1}{(p^2)^a} \rme^{-s p^2}=\frac{1}{(4 \pi)^{d/2}} \frac{\Gamma(d/2-a)}{\Gamma(d/2)} s^{a-d/2} \quad{} \mbox{\cite{Luscher:2010iy}} \label{formulazero}  , \\
%second eq
&\int_{p,k} \frac{\rme^{-s p^2-u k^2-v(k-p)^2}}{(k^2)^a}=\frac{1}{(4 \pi)^d} \frac{\Gamma(d/2-a)}{\Gamma(d/2)} \frac{1}{(s+v)^a} \frac{1}{(uv+su+sv)^{d/2-a}} , \label{formulaone} \\
%third eq
& \int_{p,k} \frac{1}{(k^2)^a (p^2)^b} \rme^{-s p^2-u k^2-v (k-p)^2} \non
&=\frac{1}{(4 \pi)^d} \frac{\Gamma(d/2-b)}{\Gamma(d/2)\Gamma(a)} \frac{1}{(u+v)^b} \frac{1}{(uv+su+sv)^{d/2-b}} \non
&\quad{} \times \bigg[
\left( \frac{uv+su+sv}{s+v} \right)^a \frac{\Gamma(a) \Gamma(d/2-a-b)}{\Gamma(d/2-b)}  {}_2F_1(a;b;1+a+b-d/2;\frac{uv+su+sv}{(s+v)(u+v)}) \non
&\qquad{}\quad{} +\frac{1}{\Gamma(b)} (u+v)^a \left(\frac{(s+v)(u+v)}{uv+su+sv} \right)^{b-d/2} \Gamma(a+b-d/2) \Gamma(d/2-a) \non
&\qquad{}\qquad{} \times {}_2F_1(\frac{d}{2}-a,\frac{d}{2}-b;\frac{d}{2}+1-a-b; \frac{uv+su+sv}{(s+v)(u+v)}) \bigg] , \label{formulatwo}\\
%fourth eq
&\int_{k,p} \frac{1}{(k^2)^a [xp^2+(1-x) (k-p)^2]^b} \rme^{-sp^2-uk^2-v(k-p)^2}   \non
&=\frac{1}{(4\pi)^d}
\frac{\Gamma(d/2-a)}{\Gamma(b)\Gamma(d/2)} \non
&\quad{} \times \int_0^{\infty} \dd \beta \beta^{b-1}
\frac{1}{(s+v+\beta)^a} \frac{1}{[u(v+\beta(1-x))+(s+\beta x)u+(s+\beta x) (v+\beta(1-x))]^{d/2-a}}  . \label{formulatwoFeynman}
\end{align}
In the last equation, $x$ corresponds to a Fyenmal integral parameter ($0 \leq x \leq 1$).
${}_2F_1(a,b;c;z)$ denotes the hypergeometric function, which is defined by
\be
{}_2F_1(a,b;c;z) \equiv \sum_{n=0}^{\infty} \frac{(a)_n (b)_n}{(c)_n} \frac{z^n}{n!}
\ee
for $|z|<1$ and a non-positive integer $c$. $(...)_n$ is the Pochhammer symbol $(a)_n=\Gamma(a+n)/\Gamma(a)$.
In our calculation, we often use a formula to
change the $z$ variable as $z \to 1-z$,
\begin{align}
{}_2F_1(a,b;c;z)
&=\frac{\Gamma(c)\Gamma(c-a-b)}{\Gamma(c-a) \Gamma(c-b)} {}_2F_1(a,b;a+b+1-c;1-z) \non
&\quad{}+\frac{\Gamma(c) \Gamma(a+b-c)}{\Gamma(a) \Gamma(b)} (1-z)^{c-a-b}  {}_2F_1(c-a,c-b;1+c-a-b;1-z) \label{rewritehyp}
\end{align}
when the alternative expression is found more convenient
to understand the structure of singularities.

