\subsection{Open-loop and Closed-loop Frequency Domain Analysis}
\begin{theorem}
    \label{theorem reset hosidf}
    \cite[Theorem 3.1]{saikumar2021loop},
    Considering $e_r(t)=\sin{(\omega t)}$ as the input of the reset element, then for its output, we have %\cite{nuij2006higher}
    \begin{equation}
        u_r(t)=\sum^{\infty}_{n=1}{|H_n(\omega)|\sin{\left(n\omega t+\angle{H_n(\omega)}\right)}},
    \end{equation}
     where $H_n(\omega)$ is the HOSIDF of the reset element in \eqref{eq.SS reset} as follows
    \begin{equation} 
    \label{eq reset HOSIDF}
    \resizebox{1\hsize}{!}{
		$H_n(\omega) = \begin{cases}
            C_r\left(j\omega I-A_r\right)^{-1}\left(I+j\Theta_D(\omega)\right)B_r+D_r,  \quad \quad \mathrm{for}\;\; n=1,\\
            C_r\left(jn\omega I-A_r\right)^{-1}j\Theta_D(\omega)B_r,  \qquad \qquad \hspace{9mm} \mathrm{for}\;\;\mathrm{odd}\;\; n\geq2,\\
            0, \hspace{66mm} \mathrm{for}\;\;\mathrm{even}\;\; n\geq2,
		\end{cases}$
  }
	\end{equation}
 with
 \begin{equation}
 \begin{split}
&\Lambda(\omega)=\omega^2 I+A_{r}^2, \quad \Delta(\omega)=I+e^{\frac{\pi}{\omega}A_r},  \\
%&\Delta(\omega)=I+e^{\frac{\pi}{\omega}A_r} \\ 
&\Delta_r(\omega)=I+A_\rho e^{\frac{\pi}{\omega}A_r}, \quad \Gamma_r(\omega)=\Delta_r^{-1}(\omega)A_\rho\Delta(\omega)\Lambda^{-1}(\omega),\\ %&\Gamma_r(\omega)=\Delta_r^{-1}(\omega)A_\rho\Delta(\omega)\Lambda^{-1}(\omega)\\
     &\Theta_\mathrm{D}(\omega)=-\frac{2\omega^2}{\pi}\Delta(\omega)\left[\Gamma_r(\omega)-\Lambda^{-1}(\omega)\right].
     \end{split}
 \end{equation}
\end{theorem}
From Theorem \ref{theorem reset hosidf} and \cite[Theorem 2]{10473227}, the open-loop HOSIDF of the system in Fig. \ref{fig:Block diagram cl} is as follows:
\begin{equation}
    \label{openloop HOSIDF}
    \mathcal{L}_n(\omega)=G(jn\omega)C_2(jn\omega)H_n(\omega)C_1(j\omega)e^{j(n-1)\angle C_1(j\omega)}.
\end{equation}

Despite LTI systems, there is no direct link between the open-loop and closed-loop frequency domain response for nonlinear controllers, especially in the case of the reset control system. Therefore, predicting the actual closed-loop performance is desirable using only frequency domain analysis. In Theorem \ref{Sn theorem}, a frequency domain-based performance prediction for RCSs is presented (\cite{saikumar2021loop}) under the following assumption.
\begin{assumption}
\label{Assumption two reset}
    We assume that only the first-order harmonic of $e_r$ contributes to resets, as in the closed-loop, it consists of a fundamental harmonic with a frequency of $\omega$, along with higher-order harmonics. Additionally, the RCS is input-to-state convergent (see \cite{hosseini2025frequency} for frequency domain stability analysis).
\end{assumption}
\begin{theorem}
    \label{Sn theorem}
    \cite[Theorem 4.1]{saikumar2021loop}
    Considering $r(t)=\sin{(\omega t)}$ and that Assumption \ref{Assumption two reset} holds, the closed-loop steady-state error $e_{ss}(t)$ can be written as 
    \begin{equation}
    \label{eq ess}
        e_{ss}(t)=\sum_{n=1}^{\infty}e_n(t),
    \end{equation}
    where
    \begin{equation}
    \label{eq en}
        e_n(t)=|S_n(\omega)|\sin{(n\omega t+\angle{S_n(\omega)})},
    \end{equation}
    with higher-order sensitivity function $S_n(\omega)$ as
    \begin{equation}
        \label{eq Sn}
        \resizebox{1\hsize}{!}{
        $S_n(\omega)=\begin{cases}
        \displaystyle
            \frac{1}{1+\mathcal{L}_1(\omega)},  \hspace{49.5mm} &\mathrm{for}\;\; n=1, \vspace{2mm}\\
            \displaystyle
            -\mathcal{L}_n(\omega)S_\mathrm{bl}(jn\omega)\left(|S_1(\omega)|e^{jn\angle{S_1{(\omega)}}}\right),  \hspace{11mm} &\mathrm{for}\;\;\mathrm{odd}\;\; n\geq2,\\
            0, \hspace{65.5mm} &\mathrm{for}\;\;\mathrm{even}\;\; n\geq2,
		\end{cases}$
  }
    \end{equation}
    where $S_\mathrm{bl}(jn\omega)=\frac{1}{1+L_\mathrm{bl}(jn\omega)}$ which $L_\mathrm{bl}(j\omega)$ is the base linear transfer function of the open-loop.
\end{theorem}
\section{Case study}
\label{sec: case study}
In this paper, we address the vibration and disturbance rejection problem for a precision positioning stage (see Fig. \ref{fig: spyder stage}). The plant is modeled using its measured frequency response function, which can be approximated by the following transfer function:
\begin{equation}
\label{eq: Plant transfer function}
G(s)=\frac{9836 e^{-0.00027}}{s^2+8.737s+7376}.
\end{equation}
\begin{figure}
	\centering
 	\includegraphics[scale=0.30,trim=0 0 0 0,clip]{Figures/spyder_setup.eps}
	\caption{Planar precision positioning ‘Spider’ stage with voice coil actuator denoted
as A1, controlling the mass indicated as M1 and
constrained by leaf flexure.}
	\label{fig: spyder stage}
\end{figure}
In this study, we use the above model of the actual system to be able to investigate its behavior under varying conditions, including the presence and absence of inputs such as noise and disturbances. A PID controller is designed to achieve a 30-degree phase margin while ensuring high low-frequency loop gain for improved disturbance rejection. However, due to time delay, the controller's ability to increase low-frequency gain is limited, as doing so requires either widening the bandwidth or raising the integral frequency, both of which reduce phase margin.

To overcome the mentioned limitations of PID controllers, we use the reset element to design a CgLp element (\cite{saikumar2019constant}) that provides phase lead around the frequency range of interest without affecting the gain behavior. We consider,
\begin{equation}
\label{eq CgLp(w)}
C_\mathrm{CgLp}= \mathcal{R}\, .\, C_\mathrm{lead},
\end{equation}
where
\begin{equation}
    \label{eq lead CgLp}
    C_\mathrm{lead}(s)=\frac{1+\frac{s}{\omega_r}}{1+\frac{s}{\omega_f}},
\end{equation}
with $\omega_f>>\omega_r$ (in this study $\omega_f=20\omega_r$).
The lead element ($C_\mathrm{lead}$) is placed after the reset component to prevent the amplification of noise in the reset action signal \( e_r(t) \) when the error signal \( e(t) \) is noisy. In many applications, the lead element is positioned either after the reset element or in parallel to it, helping to mitigate noise amplification in the reset signal \cite{10473227}.

The reset element $\mathcal{R}$ is designed such that its gain cancels the gain effect of the lead filter while providing less phase lag in its SIDF ($H_1(\omega)$) compared to the phase of $C_\mathrm{lead}^{-1}(s)$. Considering $\mathcal{R}$ as GFORE element ($A_r=-\omega_\alpha$, $B_r=1$, $C_r=\omega_\alpha$, $D_1=0$, $-1<A_\rho<1$) with the base linear transfer function 
\begin{equation}
    \label{eq: base linear GFORE}
    R(s)=\frac{1}{1+\frac{s}{\omega_{\alpha}}},
\end{equation}
where $\omega_{\alpha}$ is the corner frequency of the base linear transfer function of the GFORE element. To have the same magnitude of describing function as a linear low-pass filter $\left(1+\frac{s}{\omega_r}\right)^{-1}$ in both high frequencies ($\omega\rightarrow \infty$) and low frequencies ($\omega\rightarrow 0$), we set
\begin{equation}
    \label{eq corner frequency}
    \omega_\alpha=\frac{\omega_r}{\sqrt{1+\Theta_{\mathrm{D},\infty}^2}},
\end{equation}
where $\Theta_{D,\infty} := \lim_{\omega \to \infty} \Theta_\mathrm{D}(\omega)=\frac{4(1-A_\rho)}{\pi(1+A_\rho)}$. See \cite[Section 3]{van2024nonlinear} for more information.

Having the plant in \eqref{eq: Plant transfer function}, we compare two controllers as 
\begin{equation}
\label{C-linear}
    C_\mathrm{L}=C_\mathrm{PID}\, .\, \frac{1}{1+\frac{s}{\omega_{f}}},
\end{equation}
and
\begin{equation}
    C_\mathrm{NL}=C_\mathrm{PID}\, .\, C_\mathrm{CgLp},
\end{equation}
where $C_\mathrm{PID}$ is defined as follows
\begin{equation}
	\label{PID1}
	C_{\text{PID}}(s)=k_p\bigg(1+\frac{\omega_i}{s}\bigg)\bigg(\frac{1+\frac{s}{\omega_d}}{1+\frac{s}{\omega_t}}\bigg),
\end{equation}
where $k_p \in \mathbb{R}$ represents the PID gain, ensuring zero dB gain at crossover frequency $\omega_c$ (defined as bandwidth), $\omega_i=\omega_c/10$ is the frequency at which integral action is stopped, differentiating action is started at $\omega_d=\omega_c/3$ and terminated at $\omega_t=3\omega_c$.
