Intuitively, \textsc{\acronym} starts with a coarse partitioning of~$S$ and iteratively refines individual blocks.  
Through this sequence of refinements, \acronym\ yields a rooted tree whose nodes store even finer blocks, deriving a
\emph{hierarchy tree}.

\begin{definition}[Hierarchy tree]\label{def:tree}
A rooted tree $\mathcal{T}=(\mathcal{N},E)$ is a \emph{hierarchy tree} for $\mathcal{M}$ if 
(i) the root $r$ corresponds to the entire state space $S$;
(ii) every node $v\in \mathcal{N}$ corresponds to a block $B_v\subseteq S$; and
(iii) the blocks corresponding to the children of $v$ form a partitioning of $B_v$.
We denote the distance of $v$ from the root with 
% $\mathrm{depth}(v)$.
$\mathrm{v.depth}$.
\end{definition}

\begin{algorithm}[tb]
\caption{\textsc{SHARP} procedure}
\label{alg:HierarchicalRefinement}
\small
\renewcommand{\algorithmicindent}{2mm}
\begin{algorithmic}[1]
\Require MDP $\mathcal{M}$;
%$=(S,A,\delta)$; 
objective $\phi$ where $\phi \in \{\PP_{\mathsf{opt}}[\mathsf{F}\,G], \RR_{\mathsf{opt}}[\mathsf{F}\,G]\}$ with $\mathsf{opt} \in \{\min,\max\}$; goal states $G \subseteq S$; reward function $R$ (if $\phi$ is a reward objective); partition sizes $(N_x,N_y)$; maximum depth $D$; refinement threshold $\theta$; $\mathit{maxIters}$; convergence threshold $\varepsilon$.
\Ensure Value vector $V$ and memoryless policy $\sigma$.

\Procedure{SHARP}{$\mathcal{M}$, $\phi$, $G$, $R$, $(N_x,N_y)$, $D$, $\theta$, $\mathit{maxIters}$, $\varepsilon$}
    \Statex \(\triangleright\) \textbf{1. Create \& partition the root}
    \State $\text{new}\ \texttt{rootNode};\  \texttt{rootNode.states} \gets S$; $i=0$
    \State \texttt{rootNode.children} $\!\!\gets\!\!$ \Call{Partition}{$\texttt{rootNode}$, $N_x$, $N_y$}
    % \State $\mathit{mode} \gets \text{extractOptDirection}(\phi)$ \Comment{Extract $\mathsf{opt}$ from $\phi$}

    \Statex \(\triangleright\) \textbf{2. Initial refinement of children}
    \ForAll{$c$ \textbf{ in } $\texttt{rootNode.children}$}
       \State \Call{RefineNode}{$c$, $D$, $\theta, R, \phi$}
       \Comment Sect.\,\ref{subsec:adapt-refine}, Algorithm~\ref{alg:RefineNode}
    \EndFor

    \Statex \(\triangleright\) \textbf{3. Iterative solve/propagate until convergence or \emph{maxIters}}
    % \For{$i \gets 1$ to $\mathit{maxIters}$}
    \While{$i < \mathit{maxIters} \,\land\, $ \Call{!Converged}{\texttt{rootNode}, $\varepsilon$}}
        \State \Call{SolveLeaves}{$\texttt{rootNode}$, $R$, 
        $\phi$}
        %\Comment \emph{sub‐MDPs at leaves}
        \State $rootNode.values \gets $\Call{PropagateAllUp}{$\texttt{rootNode}$}
        \Comment Sect.\,\ref{subsec:value-prop}%\emph{Merge}% bottom‐up}

        \Statex \hspace{4mm}\(\triangleright\) \textbf{Check for further refinement}

        \State \texttt{leaves} $\gets $ \Call{SelectLeavesForRefinement}{$\texttt{rootNode}$}
           \ForAll{$l$ \textbf{ in } $\texttt{leaves}$}
              \State \Call{RefineNode}{$l$, $D$, $\theta, R, \phi$}
              \Comment Sect.\,\ref{subsec:adapt-refine}, Algorithm~\ref{alg:RefineNode}

           \EndFor

  %  \State $i$++
   \State $i \gets i + 1$
    \EndWhile


    \State \textbf{return } $\bigl(\texttt{rootNode.values},\; \texttt{rootNode.$\sigma$}\bigr)$
\EndProcedure

\Statex

\Procedure{SolveLeaves}{$v, R, \phi$}
   \If{$v.\mathrm{children} = \emptyset$} \Comment \emph{leaf partition nodes}
      \Statex \hspace{4mm}\(\triangleright\) Local sub-MDP policy synthesis (Sect.~\ref{subsec:local-submdp})
      \State $v.values, v.\sigma \gets $\Call{SolveSubMDP}{$v, v.\mathrm{parent}, R, \phi$}
      % \Comment see Sect.\,\ref{subsec:local-submdp}
   \Else
      \ForAll{$c$ \textbf{ in } $\texttt{v.children}$}
         \State \Call{SolveLeaves}{$c, R, \phi$}
      \EndFor
   \EndIf
\EndProcedure
\end{algorithmic}
\end{algorithm}


