Let us now construct  the fuchsian monodromy representation of $\pi_1(\Ccal, \h{v})$  starting from two points of the spaces (\ref{pieces}) and (\ref{pi1}) satisfying the constraint (\ref{LL}) i.e. 
the following construction gives the   map 
\be
F:  \Ht\times \Hh \Big|_{\h{\Lambda}=\t{\Lambda}^{-1}} \to V_g\;.
\la{mapF}
\ee

\begin{prop}\label{fact}


    Consider a set of matrices representing a point of  $\Ht $ and a set of matrices representing a point of  $ \Hh$ such that  $\h{\Lambda}=\t{\Lambda}^{-1}$.
    % Choose some sets of matrices $\h{M}_\gamma$, $\t{M}_\g$, $C_1$ and $C_2$ 
    % with $ \Lambda=\mathrm{diag}(\lambda_{\gamma}, \lambda_{\gamma}^{-1})$. 

    Then the following set of $SL(2)$ matrices 
    %$ \{\alpha_i, \beta_i\}_{i=1,...,g} $ of $ \Ccal$ based at $v_2$ given by:
    $$
           M_{\alpha_i} = \Chh \Ctt^{-1} M_{\t{\alpha_i}} \Ctt \Chh^{-1} \;,\hskip0.6cm M_{\beta_i} = \Chh \Ctt^{-1}  M_{\t{\beta_i}} \Ctt \Chh^{-1}, \quad i =1,...,g_1 \;,
           $$
        \begin{equation} \label{monC}     
            M_{\alpha_{i+g_1}} = M_{\h{\alpha_i}} \;,\hskip0.6cm  M_{\beta_{i+g_1}}=M_{\h{\beta_i}}, \quad i=1,...,g_2
    \end{equation}
    defines a point of $V_g$.
\end{prop}
\begin{proof} 
From the definitions (\ref{pieces}) of $ \t{\Hcal}$ and $ \h{\Hcal}$ one has
\begin{equation} \label{splitlambda}
    \begin{split}
        & \t{\Lambda} = \t{C}^{-1} \left(\prod_{i=1}^{\t{g}} \left[ M_{\t{\alpha_i}}, M_{\t{\beta_i}} \right] \right)^{-1} \t{C} \\
        & \h \Lambda = \h{C}^{-1} \left(\prod_{i=1}^{\h{g}} \left[ M_{\h{\alpha_i}}, M_{\h{\beta_i}} \right] \right) \h{C}\;.
    \end{split}
\end{equation}
    Imposing $ \t{\Lambda} = \h{\Lambda}^{-1} $ we get
    \begin{equation}\label{com}
        \h{C} \t{C}^{-1} \left(\prod_{i=1}^{\t{g}} \left[ M_{\t{\alpha_i}}, M_{\t\beta_i} \right] \right) \t{C} \h{C}^{-1} \left( \prod_{i=1}^{\h{g}} \left[M_{\h{\alpha_i}}, M_{\h{\beta_i}} \right] \right)=\mathbb{I}_2.
    \end{equation}
    Defining $ M_{\alpha_i} = \h{C} \t{C}^{-1} M_{\t{\alpha_i}} \t{C} \h{C}^{-1} $ and $  M_{\beta_i} = \h{C} \t{C}^{-1}  M_{\t{\beta_i}} \t{C} \h{C}^{-1} $ for $ i=1,...,g_1$, equation (\ref{com}) can be rewritten as:
    $$ \prod_{i=1}^{\t{g}} \left[ M_{\alpha_i}, M_{\beta_i} \right] \prod_{i=1}^{\h{g}} \left[ M_{\h\alpha_i}, M_{\h\beta_i} \right] =\mathbb{I}_2  $$
   Now, defining  $ M_{\alpha_{i+\t{g}}} = M_{\h{\alpha_i}} $ and $M_{\beta_{i+\t{g}}}=M_{\h{\beta_i}}$ for $i =1,..., \h{g} $, this last identity can be rewritten:
    $$ \prod_{i=1}^{\t{g}} \left[ M_{\alpha_i}, M_{\beta_i} \right] \prod_{i=\t{g}+1}^{\t{g}+\h{g}} \left[ M_{\alpha_i}, M_{\beta_i} \right] =\mathbb{I}_2 $$
    which coincides with   (\ref{repcl}).
\end{proof}

