One can verify that the local monodromies around all four vertices are trivial. Consider, for example, $\t{v}$ and $\t{q}$ (the computation at $\h{v}$ and $\h{q}$ is identical).

For $\t{q}$: Let us choose the cilium position to be between the edge $\tilde{e}=[\t{v}, \t{q}]$ and the half edge corresponding to $ \t{\g} $ with the same orientation as $ -\tilde{e}$. Then we have $ J(e_1)=M_{\t{\g}}$, $ J(e_2)=\t{C}$, $ J(e_3)=\Lambda^{-1}$ and 
 $ J(e_4)=\t{C}^{-1}$. Then $$ J(e_1)J(e_2)J(e_3)J(e_4)=M_{\t{\g}} \t{C} \Lambda^{-1} \t{C}^{-1}=M_{\t{\g}}M_{\t{\g}}^{-1}=\Id\;.$$

For $ \t{v}$: Let us choose the cilium position between the edge $\tilde{e}$ and the half edge  corresponding to $ \tilde{\beta}_1$ with the same orientation as $ -\tilde{e} $. Then 
$$ 
J(e_1)=M_{\t{\alpha}_1}\;, \hskip0.7cm J(e_2) = M_{\t{\beta}_1}^{-1} \;, \hskip0.7cm
J(e_3)=M_{\t{\alpha}_1}^{-1}  \;, \hskip0.7cm   J(e_4)=M_{\t{\beta}_1}\;,
$$ 
$$
 J(e_5)=M_{\t{\alpha}_2},\hskip0.7cm  \dots, \hskip0.7cm J(e_{4 \t{g}+1})=J( \tilde{e})=M_{\t{\g}}^{-1}\;.$$ 
 Therefore 
$$ \prod_{i=1}^{4\t{g}+1} J(e_i)= \prod_{i=1}^{\t{g}}\left[ M_{\t{\alpha}_i}, M_{\t{\beta}_i} \right] M_{\t{\g}}^{-1} = \Id\;. $$

The graph $ \Gamma_1$ can be transformed into the standard graph $ \Gamma_0$ by a sequence of admissible moves in the sense of \cite{bertola2023extended}:
\begin{enumerate}
    \item Merge the vertices $ \t{v}$ with $\t{q}$ and $ \h{v}$ with $ \h{q}$.\\
    \item Merge the vertices $ \t{q}$ and $ \h{q}$.\\
    \item Zip the two edges $ \t{\g}$ and $ \h{\g}$ whose jump matrices are $ \t{C}^{-1} $ and $ \h{C}$ to get a single edge $ \gamma$ with jump matrix $ J(\gamma)=\t{C}^{-1} \h{C}$.\\
    \item Zip the edge $ \gamma$ with the edges $ \{ \tilde{\alpha}_i, \tilde{\beta}_i \}_{i=1}^{\t{g}}$ to get edges $ \{ \alpha_i, \beta_i \}_{i=1}^{\t{g}}$ with corresponding jump matrices: $$ J(\beta_i)= M_{\alpha_i} = \h{C} \t{C}^{-1} \Mt_{\alpha_i} \t{C} \h{C}^{-1} \quad J(\alpha_i)= M_{\beta_i} = \h{C} \t{C}^{-1}  \Mt_{\beta_i} \t{C} \h{C}^{-1}, \quad  i=1,...,\t{g}.$$
\end{enumerate}
Therefore, the canonical symplectic form $ \Omega_{\Gamma_1}$ associated to $ (\Gamma_1) $ coincides with the canonical symplectic form $ \Omega_(\Gamma_0)$ associated to $ (\Gamma_0, J) $. In other words, one can use the graph $ \Gamma_1$ to compute the Goldman  symplectic form on $V_g $. 

In the next section we construct another graph $\Gamma_{2}$ which can also be transformed to $\Gamma_1$ by a sequence of standard moves; the jump 
matrices on edges of $\Gamma_{2}$ will be expressed in terms of Fock-Goncharov coordinates, and, therefore, can be used to write  
$\Omega$ in the log-canonical form.

\section{Triangulation of $\Ct$ and $\Ch$ and log-canonical  coordinates}



\subsection{Graph $\Gamma_2$ from triangulations of $\Ct$ and $\Ch$}

For explicit computation of the Weil-Petersson form in terms of  log-canonical coordinates we are going to construct one more graph on $\Ccal$, which we denote by $\Gamma_2$, with jump matrices on its edges 
which make it equivalent to $\Gamma_1$ and $\Gamma_0$.  

%First we are going to construct another graph on $\Ccal$, which we denote by $\Gamma_2$ and the jump matrices on its edges. On one hand, $\Gamma_2$, as we are going to see in the sequel, can be transformed to $\Gamma_1$ (and, in turn, to $\Gamma_0$) by standard moves, and, therefore, the standard form 
%$\Omega(\Gamma_2)$ is going to coincide with the Weil-Petersson form. On the other hand, $\Omega(\Gamma_2)$ admits an explicit computation leading to the set of log-canonical coordinates.


The graph $\Gamma_2$ and jump matrices on its edges are  constructed via amalgamation of the following three graphs
\begin{enumerate}
    \item 
    Graph $\t\Gamma_2$ constructed as follows.
    Fix an oriented    triangulation (i.e. such that an  orientation is  assigned to each edge)  $ \tilde{\Sigma} $ of $\t{\Ccal}$ with a single vertex $ \t{v}$ such that the boundary $\gamma$ and contour $\t q$ fall into one of the triangles. 
    The number of edges of $ \tilde{\Sigma} $ equals $ 6 \t{g}-3$. The jump matrices on  edges $\t e_j$ of  $ \tilde{\Sigma} $ are chosen as follows

    $$ 
    J(\t e_j)=\tilde{S}_{\t e_j}= \begin{pmatrix}
    0 & 1/ \t{z}_i \\
    -\t{z}_i & 0 \\
    \end{pmatrix}, \quad \t{z}_i \in \C
    $$   
    Notice that $ S_{\t e_i}^{-1}=    -S_{\t e_i} =  S_{-\t e_i}$. We also denote 
    $$ \t{\zeta}_j = \ln{ \t{z}_j}$$
     for $ j=1,..., 6\t{g}-3$.

   Choose on each face $\t F_k$ of  $ \tilde{\Sigma} $ an extra internal vertex $ \t{w}_k$ connected to $ \t{v}$ by three internal edges oriented toward $ \t{w}$.
   To each internal edge (shown in red in Fig.\ref{Graph2} and Fig.\ref{flatpic}) assign  the constant jump matrix: 
    $$ 
    A = \begin{pmatrix}
    0 & -1 \\
    1 & -1 \\
\end{pmatrix}
$$       


    \item
  Graph $\h\Gamma_2$ constructed as follows.  
     Fix an oriented triangulation $ \hat{\Sigma} $ of $\h{\Ccal}$ with a single vertex $ \h{v}$ such that the boundary $\gamma$ and contour $\h q$ fall into one of the triangles.
    The number of edges of $ \h{\Sigma} $ equals $ 6 \h{g}-3$. The jump matrices on  edges $\h e_j$ of  $ \h{\Sigma} $ are chosen as follows
$$ 
J(\h e_i)=\hat{S}_{\h e_i}= \begin{pmatrix}
    0 & 1/\h{z}_i \\
    -\h{z}_i & 0 \\
    \end{pmatrix}, \quad\ \h{z}_i \in \C
    $$ and denote $ \h{\zeta}_i = \ln{\h{z}_i}$, for $ i=1,..., 6 \h{g}-3$.
    Introduce on each face  of $ \hat{\Sigma} $ a point $ \h{w}_k$ together with three internal edges linking it to $\h{v}$. Assign the jump matrix $A$ to each of these internal edges.

The  variables $\h{\zeta}$ and $\t{\zeta}$ are assumed to satisfy the constraint
    \be
    \sum_{j=1}^{6 \t{g}-3}  \t \zeta_j   +  \sum_{j=1}^{6 \h{g}-3} \h \zeta_j=0
    \la{zetazeta}
    \ee
    or, equivalently,
    \be
    \prod_{j=1}^{6 \t{g}-3}  \t z_j \prod_{j=1}^{6 \h{g}-3}  \h z_j =1\;.
    \la{zz}
    \ee


   \item The "plumbing" 4-vertex graph part   $ \Gamma_{pl}$ remains the same while the jump matrices on its edges 
   are defined from the variables $\t \zeta_j$ and $\h \zeta_j$ as follows.


   The monodromy matrix $ M_{\t{\g}}$ (which is also the jump matrix   $ J([\t{v}, \t{q}])$ on $ \Gamma_{pl}$) can be computed as follows and turns out to be  lower-triangular
    $$ 
    M_{\t{\g}} := \left( \prod_{l=1}^{n_{\t{v}}} A \tilde{S}_{e_l} \right)^{-1}= \begin{pmatrix}
    \lambda_{\t{\g}} & 0 \\
    * &  \lambda_{\t{\g}}^{-1} \end{pmatrix}\;.
    $$
    where
    \be
    \lambda_{\t{\g}}= \prod_{j=1}^{6 \t{g}-3}  \t z^2_j 
    \la{deflt}
    \ee



    Choose the  special  matrix $\t C$ of eigenvectors of  $M_{\t{\g}}$ having the form
    $$
    \t C=\begin{pmatrix}
    1 & 0 \\
    * & 1 \end{pmatrix}\;.
$$
 Then the general    $ SL(2, \R) $ matrix $ \t{\Cp} $ diagonalizing $ M_{\t{\g}}$ (such that $ M_{\t{\g}} = \t{\Cp} \t{\Lambda} \t{\Cp}^{-1}$) has the form
    \be
     \t{\Cp}= \t{C}  \begin{pmatrix}
    \t b^{-1} & 0 \\
    0 & \t b\end{pmatrix} 
    \la{CCt}\ee
    where real number $\t b\neq 0$ is called the toric variable.  The corresponding logarithmic coordinate is denoted $ \t{\beta}=\ln{\t{b}}$.

    Similarly, we define  the matrix
    $$ 
    M_{\h{\g}} := \left( \prod_{l=1}^{n_{\h{v}}} A \tilde{S}_{\h e_l} \right)^{-1}= \begin{pmatrix}
    \lambda_{\h{\g}} & 0 \\
    * &  \lambda_{\h{\g}}^{-1} \end{pmatrix}\;.
    $$
    with
    \be
    \lambda_{\h{\g}}= \prod_{j=1}^{6 \h{g}-3}  \h z^2_j \;,
    \la{deflt}
    \ee
    the matrix $\h C$ of the form 
    $$
    \h C =\begin{pmatrix}
    1 & 0 \\
    * & 1 \end{pmatrix}\;.
    $$
    and the general matrix diagonalizing $M_{\h{\g}} $ of the form 
     \be
     \h{\Cp}= \h{C}  \begin{pmatrix}
    \h b^{-1} & 0 \\
    0 & \h b\end{pmatrix} 
    \la{CCh}\ee
    where $\h b$ is another toric variable; we denote $\h \beta=\ln \h b$.


\end{enumerate}
Notice that the  necessary condition 
$$
 \lambda_{\h{\g}}= \lambda_{\t{\g}}^{-1}
$$
is  the corollary of the constraint (\ref{zetazeta}).

In the sequel we shall  drop the tilde and denote 
$$
\lambda_{\t{\g}}= \lambda_{\g}\;,\hskip0.7cm \lambda_{\h{\g}}= \lambda_{\g}^{-1}
   $$ 
   Define also 
   $$
   \len_\g = \ln \lambda_{\g}\;.
   $$



