%\section{Proof of Theorem \ref{maintheo}}


%We are now in a position to give a proof of Theorem \ref{maintheo}. This proof is by direct computation of $ \Omega_{\Gcal_1}$ using (\ref{OmegaG}).

The graph $ \Gcal_2 $ can be transformed into the graph $ \Gcal_1$ by the following sequence of standard moves:
\begin{enumerate}
    \item First, merge  the  internal vertices $ \t{w}_k$ with $ \t{v}$ and $ \h{w}_k $ with $ \h{v}$.
    \item Second, zip together the edges with jump matrices $ A$ and the edges with jump matrices $ \t{S}_{e_i}$ (resp. $ \h{S}_{e_i}$) to get edges with jump matrices $ A \t{S}_{e_i} $ or $ A^{-1} \t{S}_{e_i}$ (resp. $ A \h{S}_{e_i} $ or $ A^{-1} \h{S}_{e_i}$)
    \item Third, zip together  the edges of the triangulations $ \tilde{\Sigma} $ and $ \hat{\Sigma} $ to get  the set of edges $ \{ \t{\alpha}_i, \t{\beta}_i \}_{i=1}^{\t{g}}$ and  $ \{ \h{\alpha}_i, \h{\beta}_i \}_{i=1}^{\h{g}}$. The jump matrices 
    \be
    M_{\t{\alpha}_j}\;, \hskip0.5cm M_{\t{\beta}_j}\;, \hskip0.5cm M_{\h{\alpha}_j}\;, \hskip0.5cm  M_{\h{\beta}_j}
 \la{MMM}\ee
    on these new edges %(i.e. the monodromy matrices of the Fuchsian representation of $\Ccal$) 
    become then 
    some products of $ \t{S}_{e_i} $ $  \h{S}_{e_i} $, $A$ and $A^{-1}$. 
\end{enumerate}



The  Fuchsian monodromy matrices $M_{\alpha_j}$, $ \hskip0.5cm M_{\beta_j}$ can be obtained from matrices (\ref{MMM}) using formulas (\ref{monC}) with $\h C$ and $\t C$ replaced by the general diagonalizing matrices $ \t{\Cp}$ and $ \h{\Cp}$ (\ref{CCt}) and (\ref{CCh}).

The  matrix 
\be
 \t{\Cp}^{-1} \h{\Cp}= \t C \begin{pmatrix}
    \t b /\h b & 0 \\
    0 & \h b/\t b   \end{pmatrix} 
\ee
%[COMMENT : ISN'T IT $  \t{\Cp}^{-1} \h{\Cp}$ ???]
depends only on the ratio of the toric variables; thus the fuchsian monodromies depend only on the difference of their logarithms and we can define the new variable
\be
\beta_\g=\t\beta- \h\beta\;.
\la{betadef}
\ee

Notice that the variables $\t\zeta_j$ and $\h \zeta_j$ are not independent but satisfy the constraint (\ref{zetazeta}).
The independent set of variables can be chosen as follows:
\be
\left\{\{\t\zeta\}_{i=2}^{\nt},\, \{\zh_i\}_{i=2}^{\nh}, \len_\gamma, \beta_\gamma\right\}\;.
\la{coo2}\ee
Then the remaining coordinates $\zt_1$ and $\zh_1$ can be obtained from the logarithmic version of (\ref{deflt}):
\be \la{cons2}
\t\zeta_1= \f{1}{2} \len_\gamma -\sum_{j=2}^{6 \t{g}-3}  \t\zeta_j\;,\hskip0.7cm
\zh_1= -\f{1}{2} \len_\gamma -\sum_{j=2}^{6 \h{g}-3}  \zh_j
\ee


\section{Computation of Weil-Petersson form as $ \Omega(\Gcal_2) $}

We are in a position to state our main theorem.
\begin{theo}
The Goldman  form  $\Omega$ on $V_g$ has constant coefficients in terms of variables (\ref{coo2}) i.e. these variables are log-canonical for $\Omega$.
Namely, we have 
\be
  \Omega=\Omega_{0}+ \t{\Omega}_{1}+\h{\Omega}_{1}+ \t{\Omega}_{2}+ \h{\Omega}_{2}
  \la{WPint1}
  \ee
where 
\be
\Omega_0=2\mathrm{d}\len_\gamma \wedge \mathrm{d}\beta_\gamma\;,
\la{ltint1}
\ee
\be
 \t{\Omega}_1= \sum_{\substack{i,j=2 \\ i<j} }^{6g_1-3} \left(\t c_{ij}-\t c_{1j}+\t c_{1i} \right)\mathrm{d}\zt_i\wedge \mathrm{d} \zt_j\;,\hskip0.7cm
\h{\Omega}_1=\sum_{\substack{k,l=2 \\ k<l} }^{6g_2-3} \left( \h c_{kl}-\h c_{1l}+\h c_{1k}\right) \mathrm{d}\zh_k \wedge \mathrm{d}\zh_l;,
\la{ossint1}
\ee
\be
 \t{\Omega}_2=\frac{1}{2} \sum_{m=2}^{6g_1-3} \h c_{1m}  \mathrm{d}\len_\gamma \wedge \mathrm{d}\zt_m\;,\hskip0.7cm
 \h{\Omega}_2=\frac{1}{2} \sum_{n=2}^{6g_2-3} \h c_{1n} \mathrm{d}\len_\gamma \wedge \mathrm{d}\zh_n\;,
\la{ostint1}
\ee

\vskip0.5cm
 The integer coefficients $ \t c_{ij}$, $\h c_{kl} $ lie  in the interval between $-4$ and $4$. They are determined by the 
order of  the edges of the uni-valent graphs $\t\Gamma$ and $\h\Gamma$ at there vertices. 

\end{theo}
\begin{proof}
The symplectic form $ \Omega({\Gcal_2}) $ can be  computed using the general formula (\ref{OmegaG}) by summing the contributions of all  four vertices $ \t{v}$, $ \h{v}$, $ \t{q}$ and $ \h{q}$ of the graph $ \Gcal_2$.  

The contributions coming from the vertices $ \t{v}$ and $ \h{v}$ are given by the following lemma:
\begin{lemma}
    The contribution of the vertex $\t{q}$  to  $ \Omega({\Gcal_2}) $   equals to $ \Omega_{\t{q}}=-2\mathrm{d}\t{\beta} \wedge \mathrm{d}\len_\gamma  $ and the contribution of the vertex  $\h{q}$  equals to $ \Omega_{\h{q}} =2\mathrm{d}\h{\beta} \wedge \mathrm{d}\len_\gamma$.
\end{lemma}

    Choose the cilium position to be between the edge $[\t{v}, \t{q}]$ and the half edge corresponding to $ \t{\gamma} $ with the same orientation as $ [\t{v}, \t{q}]$. The four edges incident to $ \t{q} $ in counterclockwise order have jump matrices: $ J(e_1) =J_1= M_{\t{\g}}$, $ J(e_2)=J_2 = \t{\Cp}$, $ J(e_3)=J_3 = \Lambda^{-1} $ and $ J(e_4)=J_4=\t{\Cp}^{-1}$. 

    According to equation (\ref{OmegaG})  the contribution of  $ q_1$ to $\Omega ({\Gcal_2}) $ reads:
    \begin{align*}
        \Omega_{\t{q}}&=\frac{1}{2}\sum_{l=1}^{3} \mathrm{tr}( J_{[1...l]}^{-1} \d J_{[1...l]} \wedge J_{l}^{-1} \d J_{l} )\\
        &= \frac{1}{2}\mathrm{tr}\left( (J_1 J_2)^{-1} \d(J_1 J_2) \wedge  J_2^{-1} \d J_2 \right) + \frac{1}{2} \mathrm{tr}\left( (J_1 J_2 J_3)^{-1} \d (J_1 J_2 J_3) \wedge J_3^{-1} \d J_3 \right) \\
        &= \frac{1}{2} \mathrm{tr}\left( ( M_{\t{\g}} \t{\Cp})^{-1} \d ( M_{\t{\g}} \t{\Cp}) \wedge \t{\Cp}^{-1}  \d \t{\Cp} \right) +\frac{1}{2}\mathrm{tr}\left( ( M_{\t{\g}} \t{\Cp} \Lambda^{-1})^{-1} \d ( M_{\t{\g}} \t{\Cp} \Lambda^{-1})  \wedge \Lambda  \d (\Lambda^{-1})\right) \\
        &= \frac{1}{2} \mathrm{tr}\left( M_{\t{\g}}^{-1} \d M_{\t{\g}} \wedge \t{\Cp}^{-1} \d \t{\Cp} \right)+ \frac{1}{2} \mathrm{tr}\left( \Lambda^{-1} \d \Lambda \wedge  M_{\t{\g}}^{-1} \d  M_{\t{\g}} \right) + \frac{1}{2} \mathrm{tr}\left( \Lambda^{-1} \d \Lambda \wedge \t{\Cp}^{-1} \d \t{\Cp} \right).
    \end{align*} 

    Using the identity  $M_{\t{\g}}^{-1} \d M_{\t{\g}} = \t{\Cp} \Lambda^{-1} \t{\Cp}^{-1} \d \Lambda $ we see that the second term is equal to zero, and the first term is equal to the last one, so the contribution $ \Omega_{\t{q}} $ simplifies to:
   $$ \Omega_{\t{q}} =  \mathrm{tr}\left( \Lambda^{-1} \d \Lambda \wedge \t{\Cp}^{-1} \d  \t{\Cp} \right)\;.$$ 
  Using the definition (\ref{CCt}) of  $  \t{\Cp}$
  we get:
$$ \Omega_{\t{q}}=\mathrm{tr}\left( \Lambda^{-1} \d \Lambda \wedge \t{\Cp}^{-1}  \d \t{\Cp} \right) = -2 \frac{\mathrm{d}\lambda_\gamma}{\lambda_\gamma} \wedge \frac{\mathrm{d} \t{b}}{\t{b}}=2 \mathrm{d}\t{\beta} \wedge \mathrm{d}\len_\gamma$$
  Similarly,
   $$ \Omega_{\h{q}}=2\frac{\mathrm{d}\lambda_\gamma}{\lambda_\gamma} \wedge \frac{\mathrm{d}\h{b}}{\h{b}}= -2 \mathrm{d}\h{\beta} \wedge \mathrm{d}\len_\gamma.$$
\end{proof}

To compute  the contributions of the vertex $ \t{v}$ we can use the result of \cite{bertola2023extended} which states that 
   $$ 
   \Omega_{\t{v}}= \sum_{\substack{i,j=1 \\ e_i <e_j}}^{2(6\t{g}-3)} \mathrm{d} \t{\zeta}_i \wedge \mathrm{d} \t{\zeta}_j 
   $$
   where each edge comes to $\t{v}$ twice. Eliminating repetitions of similar terms we get
   \be
    \label{omint} 
    \Omega_{\t{v}}=\sum_{\substack{i,j=1 \\ i <j}}^{6\t{g}-3} \t{c}_{ij} \mathrm{d}\t{\zeta}_i \wedge \mathrm{d} \t{\zeta}_j 
    \ee
where $ \t{c}_{ij}$ are some (depending on the order of the edges at the vertex) integers from the range  $ \{ -4,...,4 \}$.

Similarly, 
$$
\Omega_{\h{v}}=\sum_{\substack{k,l=1 \\ k <l}}^{6\h{g}-3} \h{c}_{kl} \mathrm{d}\h{\zeta}_k \wedge \mathrm{d} \h{\zeta}_l 
$$
where $\h{c}_{kl} $ are also some integers from  the same set $ \{ -4,...,4 \}$.


 If one eliminates $\t\zeta_1$ and $\h\zeta_1$ using the constraints (\ref{cons2}) we get also


    \begin{equation}
        \begin{split}
           \Omega_{\t{v}} &= \sum_{\substack{i,j=2 \\ i<j} }^{6 \t{g}-3} \left( \t{c}_{ij}-\t{c}_{1j}+\t{c}_{1i} \right) \mathrm{d}\t{\zeta}_i \wedge \mathrm{d}\t{\zeta}_j+\frac{1}{2} \sum_{m=2}^{6\t{g}-3} \t{c}_{1m}  \mathrm{d} \len_{\gamma} \wedge \mathrm{d}\t{\zeta}_m \\
           \Omega_{\h{v}} &= \sum_{\substack{k,l=2 \\ k<l} }^{6 \h{g}-3} \left( \h{c}_{kl}-\h{c}_{1l}+\h{c}_{1k}\right) \mathrm{d}\h{\zeta}_k \wedge \mathrm{d}\h{\zeta}_l
            +\frac{1}{2} \sum_{n=2}^{6 \h{g}-3} \h{c}_{1n} \mathrm{d}\len_\gamma \wedge \mathrm{d}\h{\zeta}_n
        \end{split}
    \end{equation}

Summing up  the contributions of all four vertices to $\Omega(\Gamma_2)$ we get  (\ref{WPint1}).

\section{Any number of cuts and higher $SL(N)$ groups}

Here we discuss two possible generalizations of the construction given above.

\subsection{Higher  $SL(N)$ groups}

The generalization of our construction  to an arbitrary $SL(N)$ character variety (in both complex and real cases) of $\pi_1(\Ccal)$ for compact genus $g$ Riemann surfaces is pretty straightforward if one uses the system of 
higher rank Fock-Goncharov coordinates \cite{fock2006moduli}. Technically, in the higher $SL(N)$ case the matrices $S_e$ become anti-diagonal; each such matrix contains $N-1$ coordinates while matrices 
$A$ also contain some of coordinates (one coordinate for $SL(3)$ case, there for $SL(4)$ etc) \cite{bertola2023extended}. The logarithms of eigenvalues of the monodromy matrices around the separating loop 
and logarithms of the ratios of the corresponding toric variables form an additional set of $N-1$ conjugated pairs of coordinates for the Goldman symplectic form.
The technical details for an arbitrary $SL(N)$ case are very similar to \cite{bertola2023extended}.


\subsection{Multiple cuts}

%Another generalization of this construction is an extension to an arbitrary number of cuts on $\Ccal$ between $1$ and $3g-3$.
%Essentially, we can define a system of log-canonical coordinates to an arbitrary component of the Deligne-Mumford boundary.

A system of log-canonical coordinates generalizing (\ref{coo1}) can be naturally associated to any system of $m$ closed non-intersecting geodesics $\gamma_1,\dots \gamma_m$  for any $m=1,\dots, 3g-3$.
These contours split $\Ccal$ into one or more Riemann surfaces with boundaries which we denote by $\Ccal^{(1)},\dots\Ccal^{(n)}$.
Denote  the number of boundary components of $\Ccal^{(i)}$ by $k^{(i)}$ and the genus by $g^{(i)}$; we have $\sum_{i=1}^n k^{(i)}= 2m$.

Then one can choose two  point $v_k^\pm $ near the opposite sides of the curve $\gamma_k$. Consider now a graph $\Gamma^{(i)}$ with $k^{(i)}$ vertices  $v_j^\pm\in\Ccal^{(i)} $ which provides triangulation of each $\Ccal^{(i)}$ if the boundary components shrinks to a point.
The number of edges of $\Gamma^{(i)}$ equals $6g^{(i)}-6+3 k^{(i)}$ which coincides with the dimension of the moduli space of Riemann surfaces of genus $g_i$ with $k^{(i)}$ boundary components of variable length.
We associate complex shear coordinates $\zeta_j^{(i)}$, $j=1,\dots, 6g^{(i)}-5+2 k^{(i)}$ to the edges of $\Gamma^{(i)}$; for each $e\in \Gamma^{(i)}$ we denote the coordinate by $\zeta(e)$.


There are $m$ constraints relating the oriented lengths $\len_k$ of $\gamma_k$ to $\zeta_j^{(i)}$:
\be
\sum_{e\in E(\Gamma^{(i)}),\; e\perp v_k} \zeta(e)=\pm \len_k\;,\hskip0.7cm k=1,\dots m
\la{constr1}\ee
where some terms in the left hand side come with coefficient 1, and other terms with coefficient  2. The signs in the right hand side should be chosen such that on the opposite sides 
of the same contour $\gamma_k$ the signs are different.

The system of constraints (\ref{constr1}) is linear in terms of $\zeta(e)$. 
 The  system of log-canonical coordinates contains the lengths $\len_k$ for $k=1,\dots,m$ and the variables $\zeta(e)$ except the ones which can be expresses in terms of $\lambda_k$ and the remaining $\zeta(e)$ using the 
 constraints  (\ref{constr1}).

Then the Goldman  form can be represented as
$$
\Omega=\sum_{i=1}^n \Omega^{(i)} +2\sum_{j=1}^m d\len_l \wedge d\beta_j
$$
where
$$
\Omega^{(i)}=\sum_{v\in V(\Gamma^{(i)})}\sum_{e,\ e'\perp v,\;\; \tilde{e}<e} d\zeta(e)\wedge d \zeta(e')
$$
(notice that in the last sum some terms repeat, and also some coordinates $\zeta(e)$ should be expressed by a linear combination of the remaining ones and $\len_j$
In the case of maximal number of cycles $m=3g-3$ one gets the complete pants decomposition of $\Ccal$, when each $\Ccal^{(i)}$ is a trinion i.e. the sphere with three holes and $n=2g-2$.
Then  the form $\Omega$ can be written as 
\be
\Omega=2\sum_{j=1}^{3g-3} d\len_{\g_j} \wedge d\beta_{\g_j} +\sum_{i=1}^{2g-2} \sum_{\g,\g'\in \partial \Ccal^{(i)}} d\len_\g\wedge d\len_{\g'}
 \la{Opants}\ee
 where the last sum is over three boundary components of $\Ccal^{(i)}$. 

The formula (\ref{Opants}) resembles the Wolpert's formula 
\begin{equation}\label{omegaWP}
    \Omega = \sum_{j=1}^{3g-3} \mathrm{d} \len_{\gamma_j} \wedge \mathrm{d}\varphi_{\gamma_j} 
\end{equation} 
 is terms of (complexified) Fenchel-Nielsen coordinates.
In fact, the angles $\beta_j$ differ from the canonical Fenchel-Nielsen angles $\varphi_{\gamma_j}$ by addition of certain combinations of $\len_j$'s. 

The complete construction based on multiple cuts will be presented elsewhere.

